@Test
public void testIn() {
    assertThat(in("s", 7, 8, 9).literals()).hasSize(3);
    assertThat(in("s", 7, 8.1, Long.MAX_VALUE).literals()).hasSize(3);
    assertThat(in("s", "abc", "abd", "abc").literals()).hasSize(3);
    assertThat(in("s").literals()).isEmpty();
    assertThat(in("s", 5).literals()).hasSize(1);
    assertThat(in("s", 5, 5).literals()).hasSize(2);
    assertThat(in("s", Arrays.asList(5, 5)).literals()).hasSize(2);
    assertThat(in("s", Collections.emptyList()).literals()).isEmpty();
    Evaluator evaluator = new Evaluator(STRUCT, in("x", 7, 8, Long.MAX_VALUE));
    assertThat(evaluator.eval(TestHelpers.Row.of(7, 8, null))).as("7 in [7, 8] => true").isTrue();
    assertThat(evaluator.eval(TestHelpers.Row.of(9, 8, null))).as("9 in [7, 8]  => false").isFalse();
    Evaluator intSetEvaluator = new Evaluator(STRUCT, in("x", Long.MAX_VALUE, Integer.MAX_VALUE, Long.MIN_VALUE));
    assertThat(intSetEvaluator.eval(TestHelpers.Row.of(Integer.MAX_VALUE, 7.0, null))).as("Integer.MAX_VALUE in [Integer.MAX_VALUE] => true").isTrue();
    assertThat(intSetEvaluator.eval(TestHelpers.Row.of(6, 6.8, null))).as("6 in [Integer.MAX_VALUE]  => false").isFalse();
    Evaluator integerEvaluator = new Evaluator(STRUCT, in("y", 7, 8, 9.1));
    assertThat(integerEvaluator.eval(TestHelpers.Row.of(0, 7.0, null))).as("7.0 in [7, 8, 9.1] => true").isTrue();
    assertThat(integerEvaluator.eval(TestHelpers.Row.of(7, 9.1, null))).as("9.1 in [7, 8, 9.1] => true").isTrue();
    assertThat(integerEvaluator.eval(TestHelpers.Row.of(6, 6.8, null))).as("6.8 in [7, 8, 9.1]  => false").isFalse();
    Evaluator structEvaluator = new Evaluator(STRUCT, in("s1.s2.s3.s4.i", 7, 8, 9));
    assertThat(structEvaluator.eval(TestHelpers.Row.of(7, 8, null, TestHelpers.Row.of(TestHelpers.Row.of(TestHelpers.Row.of(TestHelpers.Row.of(7))))))).as("7 in [7, 8, 9] => true").isTrue();
    assertThat(structEvaluator.eval(TestHelpers.Row.of(6, 8, null, TestHelpers.Row.of(TestHelpers.Row.of(TestHelpers.Row.of(TestHelpers.Row.of(6))))))).as("6 in [7, 8, 9]  => false").isFalse();
    StructType charSeqStruct = StructType.of(required(34, "s", Types.StringType.get()));
    Evaluator charSeqEvaluator = new Evaluator(charSeqStruct, in("s", "abc", "abd", "abc"));
    assertThat(charSeqEvaluator.eval(TestHelpers.Row.of(new Utf8("abc")))).as("utf8(abc) in [string(abc), string(abd)] => true").isTrue();
    assertThat(charSeqEvaluator.eval(TestHelpers.Row.of(new Utf8("abcd")))).as("utf8(abcd) in [string(abc), string(abd)] => false").isFalse();
}

@Test
public void testInExceptions() {
    Assertions.assertThatThrownBy(() -> in("x", (Literal) null)).isInstanceOf(NullPointerException.class).hasMessage("Cannot create expression literal from null");
    Assertions.assertThatThrownBy(() -> in("x", (Collection<?>) null)).isInstanceOf(NullPointerException.class).hasMessage("Values cannot be null for IN predicate.");
    Assertions.assertThatThrownBy(() -> in("x", 5, 6).literal()).isInstanceOf(IllegalArgumentException.class).hasMessage("IN predicate cannot return a literal");
    Assertions.assertThatThrownBy(() -> in("x", 1, 2, null)).isInstanceOf(NullPointerException.class).hasMessage("Cannot create expression literal from null");
    Assertions.assertThatThrownBy(() -> new Evaluator(STRUCT, in("x", 7, 8, 9.1))).isInstanceOf(ValidationException.class).hasMessageContaining("Invalid value for conversion to type int");
    Assertions.assertThatThrownBy(() -> predicate(Expression.Operation.IN, "x")).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot create IN predicate without a value");
    Assertions.assertThatThrownBy(() -> new Evaluator(STRUCT, predicate(Expression.Operation.IN, "x", 5.1))).isInstanceOf(ValidationException.class).hasMessageContaining("Invalid value for conversion to type int");
}

