@Test
public void testFloatNaN() {
    double canonicalNaN = Double.longBitsToDouble(0x7ff8000000000000L);
    // All bit patterns in the range 0x7f800001 to 0x7fffffff
    // and 0xff800001 to 0xffffffff are considered NaNs.
    float[] testNaNs = { Float.NaN, Float.intBitsToFloat(0x7f800001), Float.intBitsToFloat(0x7f9abcde), Float.intBitsToFloat(0x7fedcba9), Float.intBitsToFloat(0x7fffffff), Float.intBitsToFloat(0xff800001), Float.intBitsToFloat(0xff9abcde), Float.intBitsToFloat(0xffedcba9), Float.intBitsToFloat(0xffffffff) };
    for (float value : testNaNs) {
        assertThat(Float.isNaN(value)).as("Bit pattern is expected to be NaN.").isTrue();
        assertThat(BucketUtil.hash(canonicalNaN)).as("All NaN representations should result in the same hash").isEqualTo(BucketUtil.hash(value));
    }
}

