@Test
public void testStructWriteReordering() {
    // writes should not reorder fields
    Schema read = new Schema(required(0, "nested", Types.StructType.of(required(1, "field_a", Types.IntegerType.get()), required(2, "field_b", Types.IntegerType.get()))));
    Schema write = new Schema(required(0, "nested", Types.StructType.of(required(2, "field_b", Types.IntegerType.get()), required(1, "field_a", Types.IntegerType.get()))));
