@Test
public void testRetainAll() {
    CharSequenceSet set = CharSequenceSet.of(ImmutableList.of("123", "456"));
    Assertions.assertThat(set.retainAll(ImmutableList.of("456", "789", 123))).overridingErrorMessage("Set should be changed").isTrue();
    Assertions.assertThat(set).hasSize(1).contains("456");
    set = CharSequenceSet.of(ImmutableList.of("123", "456"));
    Assertions.assertThat(set.retainAll(ImmutableList.of("123", "456"))).overridingErrorMessage("Set should not be changed").isFalse();
    Assertions.assertThat(set.retainAll(ImmutableList.of(123, 456))).overridingErrorMessage("Set should be changed").isTrue();
    Assertions.assertThat(set).isEmpty();
}

@Test
public void testRemoveAll() {
    CharSequenceSet set = CharSequenceSet.of(ImmutableList.of("123", "456"));
    Assertions.assertThat(set.removeAll(ImmutableList.of("456", "789", 123))).overridingErrorMessage("Set should be changed").isTrue();
    Assertions.assertThat(set).hasSize(1).contains("123");
    set = CharSequenceSet.of(ImmutableList.of("123", "456"));
    Assertions.assertThat(set.removeAll(ImmutableList.of(123, 456))).overridingErrorMessage("Set should not be changed").isFalse();
