@Test
public void testAcquireMultiProcessAllSucceed() throws Exception {
    lockManager.initialize(ImmutableMap.of(CatalogProperties.LOCK_ACQUIRE_INTERVAL_MS, "500", CatalogProperties.LOCK_ACQUIRE_TIMEOUT_MS, "100000000", CatalogProperties.LOCK_TABLE, lockTableName));
    long start = System.currentTimeMillis();
    List<Boolean> results = POOL.submit(() -> IntStream.range(0, 16).parallel().mapToObj(i -> {
        DynamoDbLockManager threadLocalLockManager = new DynamoDbLockManager(dynamo, lockTableName);
        String owner = UUID.randomUUID().toString();
        boolean succeeded = threadLocalLockManager.acquire(entityId, owner);
        if (succeeded) {
            try {
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                throw new RuntimeException(e);
            }
            Assert.assertTrue(threadLocalLockManager.release(entityId, owner));
        }
        return succeeded;
    }).collect(Collectors.toList())).get();
    Assert.assertEquals("all lock acquire should succeed sequentially", 16, results.stream().filter(s -> s).count());
    Assert.assertTrue("must take more than 16 seconds", System.currentTimeMillis() - start >= 16000);
}

