    Schema writeSchema = new Schema(Types.NestedField.required(0, "id", Types.LongType.get()), Types.NestedField.optional(3, "location", Types.StructType.of(Types.NestedField.required(1, "lat", Types.FloatType.get()), Types.NestedField.required(2, "long", Types.FloatType.get()))));
    Record record = new Record(AvroSchemaUtil.convert(writeSchema, "table"));
    record.put("id", 34L);
    Record location = new Record(AvroSchemaUtil.fromOption(record.getSchema().getField("location").schema()));
    location.put("lat", 52.995143f);
    location.put("long", -1.539054f);
    record.put("location", location);
    Schema idOnly = new Schema(Types.NestedField.required(0, "id", Types.LongType.get()));
    Record projected = writeAndRead("id_only", writeSchema, idOnly, record);
    assertEmptyAvroField(projected, "location");
    Assertions.assertThat((long) projected.get("id")).as("Should contain the correct id value").isEqualTo(34L);
    Schema latOnly = new Schema(Types.NestedField.optional(3, "location", Types.StructType.of(Types.NestedField.required(1, "lat", Types.FloatType.get()))));
    projected = writeAndRead("latitude_only", writeSchema, latOnly, record);
    Record projectedLocation = (Record) projected.get("location");
    assertEmptyAvroField(projected, "id");
    Assertions.assertThat(projected.get("location")).as("Should project location").isNotNull();
    assertEmptyAvroField(projectedLocation, "long");
    Assertions.assertThat((Float) projectedLocation.get("lat")).as("Should project latitude").isCloseTo(52.995143f, Assertions.within(0.000001f));
    Schema longOnly = new Schema(Types.NestedField.optional(3, "location", Types.StructType.of(Types.NestedField.required(2, "long", Types.FloatType.get()))));
    projected = writeAndRead("longitude_only", writeSchema, longOnly, record);
    projectedLocation = (Record) projected.get("location");
    assertEmptyAvroField(projected, "id");
    Assertions.assertThat(projected.get("location")).as("Should project location").isNotNull();
    assertEmptyAvroField(projectedLocation, "lat");
    Assertions.assertThat((Float) projectedLocation.get("long")).as("Should project longitude").isCloseTo(-1.539054f, Assertions.within(0.000001f));
    Schema locationOnly = writeSchema.select("location");
    projected = writeAndRead("location_only", writeSchema, locationOnly, record);
    projectedLocation = (Record) projected.get("location");
    assertEmptyAvroField(projected, "id");
    Assertions.assertThat(projected.get("location")).as("Should project location").isNotNull();
    Assertions.assertThat((Float) projectedLocation.get("lat")).as("Should project latitude").isCloseTo(52.995143f, Assertions.within(0.000001f));
    Assertions.assertThat((Float) projectedLocation.get("long")).as("Should project longitude").isCloseTo(-1.539054f, Assertions.within(0.000001f));
}

