@Test
public void testListNamespaces() {
    C catalog = catalog();
    // the catalog may automatically create a default namespace
    List<Namespace> starting = catalog.listNamespaces();
    Namespace ns1 = Namespace.of("newdb_1");
    Namespace ns2 = Namespace.of("newdb_2");
    catalog.createNamespace(ns1);
    Assertions.assertThat(catalog.listNamespaces()).withFailMessage("Should include newdb_1").hasSameElementsAs(concat(starting, ns1));
    catalog.createNamespace(ns2);
    Assertions.assertThat(catalog.listNamespaces()).withFailMessage("Should include newdb_1 and newdb_2").hasSameElementsAs(concat(starting, ns1, ns2));
    catalog.dropNamespace(ns1);
    Assertions.assertThat(catalog.listNamespaces()).withFailMessage("Should include newdb_2, not newdb_1").hasSameElementsAs(concat(starting, ns2));
    catalog.dropNamespace(ns2);
    Assertions.assertThat(catalog.listNamespaces().containsAll(starting)).as("Should include only starting namespaces").isTrue();
}

@Test
public void testListNestedNamespaces() {
    Assumptions.assumeTrue(supportsNestedNamespaces(), "Only valid when the catalog supports nested namespaces");
    C catalog = catalog();
    // the catalog may automatically create a default namespace
    List<Namespace> starting = catalog.listNamespaces();
    Namespace parent = Namespace.of("parent");
    Namespace child1 = Namespace.of("parent", "child1");
    Namespace child2 = Namespace.of("parent", "child2");
    catalog.createNamespace(parent);
    Assertions.assertThat(catalog.listNamespaces()).withFailMessage("Should include parent").hasSameElementsAs(concat(starting, parent));
    Assertions.assertThat(catalog.listNamespaces(parent)).withFailMessage("Should have no children in newly created parent namespace").isEmpty();
    catalog.createNamespace(child1);
    Assertions.assertThat(catalog.listNamespaces(parent)).withFailMessage("Should include child1").hasSameElementsAs(ImmutableList.of(child1));
    catalog.createNamespace(child2);
    Assertions.assertThat(catalog.listNamespaces(parent)).withFailMessage("Should include child1 and child2").hasSameElementsAs(ImmutableList.of(child1, child2));
    Assertions.assertThat(catalog.listNamespaces()).withFailMessage("Should not change listing the root").hasSameElementsAs(concat(starting, parent));
    catalog.dropNamespace(child1);
    Assertions.assertThat(catalog.listNamespaces(parent)).withFailMessage("Should include only child2").hasSameElementsAs(ImmutableList.of(child2));
    catalog.dropNamespace(child2);
    Assertions.assertThat(catalog.listNamespaces(parent)).withFailMessage("Should be empty").isEmpty();
}

