    create.newFastAppend().appendFile(FILE_A).commit();
    UpdateSchema updateSchema = create.updateSchema().addColumn("new_col", Types.LongType.get());
    Schema newSchema = updateSchema.apply();
    updateSchema.commit();
    UpdatePartitionSpec updateSpec = create.updateSpec().addField("new_col");
    PartitionSpec newSpec = updateSpec.apply();
    updateSpec.commit();
    ReplaceSortOrder replaceSortOrder = create.replaceSortOrder().asc("new_col");
    SortOrder newSortOrder = replaceSortOrder.apply();
    replaceSortOrder.commit();
    DataFile anotherFile = DataFiles.builder(newSpec).withPath("/path/to/data-b.parquet").withFileSizeInBytes(10).withPartitionPath(// easy way to set partition data for now
    "id_bucket=0/new_col=0").withRecordCount(// needs at least one record or else metrics will filter it out
    2).build();
    create.newFastAppend().appendFile(anotherFile).commit();
    Assertions.assertThat(catalog.tableExists(TABLE)).as("Table should not exist after append commit").isFalse();
    create.commitTransaction();
    Assertions.assertThat(catalog.tableExists(TABLE)).as("Table should exist after append commit").isTrue();
    Table table = catalog.loadTable(TABLE);
    // initial IDs taken from TableMetadata constants
    final int initialSchemaId = 0;
    final int initialSpecId = 0;
    final int initialOrderId = 1;
    final int updateSchemaId = initialSchemaId + 1;
    final int updateSpecId = initialSpecId + 1;
    final int updateOrderId = initialOrderId + 1;
    Assertions.assertThat(table.schema().asStruct()).as("Table schema should match the new schema").isEqualTo(newSchema.asStruct());
    Assertions.assertThat(table.schema().schemaId()).as("Table schema should match the new schema ID").isEqualTo(updateSchemaId);
    Assertions.assertThat(table.spec().fields()).as("Table should have updated partition spec").isEqualTo(newSpec.fields());
    Assertions.assertThat(table.spec().specId()).as("Table should have updated partition spec ID").isEqualTo(updateSpecId);
    Assertions.assertThat(table.sortOrder().fields()).as("Table should have updated sort order").isEqualTo(newSortOrder.fields());
    Assertions.assertThat(table.sortOrder().orderId()).as("Table should have updated sort order ID").isEqualTo(updateOrderId);
    Assertions.assertThat(table.properties().entrySet()).as("Table properties should be a superset of the requested properties").containsAll(properties.entrySet());
    if (!overridesRequestedLocation()) {
        Assertions.assertThat(table.location()).as("Table location should match requested").isEqualTo("file:/tmp/ns/table");
    }
    assertFiles(table, FILE_A, anotherFile);
    assertFilePartitionSpec(table, FILE_A, initialSpecId);
