@Test
public void testUnpartitionedDeletes() {
    PartitionSpec partSpec = PartitionSpec.unpartitioned();
    DeleteFile[] deleteFiles = { withDataSequenceNumber(4, unpartitionedEqDeletes(partSpec)), withDataSequenceNumber(6, unpartitionedEqDeletes(partSpec)), withDataSequenceNumber(5, unpartitionedPosDeletes(partSpec)), withDataSequenceNumber(6, unpartitionedPosDeletes(partSpec)) };
    DeleteFileIndex index = DeleteFileIndex.builderFor(Arrays.asList(deleteFiles)).specsById(ImmutableMap.of(partSpec.specId(), partSpec, 1, SPEC)).build();
    DataFile unpartitionedFile = unpartitionedFile(partSpec);
    Assert.assertArrayEquals("All deletes should apply to seq 0", deleteFiles, index.forDataFile(0, unpartitionedFile));
    Assert.assertArrayEquals("All deletes should apply to seq 3", deleteFiles, index.forDataFile(3, unpartitionedFile));
    Assert.assertArrayEquals("Last 3 deletes should apply to seq 4", Arrays.copyOfRange(deleteFiles, 1, 4), index.forDataFile(4, unpartitionedFile));
    Assert.assertArrayEquals("Last 3 deletes should apply to seq 5", Arrays.copyOfRange(deleteFiles, 1, 4), index.forDataFile(5, unpartitionedFile));
    Assert.assertArrayEquals("Last delete should apply to seq 6", Arrays.copyOfRange(deleteFiles, 3, 4), index.forDataFile(6, unpartitionedFile));
    Assert.assertArrayEquals("No deletes should apply to seq 7", new DataFile[0], index.forDataFile(7, unpartitionedFile));
    Assert.assertArrayEquals("No deletes should apply to seq 10", new DataFile[0], index.forDataFile(10, unpartitionedFile));
    // copy file A with a different spec ID
    DataFile partitionedFileA = FILE_A.copy();
    ((BaseFile<?>) partitionedFileA).setSpecId(1);
    Assert.assertArrayEquals("All global equality deletes should apply to a partitioned file", Arrays.copyOfRange(deleteFiles, 0, 2), index.forDataFile(0, partitionedFileA));
}

