@ParameterizedTest
@ValueSource(ints = { 1, 2 })
public void testReplaceTxnBuilder(int formatVersion) {
    TableIdentifier tableIdent = TableIdentifier.of("db", "ns1", "ns2", "tbl");
    final DataFile fileA = DataFiles.builder(PARTITION_SPEC).withPath("/path/to/data-a.parquet").withFileSizeInBytes(0).withPartitionPath(// easy way to set partition data for now
