        table.newFastAppend().appendFile(DataFiles.builder(PartitionSpec.unpartitioned()).withPath(FileFormat.PARQUET.addExtension(UUID.randomUUID().toString())).withFileSizeInBytes(10).withRecordCount(2).build()).commit();
        try (CloseableIterable<FileScanTask> tasks = table.newScan().planFiles()) {
            Assertions.assertThat(tasks.iterator()).hasNext();
        }
    } finally {
        catalogWithCustomReporter.dropTable(TABLE);
    }
    // counter of custom metrics reporter should have been increased
    // 1x for commit metrics / 1x for scan metrics
    Assertions.assertThat(CustomMetricsReporter.COUNTER.get()).isEqualTo(2);
}

@Test
public synchronized void testConcurrentFastAppends() throws IOException {
    Map<String, String> properties = Maps.newHashMap();
    properties.put(CatalogProperties.WAREHOUSE_LOCATION, tableDir.getAbsolutePath());
    String sqliteDb = "jdbc:sqlite:" + tableDir.getAbsolutePath() + "concurentFastAppend.db";
    properties.put(CatalogProperties.URI, sqliteDb);
    JdbcCatalog catalog = new JdbcCatalog();
    catalog.setConf(new Configuration());
    catalog.initialize("jdbc", properties);
    catalog.createTable(TABLE_IDENTIFIER, SCHEMA);
    Table icebergTable = catalog.loadTable(TABLE_IDENTIFIER);
    String fileName = UUID.randomUUID().toString();
    DataFile file = DataFiles.builder(icebergTable.spec()).withPath(FileFormat.PARQUET.addExtension(fileName)).withRecordCount(2).withFileSizeInBytes(0).build();
    ExecutorService executorService = MoreExecutors.getExitingExecutorService((ThreadPoolExecutor) Executors.newFixedThreadPool(2));
    AtomicInteger barrier = new AtomicInteger(0);
    Tasks.range(2).stopOnFailure().throwFailureWhenFinished().executeWith(executorService).run(index -> {
        for (int numCommittedFiles = 0; numCommittedFiles < 10; numCommittedFiles++) {
            while (barrier.get() < numCommittedFiles * 2) {
                try {
                    Thread.sleep(10);
                } catch (InterruptedException e) {
                    throw new RuntimeException(e);
                }
            }
            icebergTable.newFastAppend().appendFile(file).commit();
            barrier.incrementAndGet();
        }
    });
    icebergTable.refresh();
    assertThat(icebergTable.currentSnapshot().allManifests(icebergTable.io())).hasSize(20);
}

@Test
public synchronized void testConcurrentConnections() throws InterruptedException, IOException {
    Map<String, String> properties = Maps.newHashMap();
    properties.put(CatalogProperties.WAREHOUSE_LOCATION, tableDir.getAbsolutePath());
    String sqliteDb = "jdbc:sqlite:" + tableDir.getAbsolutePath() + "concurentConnections.db";
    properties.put(CatalogProperties.URI, sqliteDb);
    JdbcCatalog catalog = new JdbcCatalog();
    catalog.setConf(new Configuration());
    catalog.initialize("jdbc", properties);
    catalog.createTable(TABLE_IDENTIFIER, SCHEMA);
    Table icebergTable = catalog.loadTable(TABLE_IDENTIFIER);
    icebergTable.updateProperties().set(COMMIT_NUM_RETRIES, "20").set(COMMIT_MIN_RETRY_WAIT_MS, "25").set(COMMIT_MAX_RETRY_WAIT_MS, "25").commit();
    String fileName = UUID.randomUUID().toString();
    DataFile file = DataFiles.builder(icebergTable.spec()).withPath(FileFormat.PARQUET.addExtension(fileName)).withRecordCount(2).withFileSizeInBytes(0).build();
    ExecutorService executorService = MoreExecutors.getExitingExecutorService((ThreadPoolExecutor) Executors.newFixedThreadPool(7));
    for (int i = 0; i < 7; i++) {
        executorService.submit(() -> icebergTable.newAppend().appendFile(file).commit());
    }
    executorService.shutdown();
    assertThat(executorService.awaitTermination(3, TimeUnit.MINUTES)).as("Timeout").isTrue();
