@Test
public void testOAuthScopeTokenValidation() {
    // valid scope tokens are from ascii 0x21 to 0x7E, excluding 0x22 (") and 0x5C (\)
    // test characters that are outside of the ! to ~ range and the excluded characters, " and \
    assertThat(OAuth2Util.isValidScopeToken("a\\b")).as("Should reject scope token with \\").isFalse();
    assertThat(OAuth2Util.isValidScopeToken("a b")).as("Should reject scope token with space").isFalse();
    assertThat(OAuth2Util.isValidScopeToken("a\"b")).as("Should reject scope token with \"").isFalse();
    assertThat(OAuth2Util.isValidScopeToken("\u007F")).as("Should reject scope token with DEL").isFalse();
    // test all characters that are inside of the ! to ~ range and are not excluded
    assertThat(OAuth2Util.isValidScopeToken("!#$%&'()*+,-./")).as("Should accept scope token with !-/").isTrue();
    assertThat(OAuth2Util.isValidScopeToken("0123456789")).as("Should accept scope token with 0-9").isTrue();
    assertThat(OAuth2Util.isValidScopeToken(":;<=>?@")).as("Should accept scope token with :-@").isTrue();
    assertThat(OAuth2Util.isValidScopeToken("ABCDEFGHIJKLM")).as("Should accept scope token with A-M").isTrue();
    assertThat(OAuth2Util.isValidScopeToken("NOPQRSTUVWXYZ")).as("Should accept scope token with N-Z").isTrue();
    assertThat(OAuth2Util.isValidScopeToken("[]^_`")).as("Should accept scope token with [-`, not \\").isTrue();
    assertThat(OAuth2Util.isValidScopeToken("abcdefghijklm")).as("Should accept scope token with a-m").isTrue();
    assertThat(OAuth2Util.isValidScopeToken("nopqrstuvwxyz")).as("Should accept scope token with n-z").isTrue();
    assertThat(OAuth2Util.isValidScopeToken("{|}~")).as("Should accept scope token with {-~").isTrue();
}

@Test
public void testExpiresAt() {
    assertThat(OAuth2Util.expiresAtMillis(null)).isNull();
    assertThat(OAuth2Util.expiresAtMillis("not a token")).isNull();
    // expires at epoch second = 1
    String token = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIiwiaWF0IjoxNTE2MjM5MDIyLCJleHAiOjF9.gQADTbdEv-rpDWKSkGLbmafyB5UUjTdm9B_1izpuZ6E";
    assertThat(OAuth2Util.expiresAtMillis(token)).isEqualTo(1000L);
    // expires at epoch second = 19999999999
    token = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIiwiaWF0IjoxNTE2MjM5MDIyLCJleHAiOjE5OTk5OTk5OTk5fQ._3k92KJi2NTyTG6V1s2mzJ__GiQtL36DnzsZSkBdYPw";
    assertThat(OAuth2Util.expiresAtMillis(token)).isEqualTo(19999999999000L);
    // no expiration
    token = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIiwiaWF0IjoxNTE2MjM5MDIyfQ.SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c";
    assertThat(OAuth2Util.expiresAtMillis(token)).isNull();
}

/**
 * This test ensures that the serialized JSON of each class has only fields that are expected from
 * the spec. Only top level fields are checked presently, as nested fields generally come from
 * some existing type that is tested elsewhere. The fields from the spec should be populated into
 * each subclass's {@link RequestResponseTestBase#allFieldsFromSpec()}.
 */
@Test
public void testHasOnlyKnownFields() {
    Set<String> fieldsFromSpec = Sets.newHashSet();
    Collections.addAll(fieldsFromSpec, allFieldsFromSpec());
    try {
        JsonNode node = mapper().readValue(serialize(createExampleInstance()), JsonNode.class);
        for (String field : fieldsFromSpec) {
            Assertions.assertThat(node.has(field)).as("Should have field: %s", field).isTrue();
        }
        for (String field : ((Iterable<? extends String>) node::fieldNames)) {
            Assertions.assertThat(fieldsFromSpec).as("Should not have field: %s", field).contains(field);
        }
    } catch (JsonProcessingException e) {
        throw new RuntimeException(e);
    }
}

