@Test
public void roundTripSerde() {
    String uuid = "2cc52516-5e73-41f2-b139-545d41a4e151";
    UpdateTableRequest commitTableRequestOne = UpdateTableRequest.create(TableIdentifier.of("ns1", "table1"), ImmutableList.of(new UpdateRequirement.AssertTableUUID(uuid), new UpdateRequirement.AssertTableDoesNotExist()), ImmutableList.of(new MetadataUpdate.AssignUUID(uuid), new MetadataUpdate.SetCurrentSchema(23)));
    UpdateTableRequest commitTableRequestTwo = UpdateTableRequest.create(TableIdentifier.of("ns1", "table2"), ImmutableList.of(new UpdateRequirement.AssertDefaultSpecID(4), new UpdateRequirement.AssertCurrentSchemaID(24)), ImmutableList.of(new MetadataUpdate.RemoveSnapshot(101L), new MetadataUpdate.SetCurrentSchema(25)));
    CommitTransactionRequest request = new CommitTransactionRequest(ImmutableList.of(commitTableRequestOne, commitTableRequestTwo));
    String expectedJson = "{
" + "  "table-changes" : [ {
" + "    "identifier" : {
" + "      "namespace" : [ "ns1" ],
" + "      "name" : "table1"
" + "    },
" + "    "requirements" : [ {
" + "      "type" : "assert-table-uuid",
" + "      "uuid" : "2cc52516-5e73-41f2-b139-545d41a4e151"
" + "    }, {
" + "      "type" : "assert-create"
" + "    } ],
" + "    "updates" : [ {
" + "      "action" : "assign-uuid",
" + "      "uuid" : "2cc52516-5e73-41f2-b139-545d41a4e151"
" + "    }, {
" + "      "action" : "set-current-schema",
" + "      "schema-id" : 23
" + "    } ]
" + "  }, {
" + "    "identifier" : {
" + "      "namespace" : [ "ns1" ],
" + "      "name" : "table2"
" + "    },
" + "    "requirements" : [ {
" + "      "type" : "assert-default-spec-id",
" + "      "default-spec-id" : 4
" + "    }, {
" + "      "type" : "assert-current-schema-id",
" + "      "current-schema-id" : 24
" + "    } ],
" + "    "updates" : [ {
" + "      "action" : "remove-snapshots",
" + "      "snapshot-ids" : [ 101 ]
" + "    }, {
" + "      "action" : "set-current-schema",
" + "      "schema-id" : 25
" + "    } ]
" + "  } ]
" + "}";
    String json = CommitTransactionRequestParser.toJson(request, true);
    assertThat(json).isEqualTo(expectedJson);
    // can't do an equality comparison on CommitTransactionRequest because updates/requirements
    // don't implement equals/hashcode
    assertThat(CommitTransactionRequestParser.toJson(CommitTransactionRequestParser.fromJson(json), true)).isEqualTo(expectedJson);
}

