@Test
public // Test cases that are JSON that can be created via the Builder
void testRoundTripSerDe() throws JsonProcessingException {
    String fullJsonRaw = "{\"name\":\"test_tbl\",\"location\":\"file://tmp/location/\",\"schema\":{\"type\":\"struct\"," + "\"schema-id\":0,\"fields\":[{\"id\":1,\"name\":\"id\",\"required\":true,\"type\":\"int\"}," + "{\"id\":2,\"name\":\"data\",\"required\":false,\"type\":\"string\"}]},\"partition-spec\":{\"spec-id\":0," + "\"fields\":[{\"name\":\"id_bucket\",\"transform\":\"bucket[16]\",\"source-id\":1,\"field-id\":1000}]}," + "\"write-order\":{\"order-id\":1,\"fields\":" + "[{\"transform\":\"identity\",\"source-id\":2,\"direction\":\"asc\",\"null-order\":\"nulls-last\"}]}," + "\"properties\":{\"owner\":\"Hank\"},\"stage-create\":false}";
    CreateTableRequest req = CreateTableRequest.builder().withName(SAMPLE_NAME).withLocation(SAMPLE_LOCATION).withSchema(SAMPLE_SCHEMA).setProperties(SAMPLE_PROPERTIES).withPartitionSpec(SAMPLE_SPEC).withWriteOrder(SAMPLE_WRITE_ORDER).build();
    assertRoundTripSerializesEquallyFrom(fullJsonRaw, req);
    // The same JSON but using existing parsers for clarity and staging the request instead of
    // committing
    String jsonStagedReq = String.format("{\"name\":\"%s\",\"location\":\"%s\",\"schema\":%s,\"partition-spec\":%s," + "\"write-order\":%s,\"properties\":%s,\"stage-create\":%b}", SAMPLE_NAME, SAMPLE_LOCATION, SchemaParser.toJson(SAMPLE_SCHEMA), PartitionSpecParser.toJson(SAMPLE_SPEC.toUnbound()), SortOrderParser.toJson(SAMPLE_WRITE_ORDER.toUnbound()), mapper().writeValueAsString(SAMPLE_PROPERTIES), true);
    CreateTableRequest stagedReq = CreateTableRequest.builder().withName(SAMPLE_NAME).withLocation(SAMPLE_LOCATION).withSchema(SAMPLE_SCHEMA).setProperty("owner", "Hank").withPartitionSpec(SAMPLE_SPEC).withWriteOrder(SAMPLE_WRITE_ORDER).stageCreate().build();
    assertRoundTripSerializesEquallyFrom(jsonStagedReq, stagedReq);
    // Partition spec and write order can be null or use PartitionSpec.unpartitioned() and
    // SortOrder.unsorted()
    String jsonWithExplicitUnsortedUnordered = String.format("{\"name\":\"%s\",\"location\":null,\"schema\":%s,\"partition-spec\":%s," + "\"write-order\":%s,\"properties\":{},\"stage-create\":%b}", SAMPLE_NAME, SchemaParser.toJson(SAMPLE_SCHEMA), PartitionSpecParser.toJson(PartitionSpec.unpartitioned()), SortOrderParser.toJson(SortOrder.unsorted().toUnbound()), /* stageCreate */
    false);
    CreateTableRequest reqOnlyRequiredFieldsExplicitDefaults = CreateTableRequest.builder().withName(SAMPLE_NAME).withLocation(null).withSchema(SAMPLE_SCHEMA).setProperties(EMPTY_PROPERTIES).withPartitionSpec(PartitionSpec.unpartitioned()).withWriteOrder(SortOrder.unsorted()).build();
    assertRoundTripSerializesEquallyFrom(jsonWithExplicitUnsortedUnordered, reqOnlyRequiredFieldsExplicitDefaults);
    String jsonOnlyRequiredFieldsNullAsDefault = String.format("{\"name\":\"%s\",\"location\":null,\"schema\":%s,\"partition-spec\":null,\"write-order\":null," + "\"properties\":{},\"stage-create\":false}", SAMPLE_NAME, SchemaParser.toJson(SAMPLE_SCHEMA));
    CreateTableRequest reqOnlyRequiredFieldsMissingDefaults = CreateTableRequest.builder().withName(SAMPLE_NAME).withSchema(SAMPLE_SCHEMA).withPartitionSpec(null).withWriteOrder(null).build();
    assertRoundTripSerializesEquallyFrom(jsonOnlyRequiredFieldsNullAsDefault, reqOnlyRequiredFieldsMissingDefaults);
}

