@Test
public void testDeserializeInvalidResponse() {
    // Invalid top-level types
    String jsonInvalidTypeOnRemovedField = "{\"removed\":{\"foo\":true},\"updated\":[\"owner\"],\"missing\":[\"bar\"]}";
    Assertions.assertThatThrownBy(() -> deserialize(jsonInvalidTypeOnRemovedField)).isInstanceOf(JsonProcessingException.class).hasMessageContaining("Cannot deserialize value of type `java.util.ArrayList<java.lang.String>`");
    String jsonInvalidTypeOnUpdatedField = "{\"updated\":\"owner\",\"missing\":[\"bar\"]}";
    Assertions.assertThatThrownBy(() -> deserialize(jsonInvalidTypeOnUpdatedField)).isInstanceOf(JsonProcessingException.class).hasMessageContaining("Cannot construct instance of `java.util.ArrayList`");
    // Valid top-level (array) types, but at least one entry in the list is not the expected type
    String jsonInvalidValueOfTypeIntNestedInRemovedList = "{\"removed\":[\"foo\", \"bar\", 123456], ,\"updated\":[\"owner\"],\"missing\":[\"bar\"]}";
    Assertions.assertThatThrownBy(() -> deserialize(jsonInvalidValueOfTypeIntNestedInRemovedList)).isInstanceOf(JsonProcessingException.class).hasMessageContaining("Unexpected character (',' (code 44))");
    // Exception comes from Jackson
    Assertions.assertThatThrownBy(() -> deserialize(null)).isInstanceOf(IllegalArgumentException.class).hasMessage("argument \"content\" is null");
}

