@Test
public void testCatalogWithCustomMetricsReporter() throws IOException {
    this.restCatalog = new RESTCatalog(new SessionCatalog.SessionContext(UUID.randomUUID().toString(), "user", ImmutableMap.of("credential", "user:12345"), ImmutableMap.of()), (config) -> HTTPClient.builder(config).uri(config.get(CatalogProperties.URI)).build());
    restCatalog.setConf(new Configuration());
    restCatalog.initialize("prod", ImmutableMap.of(CatalogProperties.URI, httpServer.getURI().toString(), "credential", "catalog:12345", CatalogProperties.METRICS_REPORTER_IMPL, CustomMetricsReporter.class.getName()));
    restCatalog.buildTable(TABLE, SCHEMA).create();
    Table table = restCatalog.loadTable(TABLE);
    table.newFastAppend().appendFile(DataFiles.builder(PartitionSpec.unpartitioned()).withPath("/path/to/data-a.parquet").withFileSizeInBytes(10).withRecordCount(2).build()).commit();
    try (CloseableIterable<FileScanTask> tasks = table.newScan().planFiles()) {
        assertThat(tasks.iterator()).hasNext();
    }
    // counter of custom metrics reporter should have been increased
    // 1x for commit metrics / 1x for scan metrics
    assertThat(CustomMetricsReporter.COUNTER.get()).isEqualTo(2);
}

