@Test
public void testMultipleRootSnapshots() throws Exception {
    table.newFastAppend().appendFile(FILE_A).commit();
    long snapshotAId = table.currentSnapshot().snapshotId();
    long expireTimestampSnapshotA = TestHelpers.waitUntilAfter(table.currentSnapshot().timestampMillis());
    // append file B in a staged branch
    AppendFiles appendFiles = table.newFastAppend().appendFile(FILE_B).stageOnly();
    long snapshotBId = appendFiles.apply().snapshotId();
    appendFiles.commit();
    table.newFastAppend().appendFile(FILE_C).commit();
    long snapshotCId = table.currentSnapshot().snapshotId();
    table.newFastAppend().appendFile(FILE_D).commit();
    long snapshotDId = table.currentSnapshot().snapshotId();
    // expiring snapshotA should create two root snapshots (B and C)
    table.expireSnapshots().expireOlderThan(expireTimestampSnapshotA).commit();
    // scan should discover snapshot C and D
    IncrementalAppendScan scan = newScan().toSnapshot(snapshotDId);
    Assert.assertEquals(2, Iterables.size(scan.planFiles()));
    // scan should fail because snapshot B is not an ancestor of snapshot D
    IncrementalAppendScan scanShouldFail = newScan().fromSnapshotExclusive(snapshotBId).toSnapshot(snapshotDId);
    Assertions.assertThatThrownBy(() -> Iterables.size(scanShouldFail.planFiles())).isInstanceOf(IllegalArgumentException.class).hasMessage(String.format("Starting snapshot (exclusive) %d is not a parent ancestor of end snapshot %d", snapshotBId, snapshotDId));
    // scan should fail because snapshot B is not an ancestor of snapshot D
    IncrementalAppendScan scanShouldFailInclusive = newScan().fromSnapshotInclusive(snapshotBId).toSnapshot(snapshotDId);
    Assertions.assertThatThrownBy(() -> Iterables.size(scanShouldFailInclusive.planFiles())).isInstanceOf(IllegalArgumentException.class).hasMessage(String.format("Starting snapshot (inclusive) %d is not an ancestor of end snapshot %d", snapshotBId, snapshotDId));
}

