@Test
public void testAlreadyDeletedFilesAreIgnoredDuringDeletesByRowFilter() {
    PartitionSpec spec = table.spec();
    DataFile firstDataFile = DataFiles.builder(spec).withPath("/path/to/data-2.parquet").withFileSizeInBytes(10).withPartitionPath("data_bucket=0").withMetrics(new Metrics(5L, // no column sizes
    null, // value count
    ImmutableMap.of(1, 5L, 2, 5L), // null count
    ImmutableMap.of(1, 0L, 2, 0L), // no nan value counts
    null, // lower bounds
    ImmutableMap.of(1, longToBuffer(0L)), // upper bounds
    ImmutableMap.of(1, longToBuffer(10L)))).build();
    DataFile secondDataFile = DataFiles.builder(spec).withPath("/path/to/data-1.parquet").withFileSizeInBytes(10).withPartitionPath("data_bucket=0").withMetrics(new Metrics(5L, // no column sizes
    null, // value count
    ImmutableMap.of(1, 5L, 2, 5L), // null count
    ImmutableMap.of(1, 0L, 2, 0L), // no nan value counts
    null, // lower bounds
    ImmutableMap.of(1, longToBuffer(0L)), // upper bounds
    ImmutableMap.of(1, longToBuffer(4L)))).build();
    // add both data files
    Snapshot initialSnapshot = commit(table, table.newFastAppend().appendFile(firstDataFile).appendFile(secondDataFile), branch);
    Assert.assertEquals("Should have 1 manifest", 1, initialSnapshot.allManifests(FILE_IO).size());
    validateManifestEntries(initialSnapshot.allManifests(FILE_IO).get(0), ids(initialSnapshot.snapshotId(), initialSnapshot.snapshotId()), files(firstDataFile, secondDataFile), statuses(Status.ADDED, Status.ADDED));
    // delete the first data file
    Snapshot deleteSnapshot = commit(table, table.newDelete().deleteFile(firstDataFile), branch);
    Assert.assertEquals("Should have 1 manifest", 1, deleteSnapshot.allManifests(FILE_IO).size());
    validateManifestEntries(deleteSnapshot.allManifests(FILE_IO).get(0), ids(deleteSnapshot.snapshotId(), initialSnapshot.snapshotId()), files(firstDataFile, secondDataFile), statuses(Status.DELETED, Status.EXISTING));
    // delete the second data file using a row filter
    // the commit should succeed as there is only one live data file
    Snapshot finalSnapshot = commit(table, table.newDelete().deleteFromRowFilter(Expressions.lessThan("id", 7)), branch);
    Assert.assertEquals("Should have 1 manifest", 1, finalSnapshot.allManifests(FILE_IO).size());
    validateManifestEntries(finalSnapshot.allManifests(FILE_IO).get(0), ids(finalSnapshot.snapshotId()), files(secondDataFile), statuses(Status.DELETED));
}

