    PartitionData partitionOne = new PartitionData(spec.partitionType());
    partitionOne.set(0, "Aa");
    PartitionData partitionTwo = new PartitionData(spec.partitionType());
    partitionTwo.set(0, "BB");
    Assert.assertEquals(StructLikeWrapper.forType(spec.partitionType()).set(partitionOne).hashCode(), StructLikeWrapper.forType(spec.partitionType()).set(partitionTwo).hashCode());
    DataFile testFileOne = DataFiles.builder(spec).withPartition(partitionOne).withPath("/g1.parquet").withFileSizeInBytes(100).withRecordCount(1).build();
    DataFile testFileTwo = DataFiles.builder(spec).withPartition(partitionTwo).withRecordCount(1).withFileSizeInBytes(100).withPath("/g2.parquet").build();
    collisionTable.newFastAppend().appendFile(testFileOne).appendFile(testFileTwo).commit();
    List<StructLike> beforeDeletePartitions = Lists.newArrayList(collisionTable.newScan().planFiles().iterator()).stream().map(s -> ((PartitionData) s.partition()).copy()).collect(Collectors.toList());
    Assert.assertEquals("We should have both partitions", ImmutableList.of(partitionOne, partitionTwo), beforeDeletePartitions);
    collisionTable.newDelete().deleteFromRowFilter(Expressions.equal("x", "BB")).commit();
    List<StructLike> afterDeletePartitions = Lists.newArrayList(collisionTable.newScan().planFiles().iterator()).stream().map(s -> ((PartitionData) s.partition()).copy()).collect(Collectors.toList());
    Assert.assertEquals("We should have deleted partitionTwo", ImmutableList.of(partitionOne), afterDeletePartitions);
}

