    Snapshot rewriteSnapshot = table.currentSnapshot();
    ManifestFile committedManifest = table.currentSnapshot().dataManifests(table.io()).get(0);
    Assert.assertEquals("Committed manifest sequence number must be correct", rewriteSnapshot.sequenceNumber(), committedManifest.sequenceNumber());
    Assert.assertEquals("Committed manifest min sequence number must be correct", appendSequenceNumber, committedManifest.minSequenceNumber());
    validateManifest(committedManifest, dataSeqs(appendSequenceNumber, appendSequenceNumber), fileSeqs(null, null), ids(appendSnapshotId, appendSnapshotId), files(file1, file2), statuses(Status.EXISTING, Status.EXISTING));
