public void testPartitionSpecEvolutionRemovalV1() {
    Assume.assumeTrue(formatVersion == 1);
    // Change spec and add two data files
    table.updateSpec().removeField(Expressions.bucket("data", 16)).addField("id").commit();
    PartitionSpec newSpec = table.spec();
    // Add two data files with new spec
    PartitionKey data10Key = new PartitionKey(newSpec, table.schema());
    data10Key.set(1, 10);
    DataFile data10 = DataFiles.builder(newSpec).withPath("/path/to/data-10.parquet").withRecordCount(10).withFileSizeInBytes(10).withPartition(data10Key).build();
    PartitionKey data11Key = new PartitionKey(newSpec, table.schema());
    data10Key.set(1, 11);
    DataFile data11 = DataFiles.builder(newSpec).withPath("/path/to/data-11.parquet").withRecordCount(10).withFileSizeInBytes(10).withPartition(data11Key).build();
    table.newFastAppend().appendFile(data10).commit();
    table.newFastAppend().appendFile(data11).commit();
    if (isAggFileTable(type)) {
        // Clear all files from current snapshot to test whether 'all' Files tables scans previous
        // files
        table.newDelete().deleteFromRowFilter(Expressions.alwaysTrue()).// Moves file entries to DELETED state
        commit();
        table.newDelete().deleteFromRowFilter(Expressions.alwaysTrue()).// Removes all entries
        commit();
        Assert.assertEquals("Current snapshot should be made empty", 0, table.currentSnapshot().allManifests(table.io()).size());
