    Assert.assertEquals(expectedScanTaskCount(5), Iterables.size(tasks));
    filter = Expressions.and(Expressions.equal(partitionColumn("data_bucket"), 0), dummyExpression());
    scan = metadataTable.newScan().filter(filter);
