@Test
public void testPositionDeletesUnpartitioned() {
    Assume.assumeTrue("Position deletes supported only for v2 tables", formatVersion == 2);
    table.updateSpec().removeField(Expressions.bucket("data", BUCKETS_NUMBER)).commit();
    Assert.assertEquals("Table should now be unpartitioned", 0, table.spec().fields().size());
    DataFile dataFile1 = DataFiles.builder(table.spec()).withPath("/path/to/data1.parquet").withFileSizeInBytes(10).withRecordCount(1).build();
    DataFile dataFile2 = DataFiles.builder(table.spec()).withPath("/path/to/data2.parquet").withFileSizeInBytes(10).withRecordCount(1).build();
    table.newAppend().appendFile(dataFile1).appendFile(dataFile2).commit();
    DeleteFile delete1 = FileMetadata.deleteFileBuilder(table.spec()).ofPositionDeletes().withPath("/path/to/delete1.parquet").withFileSizeInBytes(10).withRecordCount(1).build();
    DeleteFile delete2 = FileMetadata.deleteFileBuilder(table.spec()).ofPositionDeletes().withPath("/path/to/delete2.parquet").withFileSizeInBytes(10).withRecordCount(1).build();
    table.newRowDelta().addDeletes(delete1).addDeletes(delete2).commit();
    PositionDeletesTable positionDeletesTable = new PositionDeletesTable(table);
    BatchScan scan = positionDeletesTable.newBatchScan();
    assertThat(scan).isInstanceOf(PositionDeletesTable.PositionDeletesBatchScan.class);
    PositionDeletesTable.PositionDeletesBatchScan deleteScan = (PositionDeletesTable.PositionDeletesBatchScan) scan;
    List<PositionDeletesScanTask> scanTasks = Lists.newArrayList(Iterators.transform(deleteScan.planFiles().iterator(), task -> {
        assertThat(task).isInstanceOf(PositionDeletesScanTask.class);
        return (PositionDeletesScanTask) task;
    }));
    Assert.assertEquals("Expected to scan 1 manifest", 1, deleteScan.scanMetrics().scannedDeleteManifests().value());
    Assert.assertEquals("Expected 2 tasks", 2, scanTasks.size());
    scanTasks.sort(Comparator.comparing(f -> f.file().path().toString()));
    Assert.assertEquals("/path/to/delete1.parquet", scanTasks.get(0).file().path().toString());
    Assert.assertEquals("/path/to/delete2.parquet", scanTasks.get(1).file().path().toString());
    Types.StructType partitionType = Partitioning.partitionType(table);
    Assert.assertEquals("/path/to/delete1.parquet", constantsMap(scanTasks.get(0), partitionType).get(MetadataColumns.FILE_PATH.fieldId()));
    Assert.assertEquals("/path/to/delete2.parquet", constantsMap(scanTasks.get(1), partitionType).get(MetadataColumns.FILE_PATH.fieldId()));
    Assert.assertEquals(1, constantsMap(scanTasks.get(0), partitionType).get(MetadataColumns.SPEC_ID.fieldId()));
    Assert.assertEquals(1, constantsMap(scanTasks.get(1), partitionType).get(MetadataColumns.SPEC_ID.fieldId()));
    StructLikeWrapper wrapper = StructLikeWrapper.forType(Partitioning.partitionType(table));
    // Check for null partition values
    PartitionData partitionData = new PartitionData(Partitioning.partitionType(table));
    StructLikeWrapper expected = wrapper.set(partitionData);
    StructLike scanTask1PartitionStruct = (StructLike) constantsMap(scanTasks.get(0), partitionType).get(MetadataColumns.PARTITION_COLUMN_ID);
    StructLikeWrapper scanTask1Partition = wrapper.copyFor(scanTask1PartitionStruct);
    StructLike scanTask2PartitionStruct = (StructLike) constantsMap(scanTasks.get(1), partitionType).get(MetadataColumns.PARTITION_COLUMN_ID);
    StructLikeWrapper scanTask2Partition = wrapper.copyFor(scanTask2PartitionStruct);
    Assert.assertEquals(expected, scanTask1Partition);
    Assert.assertEquals(expected, scanTask2Partition);
}

