@Test
public void testTruncateBinary() {
    ByteBuffer original = ByteBuffer.wrap(new byte[] { 1, 1, (byte) 0xFF, 2 });
    ByteBuffer emptyByteBuffer = ByteBuffer.allocate(0);
    Comparator<ByteBuffer> cmp = Literal.of(original).comparator();
    Assertions.assertThat(cmp.compare(truncateBinary(original, 0), emptyByteBuffer)).as("Truncating to a length of zero should return an empty ByteBuffer").isEqualTo(0);
    Assertions.assertThat(truncateBinary(original, original.remaining())).as("Truncating to the original buffer's remaining size should return the original buffer").isEqualTo(original);
    Assertions.assertThat(truncateBinary(original, 16)).as("Truncating with a length greater than the input's remaining size should return the input").isEqualTo(original);
    ByteBuffer truncated = truncateBinary(original, 2);
    Assertions.assertThat(truncated.remaining()).as("Truncating with a length less than the input's remaining size should truncate properly").isEqualTo(2);
    Assertions.assertThat(truncated.position()).as("Truncating with a length less than the input's remaining size should truncate properly").isEqualTo(0);
    Assertions.assertThat(original.remaining()).as("Truncating should not modify the input buffer").isEqualTo(4);
    Assertions.assertThat(original.position()).as("Truncating should not modify the input buffer").isEqualTo(0);
    Assertions.assertThatThrownBy(() -> truncateBinary(original, -1)).isInstanceOf(IllegalArgumentException.class).hasMessage("Truncate length should be non-negative");
}

@Test
public void testTruncateBinaryMin() {
