    // Output of test1 when truncated to 2 bytes
    ByteBuffer test1_2_expected = ByteBuffer.wrap(new byte[] { 1, 1 });
    ByteBuffer test2 = ByteBuffer.wrap(new byte[] { (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, 2 });
    ByteBuffer test2_2 = ByteBuffer.wrap(new byte[] { (byte) 0xFF, (byte) 0xFF });
    Comparator<ByteBuffer> cmp = Literal.of(test1).comparator();
    Assertions.assertThat(cmp.compare(truncateBinaryMin(Literal.of(test1), 2).value(), test1)).as("Truncated lower bound should be lower than or equal to the actual lower bound").isLessThanOrEqualTo(0);
    Assertions.assertThat(cmp.compare(truncateBinaryMin(Literal.of(test1), 2).value(), test1_2_expected)).as("Output must have the first two bytes of the input").isEqualTo(0);
    Assertions.assertThat(cmp.compare(truncateBinaryMin(Literal.of(test1), 5).value(), test1)).as("No truncation required as truncate length is greater than the input size").isEqualTo(0);
    Assertions.assertThat(cmp.compare(truncateBinaryMin(Literal.of(test2), 2).value(), test2)).as("Truncated lower bound should be lower than or equal to the actual lower bound").isLessThanOrEqualTo(0);
    Assertions.assertThat(cmp.compare(truncateBinaryMin(Literal.of(test2), 2).value(), test2_2)).as("Output must have the first two bytes of the input. A lower bound exists " + "even though the first two bytes are the max value").isEqualTo(0);
}

@Test
public void testTruncateBinaryMax() {
    ByteBuffer test1 = ByteBuffer.wrap(new byte[] { 1, 1, 2 });
    ByteBuffer test2 = ByteBuffer.wrap(new byte[] { 1, 1, (byte) 0xFF, 2 });
    ByteBuffer test3 = ByteBuffer.wrap(new byte[] { (byte) 0xFF, (byte) 0xFF, (byte) 0xFF, 2 });
    ByteBuffer test4 = ByteBuffer.wrap(new byte[] { 1, 1, 0 });
    ByteBuffer expectedOutput = ByteBuffer.wrap(new byte[] { 1, 2 });
    Comparator<ByteBuffer> cmp = Literal.of(test1).comparator();
    Assertions.assertThat(cmp.compare(truncateBinaryMax(Literal.of(test1), 2).value(), test1)).as("Truncated upper bound should be greater than or equal to the actual upper bound").isGreaterThanOrEqualTo(0);
    Assertions.assertThat(cmp.compare(truncateBinaryMax(Literal.of(test1), 2).value(), expectedOutput)).as("Output must have two bytes and the second byte of the input must be incremented").isEqualTo(0);
    Assertions.assertThat(cmp.compare(truncateBinaryMax(Literal.of(test2), 2).value(), test2)).as("Truncated upper bound should be greater than or equal to the actual upper bound").isGreaterThanOrEqualTo(0);
    Assertions.assertThat(cmp.compare(truncateBinaryMax(Literal.of(test2), 3).value(), expectedOutput)).as("Since the third byte is already the max value, output must have two bytes " + "with the second byte incremented ").isEqualTo(0);
    Assertions.assertThat(cmp.compare(truncateBinaryMax(Literal.of(test3), 5).value(), test3)).as("No truncation required as truncate length is greater than the input size").isEqualTo(0);
    Assertions.assertThat(truncateBinaryMax(Literal.of(test3), 2)).as("An upper bound doesn't exist since the first two bytes are the max value").isNull();
    Assertions.assertThat(cmp.compare(truncateBinaryMax(Literal.of(test4), 2).value(), test4)).as("Truncated upper bound should be greater than or equal to the actual upper bound").isGreaterThanOrEqualTo(0);
    Assertions.assertThat(cmp.compare(truncateBinaryMax(Literal.of(test4), 2).value(), expectedOutput)).as("Since a shorter sequence is considered smaller, output must have two bytes " + "and the second byte of the input must be incremented").isEqualTo(0);
}

