@Test
public void testExpireOlderThanWithRollback() {
    // merge every commit
    table.updateProperties().set(TableProperties.MANIFEST_MIN_MERGE_COUNT, "0").commit();
    table.newAppend().appendFile(FILE_A).appendFile(FILE_B).commit();
    Snapshot firstSnapshot = table.currentSnapshot();
    Assert.assertEquals("Should create one manifest", 1, firstSnapshot.allManifests(table.io()).size());
    waitUntilAfter(table.currentSnapshot().timestampMillis());
    table.newDelete().deleteFile(FILE_B).commit();
    Snapshot secondSnapshot = table.currentSnapshot();
    Set<ManifestFile> secondSnapshotManifests = Sets.newHashSet(secondSnapshot.allManifests(table.io()));
    secondSnapshotManifests.removeAll(firstSnapshot.allManifests(table.io()));
    Assert.assertEquals("Should add one new manifest for append", 1, secondSnapshotManifests.size());
    table.manageSnapshots().rollbackTo(firstSnapshot.snapshotId()).commit();
    long tAfterCommits = waitUntilAfter(secondSnapshot.timestampMillis());
    long snapshotId = table.currentSnapshot().snapshotId();
    Set<String> deletedFiles = Sets.newHashSet();
    removeSnapshots(table).expireOlderThan(tAfterCommits).deleteWith(deletedFiles::add).commit();
    Assert.assertEquals("Expire should not change current snapshot", snapshotId, table.currentSnapshot().snapshotId());
    Assert.assertNotNull("Expire should keep the oldest snapshot, current", table.snapshot(firstSnapshot.snapshotId()));
    Assert.assertNull("Expire should remove the orphaned snapshot", table.snapshot(secondSnapshot.snapshotId()));
    Assert.assertEquals("Should remove expired manifest lists and reverted appended data file", Sets.newHashSet(// snapshot expired
    secondSnapshot.manifestListLocation(), Iterables.getOnlyElement(secondSnapshotManifests).// manifest is no longer referenced
    path()), deletedFiles);
}

