    // add a data file to partition A
    DataFile dataFile1 = DataFiles.builder(table.spec()).withPath("/path/to/data-a.parquet").withFileSizeInBytes(10).withPartitionPath("data=a").withRecordCount(1).build();
    commit(table, table.newAppend().appendFile(dataFile1), branch);
