    commit(table, table.newAppend().appendFile(dataFile2), branch);
    // use this snapshot as the starting snapshot in rowDelta
    Snapshot baseSnapshot = latestSnapshot(table, branch);
    // add a delete file for partition A
    DeleteFile deleteFile = FileMetadata.deleteFileBuilder(table.spec()).ofPositionDeletes().withPath("/path/to/data-a-deletes.parquet").withFileSizeInBytes(10).withPartitionPath("data=a").withRecordCount(1).build();
