@Test
public void testNonWapCherrypick() {
    table.newAppend().appendFile(FILE_A).commit();
    TableMetadata base = readMetadata();
    long firstSnapshotId = base.currentSnapshot().snapshotId();
    table.newAppend().appendFile(FILE_B).commit();
    base = readMetadata();
    long secondSnapshotId = base.currentSnapshot().snapshotId();
    table.newAppend().appendFile(FILE_C).commit();
    base = readMetadata();
    long thirdSnapshotId = base.currentSnapshot().snapshotId();
    Assert.assertEquals("Should be pointing to third snapshot", thirdSnapshotId, table.currentSnapshot().snapshotId());
    // NOOP commit
    table.manageSnapshots().commit();
    Assert.assertEquals("Should still be pointing to third snapshot", thirdSnapshotId, table.currentSnapshot().snapshotId());
    // Rollback to second snapshot
    table.manageSnapshots().rollbackTo(secondSnapshotId).commit();
    Assert.assertEquals("Should be pointing to second snapshot", secondSnapshotId, table.currentSnapshot().snapshotId());
    // Cherrypick down to third
    table.manageSnapshots().cherrypick(thirdSnapshotId).commit();
    Assert.assertEquals("Should be re-using wap snapshot after cherrypick", 3, table.currentSnapshot().snapshotId());
    // try double cherrypicking of the third snapshot
    Assertions.assertThatThrownBy(// double cherrypicking of second snapshot
    () -> table.manageSnapshots().cherrypick(thirdSnapshotId).commit()).isInstanceOf(CherrypickAncestorCommitException.class).hasMessage("Cannot cherrypick snapshot 3: already an ancestor");
    // try cherrypicking an ancestor
    Assertions.assertThatThrownBy(// double cherrypicking of second snapshot
    () -> table.manageSnapshots().cherrypick(firstSnapshotId).commit()).isInstanceOf(CherrypickAncestorCommitException.class).hasMessage(String.format("Cannot cherrypick snapshot %s: already an ancestor", firstSnapshotId));
}

