    assertThat(LocationUtil.stripTrailingSlash(pathWithoutTrailingSlash)).as("Should have no trailing slashes").isEqualTo(pathWithoutTrailingSlash);
    String pathWithSingleTrailingSlash = pathWithoutTrailingSlash + "/";
    assertThat(LocationUtil.stripTrailingSlash(pathWithSingleTrailingSlash)).as("Should have no trailing slashes").isEqualTo(pathWithoutTrailingSlash);
    String pathWithMultipleTrailingSlash = pathWithoutTrailingSlash + "////";
