@Test
public void closeParallelIteratorWithoutCompleteIteration() throws IOException, IllegalAccessException, NoSuchFieldException {
    ExecutorService executor = Executors.newFixedThreadPool(1);
    Iterable<CloseableIterable<Integer>> transform = Iterables.transform(Lists.newArrayList(1, 2, 3, 4, 5), item -> new CloseableIterable<Integer>() {

        @Override
        public void close() {
        }

        @Override
        public CloseableIterator<Integer> iterator() {
            return CloseableIterator.withClose(Collections.singletonList(item).iterator());
        }
    });
    ParallelIterable<Integer> parallelIterable = new ParallelIterable<>(transform, executor);
    CloseableIterator<Integer> iterator = parallelIterable.iterator();
    Field queueField = iterator.getClass().getDeclaredField("queue");
    queueField.setAccessible(true);
    ConcurrentLinkedQueue<?> queue = (ConcurrentLinkedQueue<?>) queueField.get(iterator);
    assertThat(iterator.hasNext()).isTrue();
    assertThat(iterator.next()).isNotNull();
    Awaitility.await("Queue is populated").atMost(5, TimeUnit.SECONDS).untilAsserted(() -> queueHasElements(iterator, queue));
    iterator.close();
    Awaitility.await("Queue is cleared").atMost(5, TimeUnit.SECONDS).untilAsserted(() -> assertThat(queue).isEmpty());
}

