@Test
public void viewHistoryNormalization() {
    Map<String, String> properties = ImmutableMap.of(ViewProperties.VERSION_HISTORY_SIZE, "2");
    ViewVersion viewVersionOne = newViewVersion(1, "select * from ns.tbl");
    ViewVersion viewVersionTwo = newViewVersion(2, "select count(*) from ns.tbl");
    ViewVersion viewVersionThree = newViewVersion(3, "select count(*) as count from ns.tbl");
    ViewMetadata originalViewMetadata = ViewMetadata.builder().setProperties(properties).setLocation("location").addSchema(new Schema(Types.NestedField.required(1, "x", Types.LongType.get()))).addVersion(viewVersionOne).addVersion(viewVersionTwo).addVersion(viewVersionThree).setCurrentVersionId(3).build();
    // the first build will not expire versions that were added in the builder
    assertThat(originalViewMetadata.versions()).hasSize(3);
    assertThat(originalViewMetadata.history()).hasSize(3);
    // rebuild the metadata to expire older versions
    ViewMetadata viewMetadata = ViewMetadata.buildFrom(originalViewMetadata).build();
    assertThat(viewMetadata.versions()).hasSize(2);
    assertThat(viewMetadata.history()).hasSize(2);
    // make sure that metadata changes reflect the current state after the history was adjusted,
    // meaning that the first view version shouldn't be included
    List<MetadataUpdate> changes = originalViewMetadata.changes();
    assertThat(changes).hasSize(7);
    assertThat(changes).element(0).isInstanceOf(MetadataUpdate.SetProperties.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.SetProperties.class)).extracting(MetadataUpdate.SetProperties::updated).isEqualTo(properties);
    assertThat(changes).element(1).isInstanceOf(MetadataUpdate.SetLocation.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.SetLocation.class)).extracting(MetadataUpdate.SetLocation::location).isEqualTo("location");
    assertThat(changes).element(2).isInstanceOf(MetadataUpdate.AddSchema.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AddSchema.class)).extracting(MetadataUpdate.AddSchema::schema).extracting(Schema::schemaId).isEqualTo(0);
    assertThat(changes).element(3).isInstanceOf(MetadataUpdate.AddViewVersion.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AddViewVersion.class)).extracting(MetadataUpdate.AddViewVersion::viewVersion).isEqualTo(viewVersionOne);
    assertThat(changes).element(4).isInstanceOf(MetadataUpdate.AddViewVersion.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AddViewVersion.class)).extracting(MetadataUpdate.AddViewVersion::viewVersion).isEqualTo(viewVersionTwo);
    assertThat(changes).element(5).isInstanceOf(MetadataUpdate.AddViewVersion.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AddViewVersion.class)).extracting(MetadataUpdate.AddViewVersion::viewVersion).isEqualTo(viewVersionThree);
    assertThat(changes).element(6).isInstanceOf(MetadataUpdate.SetCurrentViewVersion.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.SetCurrentViewVersion.class)).extracting(MetadataUpdate.SetCurrentViewVersion::versionId).isEqualTo(-1);
}

