    assertThat(changes).element(2).isInstanceOf(MetadataUpdate.SetProperties.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.SetProperties.class)).extracting(MetadataUpdate.SetProperties::updated).isEqualTo(properties);
    assertThat(changes).element(3).isInstanceOf(MetadataUpdate.AddSchema.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AddSchema.class)).extracting(MetadataUpdate.AddSchema::schema).extracting(Schema::schemaId).isEqualTo(0);
    assertThat(changes).element(4).isInstanceOf(MetadataUpdate.AddSchema.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AddSchema.class)).extracting(MetadataUpdate.AddSchema::schema).extracting(Schema::schemaId).isEqualTo(1);
    assertThat(changes).element(5).isInstanceOf(MetadataUpdate.AddViewVersion.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AddViewVersion.class)).extracting(MetadataUpdate.AddViewVersion::viewVersion).isEqualTo(viewVersionOne);
    assertThat(changes).element(6).isInstanceOf(MetadataUpdate.AddViewVersion.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AddViewVersion.class)).extracting(MetadataUpdate.AddViewVersion::viewVersion).isEqualTo(viewVersionTwo);
    assertThat(changes).element(7).isInstanceOf(MetadataUpdate.AddViewVersion.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.AddViewVersion.class)).extracting(MetadataUpdate.AddViewVersion::viewVersion).isEqualTo(viewVersionThree);
    assertThat(changes).element(8).isInstanceOf(MetadataUpdate.SetCurrentViewVersion.class).asInstanceOf(InstanceOfAssertFactories.type(MetadataUpdate.SetCurrentViewVersion.class)).extracting(MetadataUpdate.SetCurrentViewVersion::versionId).isEqualTo(-1);
