public void viewVersionAndSchemaDeduplication() {
    Schema schemaOne = new Schema(5, Types.NestedField.required(1, "x", Types.LongType.get()));
    Schema schemaTwo = new Schema(7, Types.NestedField.required(1, "y", Types.LongType.get()));
    Schema schemaThree = new Schema(9, Types.NestedField.required(1, "z", Types.LongType.get()));
    // all view versions have the same ID
    // additionally, there are duplicate view versions and schemas
    ViewVersion viewVersionOne = newViewVersion(1, 5, "select * from ns.tbl");
    ViewVersion viewVersionTwo = newViewVersion(1, 7, "select count(*) from ns.tbl");
    ViewVersion viewVersionThree = newViewVersion(1, 9, "select count(*) as count from ns.tbl");
    // all view versions have the same ID
    ViewMetadata viewMetadata = ViewMetadata.builder().setLocation("custom-location").addSchema(schemaOne).addSchema(schemaTwo).addSchema(schemaThree).setCurrentVersion(viewVersionOne, schemaOne).setCurrentVersion(viewVersionTwo, schemaTwo).setCurrentVersion(viewVersionThree, schemaThree).setCurrentVersion(viewVersionThree, schemaThree).setCurrentVersion(viewVersionTwo, schemaTwo).setCurrentVersion(viewVersionOne, schemaOne).build();
    assertThat(viewMetadata.currentVersion()).isEqualTo(ImmutableViewVersion.builder().from(viewVersionOne).versionId(1).schemaId(0).build());
    // IDs of schemas and view versions should be re-assigned and both should be de-duplicated
    assertThat(viewMetadata.versions()).hasSize(3).containsExactly(ImmutableViewVersion.builder().from(viewVersionOne).versionId(1).schemaId(0).build(), ImmutableViewVersion.builder().from(viewVersionTwo).versionId(2).schemaId(1).build(), ImmutableViewVersion.builder().from(viewVersionThree).versionId(3).schemaId(2).build());
    assertThat(viewMetadata.schemas().stream().map(Schema::asStruct)).hasSize(3).containsExactly(schemaOne.asStruct(), schemaTwo.asStruct(), schemaThree.asStruct());
    assertThat(viewMetadata.schemasById().keySet()).containsExactly(0, 1, 2);
}

