    List<Record> recordList = RandomGenericData.generate(SCHEMA, 5, 250L);
    FileAppender<T> appender = writeAndGetAppender(recordList);
    Map<Types.NestedField, AtomicReference<Number>> expectedUpperBounds = Maps.newHashMap();
