@Test
public void testBaseObjectWrite() throws IOException {
    String objectName = rule.randomObjectName();
    try (EcsAppendOutputStream output = EcsAppendOutputStream.createWithBufferSize(rule.client(), new EcsURI(rule.bucket(), objectName), 10, MetricsContext.nullMetrics())) {
        // write 1 byte
        output.write('1');
        // write 3 bytes
        output.write("123".getBytes());
        // write 7 bytes, totally 11 bytes > local buffer limit (10)
        output.write("1234567".getBytes());
        // write 11 bytes, flush remain 7 bytes and new 11 bytes
        output.write("12345678901".getBytes());
    }
    try (InputStream input = rule.client().readObjectStream(rule.bucket(), objectName, Range.fromOffset(0))) {
        assertThat(new String(ByteStreams.toByteArray(input), StandardCharsets.UTF_8)).as("Must write all the object content").isEqualTo("1" + "123" + "1234567" + "12345678901");
    }
}

