}

@Test
public void testNestedTypeConversion() {
    Type converted = DeltaLakeDataTypeVisitor.visit(deltaNestedSchema, new DeltaLakeTypeToType(deltaNestedSchema));
    Schema convertedSchema = new Schema(converted.asNestedType().asStructType().fields());
    Assertions.assertThat(convertedSchema.findType(innerAtomicSchema)).isInstanceOf(Types.StructType.class);
    Assertions.assertThat(convertedSchema.findField(innerAtomicSchema).isOptional()).isTrue();
    Assertions.assertThat(convertedSchema.findType(innerAtomicSchema).asStructType().fieldType(optionalBooleanType)).isInstanceOf(Types.BooleanType.class);
    Assertions.assertThat(convertedSchema.findType(innerAtomicSchema).asStructType().fieldType(requiredBinaryType)).isInstanceOf(Types.BinaryType.class);
    Assertions.assertThat(convertedSchema.findType(innerAtomicSchema).asStructType().field(requiredBinaryType).isRequired()).isTrue();
    Assertions.assertThat(convertedSchema.findType(stringLongMapType)).isInstanceOf(Types.MapType.class);
    Assertions.assertThat(convertedSchema.findType(stringLongMapType).asMapType().keyType()).isInstanceOf(Types.StringType.class);
    Assertions.assertThat(convertedSchema.findType(stringLongMapType).asMapType().valueType()).isInstanceOf(Types.LongType.class);
    Assertions.assertThat(convertedSchema.findType(doubleArrayType)).isInstanceOf(Types.ListType.class);
    Assertions.assertThat(convertedSchema.findField(doubleArrayType).isRequired()).isTrue();
    Assertions.assertThat(convertedSchema.findType(doubleArrayType).asListType().isElementOptional()).isTrue();
    Assertions.assertThat(convertedSchema.findType(structArrayType)).isInstanceOf(Types.ListType.class);
    Assertions.assertThat(convertedSchema.findField(structArrayType).isRequired()).isTrue();
    Assertions.assertThat(convertedSchema.findType(structArrayType).asListType().isElementOptional()).isTrue();
    Assertions.assertThat(convertedSchema.findType(structArrayType).asListType().elementType()).isInstanceOf(Types.StructType.class);
    Assertions.assertThat(convertedSchema.findType(structArrayType).asListType().elementType().asStructType().fieldType(optionalBooleanType)).isInstanceOf(Types.BooleanType.class);
    Assertions.assertThat(convertedSchema.findType(structArrayType).asListType().elementType().asStructType().field(optionalBooleanType).isOptional()).isTrue();
    Assertions.assertThat(convertedSchema.findType(structArrayType).asListType().elementType().asStructType().fieldType(requiredBinaryType)).isInstanceOf(Types.BinaryType.class);
    Assertions.assertThat(convertedSchema.findType(structArrayType).asListType().elementType().asStructType().field(requiredBinaryType).isRequired()).isTrue();
}

