@Test
public void mergeDataStatisticTest() {
    GenericRowData rowDataA = GenericRowData.of(StringData.fromString("a"));
    GenericRowData rowDataB = GenericRowData.of(StringData.fromString("b"));
    AggregatedStatistics<MapDataStatistics, Map<RowData, Long>> aggregatedStatistics = new AggregatedStatistics<>(1, MapDataStatisticsSerializer.fromKeySerializer(new RowDataSerializer(RowType.of(new VarCharType()))));
    MapDataStatistics mapDataStatistics1 = new MapDataStatistics();
    mapDataStatistics1.add(rowDataA);
    mapDataStatistics1.add(rowDataA);
    mapDataStatistics1.add(rowDataB);
    aggregatedStatistics.mergeDataStatistic("testOperator", 1, mapDataStatistics1);
    MapDataStatistics mapDataStatistics2 = new MapDataStatistics();
    mapDataStatistics2.add(rowDataA);
    aggregatedStatistics.mergeDataStatistic("testOperator", 1, mapDataStatistics2);
    assertThat(aggregatedStatistics.dataStatistics().statistics().get(rowDataA)).isEqualTo(mapDataStatistics1.statistics().get(rowDataA) + mapDataStatistics2.statistics().get(rowDataA));
    assertThat(aggregatedStatistics.dataStatistics().statistics().get(rowDataB)).isEqualTo(mapDataStatistics1.statistics().get(rowDataB) + mapDataStatistics2.statistics().getOrDefault(rowDataB, 0L));
}

@Test
public void receiveNewerDataStatisticEvent() {
    MapDataStatistics checkpoint1Subtask0DataStatistic = new MapDataStatistics();
    checkpoint1Subtask0DataStatistic.add(binaryRowDataA);
    DataStatisticsEvent<MapDataStatistics, Map<RowData, Long>> checkpoint1Subtask0DataStatisticEvent = DataStatisticsEvent.create(1, checkpoint1Subtask0DataStatistic, statisticsSerializer);
    assertThat(aggregatedStatisticsTracker.updateAndCheckCompletion(0, checkpoint1Subtask0DataStatisticEvent)).isNull();
    assertThat(aggregatedStatisticsTracker.inProgressStatistics().checkpointId()).isEqualTo(1);
    MapDataStatistics checkpoint2Subtask0DataStatistic = new MapDataStatistics();
    checkpoint2Subtask0DataStatistic.add(binaryRowDataA);
    DataStatisticsEvent<MapDataStatistics, Map<RowData, Long>> checkpoint2Subtask0DataStatisticEvent = DataStatisticsEvent.create(2, checkpoint2Subtask0DataStatistic, statisticsSerializer);
    assertThat(aggregatedStatisticsTracker.updateAndCheckCompletion(0, checkpoint2Subtask0DataStatisticEvent)).isNull();
    // Checkpoint 2 is newer than checkpoint1, thus dropping in progress statistics for checkpoint1
    assertThat(aggregatedStatisticsTracker.inProgressStatistics().checkpointId()).isEqualTo(2);
}

@Test
public void receiveOlderDataStatisticEventTest() {
    MapDataStatistics checkpoint2Subtask0DataStatistic = new MapDataStatistics();
    checkpoint2Subtask0DataStatistic.add(binaryRowDataA);
