@Test
public void receiveCompletedDataStatisticEvent() {
    MapDataStatistics checkpoint1Subtask0DataStatistic = new MapDataStatistics();
    checkpoint1Subtask0DataStatistic.add(binaryRowDataA);
    checkpoint1Subtask0DataStatistic.add(binaryRowDataB);
    checkpoint1Subtask0DataStatistic.add(binaryRowDataB);
    DataStatisticsEvent<MapDataStatistics, Map<RowData, Long>> checkpoint1Subtask0DataStatisticEvent = DataStatisticsEvent.create(1, checkpoint1Subtask0DataStatistic, statisticsSerializer);
    assertThat(aggregatedStatisticsTracker.updateAndCheckCompletion(0, checkpoint1Subtask0DataStatisticEvent)).isNull();
    MapDataStatistics checkpoint1Subtask1DataStatistic = new MapDataStatistics();
    checkpoint1Subtask1DataStatistic.add(binaryRowDataA);
    checkpoint1Subtask1DataStatistic.add(binaryRowDataA);
    checkpoint1Subtask1DataStatistic.add(binaryRowDataB);
    DataStatisticsEvent<MapDataStatistics, Map<RowData, Long>> checkpoint1Subtask1DataStatisticEvent = DataStatisticsEvent.create(1, checkpoint1Subtask1DataStatistic, statisticsSerializer);
    // Receive data statistics from all subtasks at checkpoint 1
    AggregatedStatistics<MapDataStatistics, Map<RowData, Long>> completedStatistics = aggregatedStatisticsTracker.updateAndCheckCompletion(1, checkpoint1Subtask1DataStatisticEvent);
    assertThat(completedStatistics).isNotNull();
    assertThat(completedStatistics.checkpointId()).isEqualTo(1);
    MapDataStatistics globalDataStatistics = (MapDataStatistics) completedStatistics.dataStatistics();
    assertThat((long) globalDataStatistics.statistics().get(binaryRowDataA)).isEqualTo(checkpoint1Subtask0DataStatistic.statistics().get(binaryRowDataA) + checkpoint1Subtask1DataStatistic.statistics().get(binaryRowDataA));
    assertThat((long) globalDataStatistics.statistics().get(binaryRowDataB)).isEqualTo(checkpoint1Subtask0DataStatistic.statistics().get(binaryRowDataB) + checkpoint1Subtask1DataStatistic.statistics().get(binaryRowDataB));
    assertThat(aggregatedStatisticsTracker.inProgressStatistics().checkpointId()).isEqualTo(completedStatistics.checkpointId() + 1);
    MapDataStatistics checkpoint2Subtask0DataStatistic = new MapDataStatistics();
    checkpoint2Subtask0DataStatistic.add(binaryRowDataA);
    DataStatisticsEvent<MapDataStatistics, Map<RowData, Long>> checkpoint2Subtask0DataStatisticEvent = DataStatisticsEvent.create(2, checkpoint2Subtask0DataStatistic, statisticsSerializer);
    assertThat(aggregatedStatisticsTracker.updateAndCheckCompletion(0, checkpoint2Subtask0DataStatisticEvent)).isNull();
    assertThat(completedStatistics.checkpointId()).isEqualTo(1);
    MapDataStatistics checkpoint2Subtask1DataStatistic = new MapDataStatistics();
    checkpoint2Subtask1DataStatistic.add(binaryRowDataB);
    DataStatisticsEvent<MapDataStatistics, Map<RowData, Long>> checkpoint2Subtask1DataStatisticEvent = DataStatisticsEvent.create(2, checkpoint2Subtask1DataStatistic, statisticsSerializer);
    // Receive data statistics from all subtasks at checkpoint 2
    completedStatistics = aggregatedStatisticsTracker.updateAndCheckCompletion(1, checkpoint2Subtask1DataStatisticEvent);
    assertThat(completedStatistics).isNotNull();
    assertThat(completedStatistics.checkpointId()).isEqualTo(2);
    assertThat(aggregatedStatisticsTracker.inProgressStatistics().checkpointId()).isEqualTo(completedStatistics.checkpointId() + 1);
}

