@Test
public void testDataStatisticsEventHandling() throws Exception {
    tasksReady();
    // When coordinator handles events from operator, DataStatisticsUtil#deserializeDataStatistics
    // deserializes bytes into BinaryRowData
    RowType rowType = RowType.of(new VarCharType());
    BinaryRowData binaryRowDataA = new RowDataSerializer(rowType).toBinaryRow(GenericRowData.of(StringData.fromString("a")));
    BinaryRowData binaryRowDataB = new RowDataSerializer(rowType).toBinaryRow(GenericRowData.of(StringData.fromString("b")));
    BinaryRowData binaryRowDataC = new RowDataSerializer(rowType).toBinaryRow(GenericRowData.of(StringData.fromString("c")));
    MapDataStatistics checkpoint1Subtask0DataStatistic = new MapDataStatistics();
    checkpoint1Subtask0DataStatistic.add(binaryRowDataA);
    checkpoint1Subtask0DataStatistic.add(binaryRowDataB);
    checkpoint1Subtask0DataStatistic.add(binaryRowDataB);
    checkpoint1Subtask0DataStatistic.add(binaryRowDataC);
    checkpoint1Subtask0DataStatistic.add(binaryRowDataC);
    checkpoint1Subtask0DataStatistic.add(binaryRowDataC);
    DataStatisticsEvent<MapDataStatistics, Map<RowData, Long>> checkpoint1Subtask0DataStatisticEvent = DataStatisticsEvent.create(1, checkpoint1Subtask0DataStatistic, statisticsSerializer);
    MapDataStatistics checkpoint1Subtask1DataStatistic = new MapDataStatistics();
    checkpoint1Subtask1DataStatistic.add(binaryRowDataA);
    checkpoint1Subtask1DataStatistic.add(binaryRowDataB);
    checkpoint1Subtask1DataStatistic.add(binaryRowDataC);
    checkpoint1Subtask1DataStatistic.add(binaryRowDataC);
    DataStatisticsEvent<MapDataStatistics, Map<RowData, Long>> checkpoint1Subtask1DataStatisticEvent = DataStatisticsEvent.create(1, checkpoint1Subtask1DataStatistic, statisticsSerializer);
    // Handle events from operators for checkpoint 1
    dataStatisticsCoordinator.handleEventFromOperator(0, checkpoint1Subtask0DataStatisticEvent);
    dataStatisticsCoordinator.handleEventFromOperator(1, checkpoint1Subtask1DataStatisticEvent);
    waitForCoordinatorToProcessActions(dataStatisticsCoordinator);
    // Verify global data statistics is the aggregation of all subtasks data statistics
    MapDataStatistics globalDataStatistics = (MapDataStatistics) dataStatisticsCoordinator.completedStatistics().dataStatistics();
    assertThat(globalDataStatistics.statistics()).containsExactlyInAnyOrderEntriesOf(ImmutableMap.of(binaryRowDataA, checkpoint1Subtask0DataStatistic.statistics().get(binaryRowDataA) + (long) checkpoint1Subtask1DataStatistic.statistics().get(binaryRowDataA), binaryRowDataB, checkpoint1Subtask0DataStatistic.statistics().get(binaryRowDataB) + (long) checkpoint1Subtask1DataStatistic.statistics().get(binaryRowDataB), binaryRowDataC, checkpoint1Subtask0DataStatistic.statistics().get(binaryRowDataC) + (long) checkpoint1Subtask1DataStatistic.statistics().get(binaryRowDataC)));
}

