@Test
public void testEqualityColumnOnCustomPrecisionTSColumn() throws IOException {
    Schema tableSchema = new Schema(required(3, "id", Types.IntegerType.get()), required(4, "ts", Types.TimestampType.withZone()));
    RowType flinkType = new RowType(false, ImmutableList.of(new RowType.RowField("id", new IntType()), new RowType.RowField("ts", new LocalZonedTimestampType(3))));
    this.table = create(tableSchema, PartitionSpec.unpartitioned());
    initTable(table);
    List<Integer> equalityIds = ImmutableList.of(table.schema().findField("ts").fieldId());
    TaskWriterFactory<RowData> taskWriterFactory = createTaskWriterFactory(flinkType, equalityIds);
    taskWriterFactory.initialize(1, 1);
    TaskWriter<RowData> writer = taskWriterFactory.create();
    RowDataSerializer serializer = new RowDataSerializer(flinkType);
    OffsetDateTime start = OffsetDateTime.now();
    writer.write(serializer.toBinaryRow(GenericRowData.ofKind(RowKind.INSERT, 1, TimestampData.fromInstant(start.toInstant()))));
    writer.write(serializer.toBinaryRow(GenericRowData.ofKind(RowKind.INSERT, 2, TimestampData.fromInstant(start.plusSeconds(1).toInstant()))));
    writer.write(serializer.toBinaryRow(GenericRowData.ofKind(RowKind.DELETE, 2, TimestampData.fromInstant(start.plusSeconds(1).toInstant()))));
    WriteResult result = writer.complete();
    // One data file
    Assertions.assertThat(result.dataFiles().length).isEqualTo(1);
    // One eq delete file + one pos delete file
    Assertions.assertThat(result.deleteFiles().length).isEqualTo(2);
    Assertions.assertThat(Arrays.stream(result.deleteFiles()).map(ContentFile::content).collect(Collectors.toSet())).isEqualTo(Sets.newHashSet(FileContent.POSITION_DELETES, FileContent.EQUALITY_DELETES));
    commitTransaction(result);
    Record expectedRecord = GenericRecord.create(tableSchema);
    expectedRecord.setField("id", 1);
    int cutPrecisionNano = start.getNano() / 1000000 * 1000000;
    expectedRecord.setField("ts", start.withNano(cutPrecisionNano));
    Assertions.assertThat(actualRowSet("*")).isEqualTo(expectedRowSet(expectedRecord));
}

