@Test
public void testSpecEvolution() throws Exception {
    long timestamp = 0;
    int checkpointId = 0;
    List<RowData> rows = Lists.newArrayList();
    JobID jobId = new JobID();
    OperatorID operatorId;
    OperatorSubtaskState snapshot;
    DataFile dataFile;
    int specId;
    try (OneInputStreamOperatorTestHarness<WriteResult, Void> harness = createStreamSink(jobId)) {
        harness.setup();
        harness.open();
        operatorId = harness.getOperator().getOperatorID();
        assertSnapshotSize(0);
        checkpointId++;
        RowData rowData = SimpleDataUtil.createRowData(checkpointId, "hello" + checkpointId);
        // table unpartitioned
        dataFile = writeDataFile("data-" + checkpointId, ImmutableList.of(rowData));
        harness.processElement(of(dataFile), ++timestamp);
        rows.add(rowData);
        harness.snapshot(checkpointId, ++timestamp);
        specId = getStagingManifestSpecId(harness.getOperator().getOperatorStateBackend(), checkpointId);
        assertThat(specId).isEqualTo(table.spec().specId());
        harness.notifyOfCompletedCheckpoint(checkpointId);
        // Change partition spec
        table.refresh();
        PartitionSpec oldSpec = table.spec();
        table.updateSpec().addField("id").commit();
        checkpointId++;
        rowData = SimpleDataUtil.createRowData(checkpointId, "hello" + checkpointId);
        // write data with old partition spec
        dataFile = writeDataFile("data-" + checkpointId, ImmutableList.of(rowData), oldSpec, null);
        harness.processElement(of(dataFile), ++timestamp);
        rows.add(rowData);
        snapshot = harness.snapshot(checkpointId, ++timestamp);
        specId = getStagingManifestSpecId(harness.getOperator().getOperatorStateBackend(), checkpointId);
        assertThat(specId).isEqualTo(oldSpec.specId());
        harness.notifyOfCompletedCheckpoint(checkpointId);
        assertFlinkManifests(0);
        SimpleDataUtil.assertTableRows(table, ImmutableList.copyOf(rows), branch);
        assertSnapshotSize(checkpointId);
        assertMaxCommittedCheckpointId(jobId, operatorId, checkpointId);
    }
    // Restore from the given snapshot
    try (OneInputStreamOperatorTestHarness<WriteResult, Void> harness = createStreamSink(jobId)) {
        harness.getStreamConfig().setOperatorID(operatorId);
        harness.setup();
        harness.initializeState(snapshot);
        harness.open();
        SimpleDataUtil.assertTableRows(table, rows, branch);
        assertSnapshotSize(checkpointId);
        assertMaxCommittedCheckpointId(jobId, operatorId, checkpointId);
        checkpointId++;
        RowData row = SimpleDataUtil.createRowData(checkpointId, "world" + checkpointId);
        StructLike partition = new PartitionData(table.spec().partitionType());
        partition.set(0, checkpointId);
        dataFile = writeDataFile("data-" + checkpointId, ImmutableList.of(row), table.spec(), partition);
        harness.processElement(of(dataFile), ++timestamp);
        rows.add(row);
        harness.snapshot(checkpointId, ++timestamp);
        assertFlinkManifests(1);
        specId = getStagingManifestSpecId(harness.getOperator().getOperatorStateBackend(), checkpointId);
        assertThat(specId).isEqualTo(table.spec().specId());
        harness.notifyOfCompletedCheckpoint(checkpointId);
        assertFlinkManifests(0);
        SimpleDataUtil.assertTableRows(table, rows, branch);
        assertSnapshotSize(checkpointId);
        assertMaxCommittedCheckpointId(jobId, operatorId, checkpointId);
    }
}

@Test
public void testWritingTable() throws Exception {
    long checkpointId = 1L;
    try (OneInputStreamOperatorTestHarness<RowData, WriteResult> testHarness = createIcebergStreamWriter()) {
        // The first checkpoint
        testHarness.processElement(SimpleDataUtil.createRowData(1, "hello"), 1);
        testHarness.processElement(SimpleDataUtil.createRowData(2, "world"), 1);
        testHarness.processElement(SimpleDataUtil.createRowData(3, "hello"), 1);
        testHarness.prepareSnapshotPreBarrier(checkpointId);
        long expectedDataFiles = partitioned ? 2 : 1;
        WriteResult result = WriteResult.builder().addAll(testHarness.extractOutputValues()).build();
        Assert.assertEquals(0, result.deleteFiles().length);
        Assert.assertEquals(expectedDataFiles, result.dataFiles().length);
        checkpointId = checkpointId + 1;
        // The second checkpoint
        testHarness.processElement(SimpleDataUtil.createRowData(4, "foo"), 1);
        testHarness.processElement(SimpleDataUtil.createRowData(5, "bar"), 2);
        testHarness.prepareSnapshotPreBarrier(checkpointId);
        expectedDataFiles = partitioned ? 4 : 2;
        result = WriteResult.builder().addAll(testHarness.extractOutputValues()).build();
        Assert.assertEquals(0, result.deleteFiles().length);
        Assert.assertEquals(expectedDataFiles, result.dataFiles().length);
        // Commit the iceberg transaction.
        AppendFiles appendFiles = table.newAppend();
        Arrays.stream(result.dataFiles()).forEach(appendFiles::appendFile);
        appendFiles.commit();
        // Assert the table records.
        SimpleDataUtil.assertTableRecords(table, Lists.newArrayList(SimpleDataUtil.createRecord(1, "hello"), SimpleDataUtil.createRecord(2, "world"), SimpleDataUtil.createRecord(3, "hello"), SimpleDataUtil.createRecord(4, "foo"), SimpleDataUtil.createRecord(5, "bar")));
    }
}

