public void testMetadataLogEntries() {
    Table table = validationCatalog.loadTable(TableIdentifier.of(icebergNamespace, TABLE_NAME));
    Long currentSnapshotId = table.currentSnapshot().snapshotId();
    TableMetadata tableMetadata = ((HasTableOperations) table).operations().current();
    Snapshot currentSnapshot = tableMetadata.currentSnapshot();
    Snapshot parentSnapshot = table.snapshot(currentSnapshot.parentId());
    List<TableMetadata.MetadataLogEntry> metadataLogEntries = Lists.newArrayList(tableMetadata.previousFiles());
    // Check metadataLog table
    List<Row> metadataLogs = sql("SELECT * FROM %s$metadata_log_entries", TABLE_NAME);
    Assert.assertEquals("metadataLogEntries table should return 3 row", 3, metadataLogs.size());
    Row metadataLog = metadataLogs.get(0);
    Assert.assertEquals(Instant.ofEpochMilli(metadataLogEntries.get(0).timestampMillis()), metadataLog.getField("timestamp"));
    Assert.assertEquals(metadataLogEntries.get(0).file(), metadataLog.getField("file"));
    Assert.assertNull(metadataLog.getField("latest_snapshot_id"));
    Assert.assertNull(metadataLog.getField("latest_schema_id"));
    Assert.assertNull(metadataLog.getField("latest_sequence_number"));
    metadataLog = metadataLogs.get(1);
    Assert.assertEquals(Instant.ofEpochMilli(metadataLogEntries.get(1).timestampMillis()), metadataLog.getField("timestamp"));
    Assert.assertEquals(metadataLogEntries.get(1).file(), metadataLog.getField("file"));
    Assert.assertEquals(parentSnapshot.snapshotId(), metadataLog.getField("latest_snapshot_id"));
    Assert.assertEquals(parentSnapshot.schemaId(), metadataLog.getField("latest_schema_id"));
    Assert.assertEquals(parentSnapshot.sequenceNumber(), metadataLog.getField("latest_sequence_number"));
    metadataLog = metadataLogs.get(2);
    Assert.assertEquals(Instant.ofEpochMilli(currentSnapshot.timestampMillis()), metadataLog.getField("timestamp"));
    Assert.assertEquals(tableMetadata.metadataFileLocation(), metadataLog.getField("file"));
    Assert.assertEquals(currentSnapshot.snapshotId(), metadataLog.getField("latest_snapshot_id"));
    Assert.assertEquals(currentSnapshot.schemaId(), metadataLog.getField("latest_schema_id"));
    Assert.assertEquals(currentSnapshot.sequenceNumber(), metadataLog.getField("latest_sequence_number"));
    // test filtering
    List<Row> metadataLogWithFilters = sql("SELECT * FROM %s$metadata_log_entries WHERE latest_snapshot_id = %s", TABLE_NAME, currentSnapshotId);
    Assert.assertEquals("metadataLogEntries table should return 1 row", 1, metadataLogWithFilters.size());
    metadataLog = metadataLogWithFilters.get(0);
    Assert.assertEquals(Instant.ofEpochMilli(tableMetadata.currentSnapshot().timestampMillis()), metadataLog.getField("timestamp"));
    Assert.assertEquals(tableMetadata.metadataFileLocation(), metadataLog.getField("file"));
    Assert.assertEquals(tableMetadata.currentSnapshot().snapshotId(), metadataLog.getField("latest_snapshot_id"));
    Assert.assertEquals(tableMetadata.currentSnapshot().schemaId(), metadataLog.getField("latest_schema_id"));
    Assert.assertEquals(tableMetadata.currentSnapshot().sequenceNumber(), metadataLog.getField("latest_sequence_number"));
    // test projection
    List<String> metadataFiles = metadataLogEntries.stream().map(TableMetadata.MetadataLogEntry::file).collect(Collectors.toList());
    metadataFiles.add(tableMetadata.metadataFileLocation());
    List<Row> metadataLogWithProjection = sql("SELECT file FROM %s$metadata_log_entries", TABLE_NAME);
    Assert.assertEquals("metadataLogEntries table should return 3 rows", 3, metadataLogWithProjection.size());
    for (int i = 0; i < metadataFiles.size(); i++) {
        Assert.assertEquals(metadataFiles.get(i), metadataLogWithProjection.get(i).getField("file"));
    }
}

