@Test
public void mergeDataStatisticTest() {
    GenericRowData rowDataA = GenericRowData.of(StringData.fromString("a"));
    GenericRowData rowDataB = GenericRowData.of(StringData.fromString("b"));
    AggregatedStatistics<MapDataStatistics, Map<RowData, Long>> aggregatedStatistics = new AggregatedStatistics<>(1, MapDataStatisticsSerializer.fromKeySerializer(new RowDataSerializer(RowType.of(new VarCharType()))));
    MapDataStatistics mapDataStatistics1 = new MapDataStatistics();
    mapDataStatistics1.add(rowDataA);
    mapDataStatistics1.add(rowDataA);
    mapDataStatistics1.add(rowDataB);
    aggregatedStatistics.mergeDataStatistic("testOperator", 1, mapDataStatistics1);
    MapDataStatistics mapDataStatistics2 = new MapDataStatistics();
    mapDataStatistics2.add(rowDataA);
    aggregatedStatistics.mergeDataStatistic("testOperator", 1, mapDataStatistics2);
    assertThat(aggregatedStatistics.dataStatistics().statistics().get(rowDataA)).isEqualTo(mapDataStatistics1.statistics().get(rowDataA) + mapDataStatistics2.statistics().get(rowDataA));
    assertThat(aggregatedStatistics.dataStatistics().statistics().get(rowDataB)).isEqualTo(mapDataStatistics1.statistics().get(rowDataB) + mapDataStatistics2.statistics().getOrDefault(rowDataB, 0L));
}

