@Test
@SuppressWarnings("unchecked")
public void testCheckpointAndReset() throws Exception {
    RowType rowType = RowType.of(new VarCharType());
    // When coordinator handles events from operator, DataStatisticsUtil#deserializeDataStatistics
    // deserializes bytes into BinaryRowData
    BinaryRowData binaryRowDataA = new RowDataSerializer(rowType).toBinaryRow(GenericRowData.of(StringData.fromString("a")));
    BinaryRowData binaryRowDataB = new RowDataSerializer(rowType).toBinaryRow(GenericRowData.of(StringData.fromString("b")));
    BinaryRowData binaryRowDataC = new RowDataSerializer(rowType).toBinaryRow(GenericRowData.of(StringData.fromString("c")));
    BinaryRowData binaryRowDataD = new RowDataSerializer(rowType).toBinaryRow(GenericRowData.of(StringData.fromString("d")));
    BinaryRowData binaryRowDataE = new RowDataSerializer(rowType).toBinaryRow(GenericRowData.of(StringData.fromString("e")));
    RecreateOnResetOperatorCoordinator coordinator = (RecreateOnResetOperatorCoordinator) provider.create(new MockOperatorCoordinatorContext(OPERATOR_ID, NUM_SUBTASKS));
    DataStatisticsCoordinator<MapDataStatistics, Map<RowData, Long>> dataStatisticsCoordinator = (DataStatisticsCoordinator<MapDataStatistics, Map<RowData, Long>>) coordinator.getInternalCoordinator();
    // Start the coordinator
    coordinator.start();
    TestDataStatisticsCoordinator.setAllTasksReady(NUM_SUBTASKS, dataStatisticsCoordinator, receivingTasks);
    MapDataStatistics checkpoint1Subtask0DataStatistic = new MapDataStatistics();
    checkpoint1Subtask0DataStatistic.add(binaryRowDataA);
    checkpoint1Subtask0DataStatistic.add(binaryRowDataB);
    checkpoint1Subtask0DataStatistic.add(binaryRowDataC);
    DataStatisticsEvent<MapDataStatistics, Map<RowData, Long>> checkpoint1Subtask0DataStatisticEvent = DataStatisticsEvent.create(1, checkpoint1Subtask0DataStatistic, statisticsSerializer);
    // Handle events from operators for checkpoint 1
    coordinator.handleEventFromOperator(0, 0, checkpoint1Subtask0DataStatisticEvent);
    TestDataStatisticsCoordinator.waitForCoordinatorToProcessActions(dataStatisticsCoordinator);
    // Verify checkpoint 1 global data statistics
    MapDataStatistics checkpoint1GlobalDataStatistics = (MapDataStatistics) dataStatisticsCoordinator.completedStatistics().dataStatistics();
    assertThat(checkpoint1GlobalDataStatistics.statistics()).isEqualTo(checkpoint1Subtask0DataStatistic.statistics());
    byte[] checkpoint1Bytes = waitForCheckpoint(1L, dataStatisticsCoordinator);
    MapDataStatistics checkpoint2Subtask0DataStatistic = new MapDataStatistics();
    checkpoint2Subtask0DataStatistic.add(binaryRowDataD);
    checkpoint2Subtask0DataStatistic.add(binaryRowDataE);
    checkpoint2Subtask0DataStatistic.add(binaryRowDataE);
    DataStatisticsEvent<MapDataStatistics, Map<RowData, Long>> checkpoint2Subtask0DataStatisticEvent = DataStatisticsEvent.create(2, checkpoint2Subtask0DataStatistic, statisticsSerializer);
    // Handle events from operators for checkpoint 2
    coordinator.handleEventFromOperator(0, 0, checkpoint2Subtask0DataStatisticEvent);
    TestDataStatisticsCoordinator.waitForCoordinatorToProcessActions(dataStatisticsCoordinator);
    // Verify checkpoint 2 global data statistics
    MapDataStatistics checkpoint2GlobalDataStatistics = (MapDataStatistics) dataStatisticsCoordinator.completedStatistics().dataStatistics();
    assertThat(checkpoint2GlobalDataStatistics.statistics()).isEqualTo(checkpoint2Subtask0DataStatistic.statistics());
    waitForCheckpoint(2L, dataStatisticsCoordinator);
    // Reset coordinator to checkpoint 1
    coordinator.resetToCheckpoint(1L, checkpoint1Bytes);
    DataStatisticsCoordinator<MapDataStatistics, Map<RowData, Long>> restoredDataStatisticsCoordinator = (DataStatisticsCoordinator<MapDataStatistics, Map<RowData, Long>>) coordinator.getInternalCoordinator();
    assertThat(dataStatisticsCoordinator).isNotEqualTo(restoredDataStatisticsCoordinator);
    // Verify restored data statistics
    MapDataStatistics restoredAggregateDataStatistics = (MapDataStatistics) restoredDataStatisticsCoordinator.completedStatistics().dataStatistics();
    assertThat(restoredAggregateDataStatistics.statistics()).isEqualTo(checkpoint1GlobalDataStatistics.statistics());
}

