        for (int i = 1; i <= 3; i++) {
            harness.snapshot(++checkpointId, ++timestamp);
            assertFlinkManifests(0);
            harness.notifyOfCompletedCheckpoint(checkpointId);
            assertFlinkManifests(0);
            assertSnapshotSize(i);
            assertMaxCommittedCheckpointId(jobId, operatorId, checkpointId);
        }
    }
}

