@Test
public void testInferParallelismWithGlobalSetting() throws IOException {
    Configuration cfg = getTableEnv().getConfig().getConfiguration();
    cfg.set(PipelineOptions.MAX_PARALLELISM, 1);
    Table table = catalogResource.catalog().createTable(TestFixtures.TABLE_IDENTIFIER, TestFixtures.SCHEMA, null);
    GenericAppenderHelper helper = new GenericAppenderHelper(table, FileFormat.PARQUET, TEMPORARY_FOLDER);
    List<Record> expectedRecords = Lists.newArrayList();
    long maxFileLen = 0;
    for (int i = 0; i < 5; i++) {
        List<Record> records = RandomGenericData.generate(TestFixtures.SCHEMA, 2, i);
        DataFile dataFile = helper.writeFile(null, records);
        helper.appendToTable(dataFile);
        expectedRecords.addAll(records);
        maxFileLen = Math.max(dataFile.fileSizeInBytes(), maxFileLen);
    }
    // Make sure to generate multiple CombinedScanTasks
    SqlHelpers.sql(getTableEnv(), "ALTER TABLE t SET ('read.split.open-file-cost'='1', 'read.split.target-size'='%s')", maxFileLen);
    List<Row> results = run(Maps.newHashMap(), "", "*");
    org.apache.iceberg.flink.TestHelpers.assertRecords(results, expectedRecords, TestFixtures.SCHEMA);
}

@Test
public void testLimitPushDown() {
    Assertions.assertThatThrownBy(() -> sql("SELECT * FROM %s LIMIT -1", TABLE_NAME)).isInstanceOf(SqlParserException.class).hasMessageStartingWith("SQL parse failed.");
    Assert.assertEquals("Should have 0 record", 0, sql("SELECT * FROM %s LIMIT 0", TABLE_NAME).size());
    String sqlLimitExceed = String.format("SELECT * FROM %s LIMIT 4", TABLE_NAME);
    List<Row> resultExceed = sql(sqlLimitExceed);
    Assert.assertEquals("Should have 3 records", 3, resultExceed.size());
    List<Row> expectedList = Lists.newArrayList(Row.of(1, "iceberg", 10.0), Row.of(2, "b", 20.0), Row.of(3, null, 30.0));
    assertSameElements(expectedList, resultExceed);
    String querySql = String.format("SELECT * FROM %s LIMIT 1", TABLE_NAME);
    String explain = getTableEnv().explainSql(querySql);
    String expectedExplain = "limit=[1]";
    Assert.assertTrue("Explain should contain LimitPushDown", explain.contains(expectedExplain));
    List<Row> result = sql(querySql);
    Assert.assertEquals("Should have 1 record", 1, result.size());
    Assertions.assertThat(result).containsAnyElementsOf(expectedList);
    String sqlMixed = String.format("SELECT * FROM %s WHERE id = 1 LIMIT 2", TABLE_NAME);
    List<Row> mixedResult = sql(sqlMixed);
    Assert.assertEquals("Should have 1 record", 1, mixedResult.size());
    Assert.assertEquals("Should produce the expected records", Row.of(1, "iceberg", 10.0), mixedResult.get(0));
}

