    long oldestSnapshotId = SnapshotUtil.oldestAncestor(table).snapshotId();
    ScanContext scanContext = ScanContext.builder().monitorInterval(Duration.ofMillis(100)).splitSize(1000L).startSnapshotId(oldestSnapshotId).maxPlanningSnapshotCount(Integer.MAX_VALUE).build();
    FlinkInputSplit[] expectedSplits = FlinkSplitPlanner.planInputSplits(table, scanContext, ThreadPools.getWorkerPool());
    Assert.assertEquals("should produce 9 splits", 9, expectedSplits.length);
    // This covers three cases that maxPlanningSnapshotCount is less than, equal or greater than the
    // total splits number
    for (int maxPlanningSnapshotCount : ImmutableList.of(1, 9, 15)) {
        scanContext = ScanContext.builder().monitorInterval(Duration.ofMillis(500)).startSnapshotId(oldestSnapshotId).splitSize(1000L).maxPlanningSnapshotCount(maxPlanningSnapshotCount).build();
