@Test
public void testAlterTableAddColumn() {
    sql("CREATE TABLE tl(id BIGINT)");
    Schema schemaBefore = table("tl").schema();
    Assert.assertEquals(new Schema(Types.NestedField.optional(1, "id", Types.LongType.get())).asStruct(), schemaBefore.asStruct());
    sql("ALTER TABLE tl ADD (dt STRING)");
    Schema schemaAfter1 = table("tl").schema();
    Assert.assertEquals(new Schema(Types.NestedField.optional(1, "id", Types.LongType.get()), Types.NestedField.optional(2, "dt", Types.StringType.get())).asStruct(), schemaAfter1.asStruct());
    // Add multiple columns
    sql("ALTER TABLE tl ADD (col1 STRING, col2 BIGINT)");
    Schema schemaAfter2 = table("tl").schema();
    Assert.assertEquals(new Schema(Types.NestedField.optional(1, "id", Types.LongType.get()), Types.NestedField.optional(2, "dt", Types.StringType.get()), Types.NestedField.optional(3, "col1", Types.StringType.get()), Types.NestedField.optional(4, "col2", Types.LongType.get())).asStruct(), schemaAfter2.asStruct());
    // Adding a required field should fail because Iceberg's SchemaUpdate does not allow
    // incompatible changes.
    Assertions.assertThatThrownBy(() -> sql("ALTER TABLE tl ADD (pk STRING NOT NULL)")).hasRootCauseInstanceOf(IllegalArgumentException.class).hasRootCauseMessage("Incompatible change: cannot add required column: pk");
    // Adding an existing field should fail due to Flink's internal validation.
    Assertions.assertThatThrownBy(() -> sql("ALTER TABLE tl ADD (id STRING)")).isInstanceOf(ValidationException.class).hasMessageContaining("Try to add a column `id` which already exists in the table.");
}

