@Test
public void testAlterTableConstraint() {
    sql("CREATE TABLE tl(id BIGINT NOT NULL, dt STRING NOT NULL, col1 STRING)");
    Schema schemaBefore = table("tl").schema();
    Assert.assertEquals(new Schema(Types.NestedField.required(1, "id", Types.LongType.get()), Types.NestedField.required(2, "dt", Types.StringType.get()), Types.NestedField.optional(3, "col1", Types.StringType.get())).asStruct(), schemaBefore.asStruct());
    Assert.assertEquals(ImmutableSet.of(), schemaBefore.identifierFieldNames());
    sql("ALTER TABLE tl ADD (PRIMARY KEY (id) NOT ENFORCED)");
    Schema schemaAfterAdd = table("tl").schema();
    Assert.assertEquals(ImmutableSet.of("id"), schemaAfterAdd.identifierFieldNames());
    sql("ALTER TABLE tl MODIFY (PRIMARY KEY (dt) NOT ENFORCED)");
    Schema schemaAfterModify = table("tl").schema();
    Assert.assertEquals(new Schema(Types.NestedField.required(1, "id", Types.LongType.get()), Types.NestedField.required(2, "dt", Types.StringType.get()), Types.NestedField.optional(3, "col1", Types.StringType.get())).asStruct(), schemaAfterModify.asStruct());
    Assert.assertEquals(ImmutableSet.of("dt"), schemaAfterModify.identifierFieldNames());
    // Composite primary key
    sql("ALTER TABLE tl MODIFY (PRIMARY KEY (id, dt) NOT ENFORCED)");
    Schema schemaAfterComposite = table("tl").schema();
    Assert.assertEquals(new Schema(Types.NestedField.required(1, "id", Types.LongType.get()), Types.NestedField.required(2, "dt", Types.StringType.get()), Types.NestedField.optional(3, "col1", Types.StringType.get())).asStruct(), schemaAfterComposite.asStruct());
    Assert.assertEquals(ImmutableSet.of("id", "dt"), schemaAfterComposite.identifierFieldNames());
    // Setting an optional field as primary key should fail
    // because Iceberg's SchemaUpdate does not allow incompatible changes.
    Assertions.assertThatThrownBy(() -> sql("ALTER TABLE tl MODIFY (PRIMARY KEY (col1) NOT ENFORCED)")).isInstanceOf(TableException.class).hasRootCauseInstanceOf(IllegalArgumentException.class).hasRootCauseMessage("Cannot add field col1 as an identifier field: not a required field");
    // Setting a composite key containing an optional field should fail
    // because Iceberg's SchemaUpdate does not allow incompatible changes.
    Assertions.assertThatThrownBy(() -> sql("ALTER TABLE tl MODIFY (PRIMARY KEY (id, col1) NOT ENFORCED)")).isInstanceOf(TableException.class).hasRootCauseInstanceOf(IllegalArgumentException.class).hasRootCauseMessage("Cannot add field col1 as an identifier field: not a required field");
    // Dropping constraints is not supported yet
    Assertions.assertThatThrownBy(() -> sql("ALTER TABLE tl DROP PRIMARY KEY")).isInstanceOf(TableException.class).hasRootCauseInstanceOf(UnsupportedOperationException.class).hasRootCauseMessage("Unsupported table change: DropConstraint.");
}

