@Test
public void testSetCurrentAndCherryPickSnapshotId() {
    sql("CREATE TABLE tl(c1 INT, c2 STRING, c3 STRING) PARTITIONED BY (c1)");
    Table table = table("tl");
    DataFile fileA = DataFiles.builder(table.spec()).withPath("/path/to/data-a.parquet").withFileSizeInBytes(10).withPartitionPath(// easy way to set partition data for now
    "c1=0").withRecordCount(1).build();
    DataFile fileB = DataFiles.builder(table.spec()).withPath("/path/to/data-b.parquet").withFileSizeInBytes(10).withPartitionPath(// easy way to set partition data for now
    "c1=1").withRecordCount(1).build();
    DataFile replacementFile = DataFiles.builder(table.spec()).withPath("/path/to/data-a-replacement.parquet").withFileSizeInBytes(10).withPartitionPath(// easy way to set partition data for now
    "c1=0").withRecordCount(1).build();
    table.newAppend().appendFile(fileA).commit();
    long snapshotId = table.currentSnapshot().snapshotId();
    // stage an overwrite that replaces FILE_A
    table.newReplacePartitions().addFile(replacementFile).stageOnly().commit();
    Snapshot staged = Iterables.getLast(table.snapshots());
    Assert.assertEquals("Should find the staged overwrite snapshot", DataOperations.OVERWRITE, staged.operation());
    // add another append so that the original commit can't be fast-forwarded
    table.newAppend().appendFile(fileB).commit();
    // test cherry pick
    sql("ALTER TABLE tl SET('cherry-pick-snapshot-id'='%s')", staged.snapshotId());
    validateTableFiles(table, fileB, replacementFile);
    // test set current snapshot
    sql("ALTER TABLE tl SET('current-snapshot-id'='%s')", snapshotId);
    validateTableFiles(table, fileA);
}

