@ParameterizedTest
@ValueSource(ints = { 1, 2 })
public void testReplaceTxnBuilder(int formatVersion) {
    Schema schema = getTestSchema();
    PartitionSpec spec = PartitionSpec.builderFor(schema).bucket("data", 16).build();
    TableIdentifier tableIdent = TableIdentifier.of(DB_NAME, "tbl");
    String location = temp.resolve("tbl").toString();
    try {
        Transaction createTxn = catalog.buildTable(tableIdent, schema).withPartitionSpec(spec).withLocation(location).withProperty("key1", "value1").withProperty(TableProperties.FORMAT_VERSION, String.valueOf(formatVersion)).createOrReplaceTransaction();
        createTxn.commitTransaction();
        Table table = catalog.loadTable(tableIdent);
        assertThat(table.spec().fields()).hasSize(1);
        String newLocation = temp.resolve("tbl-2").toString();
        Transaction replaceTxn = catalog.buildTable(tableIdent, schema).withProperty("key2", "value2").withLocation(newLocation).replaceTransaction();
        replaceTxn.commitTransaction();
        table = catalog.loadTable(tableIdent);
        assertThat(table.location()).isEqualTo(newLocation);
        assertThat(table.currentSnapshot()).isNull();
        if (formatVersion == 1) {
            PartitionSpec v1Expected = PartitionSpec.builderFor(table.schema()).alwaysNull("data", "data_bucket").withSpecId(1).build();
            assertThat(table.spec()).as("Table should have a spec with one void field").isEqualTo(v1Expected);
        } else {
            assertThat(table.spec().isUnpartitioned()).as("Table spec must be unpartitioned").isTrue();
        }
        assertThat(table.properties()).containsEntry("key1", "value1");
        assertThat(table.properties()).containsEntry("key2", "value2");
    } finally {
        catalog.dropTable(tableIdent);
    }
}

