    Expression expr = and(and(and(lessThan("int", 1), lessThanOrEqual("long", 100)), and(greaterThan("float", 5.0), greaterThanOrEqual("double", 500.0))), and(and(equal("boolean", true), notEqual("string", "test")), and(in("decimal", BigDecimal.valueOf(-12345, 2), BigDecimal.valueOf(12345, 2)), notIn("time", 100L, 200L))), and(isNaN("float2"), notNaN("double2")));
    Expression boundFilter = Binder.bind(schema.asStruct(), expr, true);
