@Test
public void testUsingFileIO() throws IOException {
    // When files other than HadoopInputFile and HadoopOutputFile are supplied the location
    // is used to determine the corresponding FileSystem class based on the scheme in case of
    // local files that would be the LocalFileSystem. To prevent this we use the Proxy classes to
    // use a scheme `dummy` that is not handled. Note that Hadoop 2.7.3 throws IOException
    // while latest Hadoop versions throw UnsupportedFileSystemException (extends IOException)
    ProxyOutputFile outFile = new ProxyOutputFile(Files.localOutput(temp));
    Assertions.assertThatThrownBy(() -> new Path(outFile.location()).getFileSystem(new Configuration())).isInstanceOf(IOException.class).hasMessageStartingWith("No FileSystem for scheme");
    // Given that FileIO is now handled there is no determination of FileSystem based on scheme
    // but instead operations are handled by the InputFileSystem and OutputFileSystem that wrap
    // the InputFile and OutputFile correspondingly. Both write and read should be successful.
    DataWriter<Record> dataWriter = ORC.writeData(outFile).schema(SCHEMA).createWriterFunc(GenericOrcWriter::buildWriter).overwrite().withSpec(PartitionSpec.unpartitioned()).build();
    try {
        for (Record record : records) {
            dataWriter.write(record);
        }
    } finally {
        dataWriter.close();
    }
    DataFile dataFile = dataWriter.toDataFile();
    OrcFile.ReaderOptions options = OrcFile.readerOptions(new Configuration()).filesystem(new FileIOFSUtil.InputFileSystem(outFile.toInputFile())).maxLength(outFile.toInputFile().getLength());
    Assertions.assertThat(dataFile.splitOffsets()).isEqualTo(stripeOffsetsFromReader(dataFile, options));
    Assertions.assertThat(dataFile.format()).isEqualTo(FileFormat.ORC);
    Assertions.assertThat(dataFile.content()).isEqualTo(FileContent.DATA);
    Assertions.assertThat(dataFile.recordCount()).isEqualTo(records.size());
    Assertions.assertThat(dataFile.partition().size()).isEqualTo(0);
    Assertions.assertThat(dataFile.keyMetadata()).isNull();
    List<Record> writtenRecords;
    try (CloseableIterable<Record> reader = ORC.read(outFile.toInputFile()).project(SCHEMA).createReaderFunc(fileSchema -> GenericOrcReader.buildReader(SCHEMA, fileSchema)).build()) {
        writtenRecords = Lists.newArrayList(reader);
    }
    Assertions.assertThat(writtenRecords).as("Written records should match").isEqualTo(records);
}

