@Test
public void testAnd() {
    // this test case must use a real predicate, not alwaysTrue(), otherwise binding will simplify
    // it out
    boolean shouldRead = new ParquetBloomRowGroupFilter(SCHEMA, and(equal("id", INT_MIN_VALUE - 25), equal("id", INT_MIN_VALUE + 30))).shouldRead(parquetSchema, rowGroupMetadata, bloomStore);
    assertThat(shouldRead).as("Should skip: and(false, true)").isFalse();
    shouldRead = new ParquetBloomRowGroupFilter(SCHEMA, and(equal("id", INT_MIN_VALUE - 25), equal("id", INT_MAX_VALUE + 1))).shouldRead(parquetSchema, rowGroupMetadata, bloomStore);
    assertThat(shouldRead).as("Should skip: and(false, false)").isFalse();
    shouldRead = new ParquetBloomRowGroupFilter(SCHEMA, and(equal("id", INT_MIN_VALUE + 25), equal("id", INT_MIN_VALUE))).shouldRead(parquetSchema, rowGroupMetadata, bloomStore);
    assertThat(shouldRead).as("Should read: and(true, true)").isTrue();
    // AND filters that refer different columns ("id", "long", "binary")
    shouldRead = new ParquetBloomRowGroupFilter(SCHEMA, and(equal("id", INT_MIN_VALUE + 25), equal("long", LONG_BASE + 30), equal("binary", RANDOM_BYTES.get(30)))).shouldRead(parquetSchema, rowGroupMetadata, bloomStore);
    assertThat(shouldRead).as("Should read: and(true, true, true)").isTrue();
    // AND filters that refer different columns ("id", "long", "binary")
    shouldRead = new ParquetBloomRowGroupFilter(SCHEMA, and(equal("id", INT_MIN_VALUE - 25), equal("long", LONG_BASE + 30), equal("binary", RANDOM_BYTES.get(30)))).shouldRead(parquetSchema, rowGroupMetadata, bloomStore);
    assertThat(shouldRead).as("Should skip: and(false, true, true)").isFalse();
    // In And, one of the filter's column doesn't have bloom filter
    shouldRead = new ParquetBloomRowGroupFilter(SCHEMA, and(equal("id", INT_MIN_VALUE + 25), equal("long", LONG_BASE + 30), equal("binary", RANDOM_BYTES.get(30)), equal("non_bloom", "a"))).shouldRead(parquetSchema, rowGroupMetadata, bloomStore);
    assertThat(shouldRead).as("Should read: and(true, true, true, true)").isTrue();
    // In And, one of the filter's column doesn't have bloom filter
    shouldRead = new ParquetBloomRowGroupFilter(SCHEMA, and(equal("id", INT_MIN_VALUE - 25), equal("long", LONG_BASE + 30), equal("binary", RANDOM_BYTES.get(30)), equal("non_bloom", "a"))).shouldRead(parquetSchema, rowGroupMetadata, bloomStore);
    assertThat(shouldRead).as("Should skip: and(false, true, true, true)").isFalse();
    // In And, one of the filter's column is not in the file
    shouldRead = new ParquetBloomRowGroupFilter(SCHEMA, and(equal("id", INT_MIN_VALUE + 25), equal("long", LONG_BASE + 30), equal("binary", RANDOM_BYTES.get(30)), equal("not_in_file", 1.0f))).shouldRead(parquetSchema, rowGroupMetadata, bloomStore);
    assertThat(shouldRead).as("Should read: and(true, true, true, true)").isTrue();
    // In And, one of the filter's column is not in the file
    shouldRead = new ParquetBloomRowGroupFilter(SCHEMA, and(equal("id", INT_MIN_VALUE - 25), equal("long", LONG_BASE + 30), equal("binary", RANDOM_BYTES.get(30)), equal("not_in_file", 1.0f))).shouldRead(parquetSchema, rowGroupMetadata, bloomStore);
    assertThat(shouldRead).as("Should skip: and(false, true, true, true)").isFalse();
}

