@Test
public void testIntegerIn() {
    // only one value is present
    for (int i = 0; i < INT_VALUE_COUNT; i++) {
        boolean shouldRead = new ParquetBloomRowGroupFilter(SCHEMA, in("id", INT_MIN_VALUE - 3 * i, INT_MIN_VALUE + i, INT_MAX_VALUE + 3 * i)).shouldRead(parquetSchema, rowGroupMetadata, bloomStore);
        assertThat(shouldRead).as("Should read: integer within range").isTrue();
    }
    // all values are present
    boolean shouldRead = new ParquetBloomRowGroupFilter(SCHEMA, in("id", IntStream.range(INT_MIN_VALUE - 10, INT_MAX_VALUE + 10).boxed().collect(Collectors.toList()))).shouldRead(parquetSchema, rowGroupMetadata, bloomStore);
    assertThat(shouldRead).as("Should read: the bloom is a subset of the in set").isTrue();
    // all values are present
    shouldRead = new ParquetBloomRowGroupFilter(SCHEMA, in("id", IntStream.range(INT_MIN_VALUE, INT_MAX_VALUE).boxed().collect(Collectors.toList()))).shouldRead(parquetSchema, rowGroupMetadata, bloomStore);
    assertThat(shouldRead).as("Should read: the bloom is equal to the in set").isTrue();
    // no values are present
    shouldRead = new ParquetBloomRowGroupFilter(SCHEMA, in("id", IntStream.range(INT_MIN_VALUE - 10, INT_MIN_VALUE - 1).boxed().collect(Collectors.toList()))).shouldRead(parquetSchema, rowGroupMetadata, bloomStore);
    assertThat(shouldRead).as("Should not read: value outside range").isFalse();
}

@Test
public void testOtherTypesIn() {
    boolean shouldRead = new ParquetBloomRowGroupFilter(SCHEMA, in("all_nulls", 1, 2)).shouldRead(parquetSchema, rowGroupMetadata, bloomStore);
    assertThat(shouldRead).as("Should not read: in on all nulls column (bloom is empty) ").isFalse();
    shouldRead = new ParquetBloomRowGroupFilter(SCHEMA, in("some_nulls", "aaa", "some")).shouldRead(parquetSchema, rowGroupMetadata, bloomStore);
