@Test
public void mapConversions() throws IOException {
    // consistent behavior for maps conversions. The below test case, correctly does not specify map
    // key types
    convertToPigSchema(new Schema(required(1, "a", MapType.ofRequired(2, 3, StringType.get(), ListType.ofRequired(4, StructType.of(required(5, "b", LongType.get()), required(6, "c", StringType.get())))))), "a:[{(b:long,c:chararray)}]", "We do not specify the map key type here");
    // struct<a:map<string,map<string,double>>> -> (a:[[double]])
    // As per https://pig.apache.org/docs/latest/basic.html#map-schema. It seems that
    // we  only need to specify value type as keys are always of type chararray
    convertToPigSchema(new Schema(StructType.of(required(1, "a", MapType.ofRequired(2, 3, StringType.get(), MapType.ofRequired(4, 5, StringType.get(), DoubleType.get())))).fields()), "a:[[double]]", "A map key type does not need to be specified");
}

@Test
public void testTupleInMap() throws IOException {
