@Test
public void doubleWrappingTuples() throws IOException {
    // struct<a:array<struct<b:string>>> -> (a:{(b:chararray)})
    convertToPigSchema(new Schema(StructType.of(required(1, "a", ListType.ofRequired(2, StructType.of(required(3, "b", StringType.get()))))).fields()), "a:{(b:chararray)}", "A tuple inside a bag should not be double wrapped");
    // struct<a:array<boolean>> -> "(a:{(boolean)})
    convertToPigSchema(new Schema(StructType.of(required(1, "a", ListType.ofRequired(2, BooleanType.get()))).fields()), "a:{(boolean)}", "boolean (or anything non-tuple) element inside a bag should be wrapped inside a tuple");
}

