@Test
public void testTwoLevelList() throws IOException {
    spark.conf().set("spark.sql.parquet.writeLegacyFormat", true);
    String tableName = sourceName("testTwoLevelList");
    File location = temp.newFolder();
    StructType sparkSchema = new StructType(new StructField[] { new StructField("col1", new ArrayType(new StructType(new StructField[] { new StructField("col2", DataTypes.IntegerType, false, Metadata.empty()) }), false), true, Metadata.empty()) });
    // even though this list looks like three level list, it is actually a 2-level list where the
    // items are
    // structs with 1 field.
    String expectedParquetSchema = "message spark_schema {\n" + "  optional group col1 (LIST) {\n" + "    repeated group array {\n" + "      required int32 col2;\n" + "    }\n" + "  }\n" + "}\n";
    // generate parquet file with required schema
    List<String> testData = Collections.singletonList("{\"col1\": [{\"col2\": 1}]}");
    spark.read().schema(sparkSchema).json(JavaSparkContext.fromSparkContext(spark.sparkContext()).parallelize(testData)).coalesce(1).write().format("parquet").mode(SaveMode.Append).save(location.getPath());
    File parquetFile = Arrays.stream(Preconditions.checkNotNull(location.listFiles(new FilenameFilter() {

        @Override
        public boolean accept(File dir, String name) {
            return name.endsWith("parquet");
        }
    }))).findAny().get();
    // verify generated parquet file has expected schema
    ParquetFileReader pqReader = ParquetFileReader.open(HadoopInputFile.fromPath(new Path(parquetFile.getPath()), spark.sessionState().newHadoopConf()));
    MessageType schema = pqReader.getFooter().getFileMetaData().getSchema();
    Assert.assertEquals(MessageTypeParser.parseMessageType(expectedParquetSchema), schema);
    // create sql table on top of it
    sql("CREATE EXTERNAL TABLE %s (col1 ARRAY<STRUCT<col2 INT>>)" + " STORED AS parquet" + " LOCATION '%s'", tableName, location);
    List<Object[]> expected = sql("select array(struct(1))");
    // migrate table
    SparkActions.get().migrateTable(tableName).execute();
    // check migrated table is returning expected result
    List<Object[]> results = sql("SELECT * FROM %s", tableName);
    Assert.assertFalse(results.isEmpty());
    assertEquals("Output must match", expected, results);
}

@Test
public void dataFilesCleanupWithParallelTasks() {
    table.newFastAppend().appendFile(FILE_A).commit();
    table.newFastAppend().appendFile(FILE_B).commit();
    table.newRewrite().rewriteFiles(ImmutableSet.of(FILE_B), ImmutableSet.of(FILE_D)).commit();
    table.newRewrite().rewriteFiles(ImmutableSet.of(FILE_A), ImmutableSet.of(FILE_C)).commit();
    Set<String> deletedFiles = ConcurrentHashMap.newKeySet();
    Set<String> deleteThreads = ConcurrentHashMap.newKeySet();
    AtomicInteger deleteThreadsIndex = new AtomicInteger(0);
    DeleteReachableFiles.Result result = sparkActions().deleteReachableFiles(metadataLocation(table)).io(table.io()).executeDeleteWith(Executors.newFixedThreadPool(4, runnable -> {
        Thread thread = new Thread(runnable);
        thread.setName("remove-files-" + deleteThreadsIndex.getAndIncrement());
        thread.setDaemon(// daemon threads will be terminated abruptly when the JVM exits
        true);
        return thread;
    })).deleteWith(s -> {
        deleteThreads.add(Thread.currentThread().getName());
        deletedFiles.add(s);
    }).execute();
    // Verifies that the delete methods ran in the threads created by the provided ExecutorService
    // ThreadFactory
    Assert.assertEquals(deleteThreads, Sets.newHashSet("remove-files-0", "remove-files-1", "remove-files-2", "remove-files-3"));
    Lists.newArrayList(FILE_A, FILE_B, FILE_C, FILE_D).forEach(file -> Assert.assertTrue("FILE_A should be deleted", deletedFiles.contains(FILE_A.path().toString())));
    checkRemoveFilesResults(4L, 0, 0, 6L, 4L, 6, result);
}

