    Thread writerThread = new Thread(() -> {
        Map<String, String> properties = ImmutableMap.of("writer-thread", String.valueOf(Thread.currentThread().getName()), SnapshotSummary.EXTRA_METADATA_PREFIX + "extra-key", "someValue", SnapshotSummary.EXTRA_METADATA_PREFIX + "another-key", "anotherValue");
