    df1.select("id", "data").write().format("iceberg").mode("append").save(loadLocation(tableIdentifier));
    table.refresh();
    long firstCommitId = table.currentSnapshot().snapshotId();
    // add a second file
    df2.select("id", "data").write().format("iceberg").mode("append").save(loadLocation(tableIdentifier));
    table.refresh();
    long secondCommitId = table.currentSnapshot().snapshotId();
    // check if rewrite manifest does not override metadata about data file's creating snapshot
    RewriteManifests.Result rewriteManifestResult = SparkActions.get().rewriteManifests(table).execute();
    Assert.assertEquals("rewrite replaced 2 manifests", 2, Iterables.size(rewriteManifestResult.rewrittenManifests()));
    Assert.assertEquals("rewrite added 1 manifests", 1, Iterables.size(rewriteManifestResult.addedManifests()));
    List<Row> actual = spark.read().format("iceberg").load(loadLocation(tableIdentifier, "partitions")).orderBy("partition.id").collectAsList();
    GenericRecordBuilder builder = new GenericRecordBuilder(AvroSchemaUtil.convert(partitionsTable.schema(), "partitions"));
    GenericRecordBuilder partitionBuilder = new GenericRecordBuilder(AvroSchemaUtil.convert(partitionsTable.schema().findType("partition").asStructType(), "partition"));
    List<DataFile> dataFiles = TestHelpers.dataFiles(table);
    assertDataFilePartitions(dataFiles, Arrays.asList(1, 2, 2));
    List<GenericData.Record> expected = Lists.newArrayList();
    expected.add(builder.set("partition", partitionBuilder.set("id", 1).build()).set("record_count", 1L).set("file_count", 1).set("total_data_file_size_in_bytes", dataFiles.get(0).fileSizeInBytes()).set("position_delete_record_count", 0L).set("position_delete_file_count", 0).set("equality_delete_record_count", 0L).set("equality_delete_file_count", 0).set("spec_id", 0).set("last_updated_at", table.snapshot(firstCommitId).timestampMillis() * 1000).set("last_updated_snapshot_id", firstCommitId).build());
    expected.add(builder.set("partition", partitionBuilder.set("id", 2).build()).set("record_count", 2L).set("file_count", 2).set("total_data_file_size_in_bytes", dataFiles.get(1).fileSizeInBytes() + dataFiles.get(2).fileSizeInBytes()).set("position_delete_record_count", 0L).set("position_delete_file_count", 0).set("equality_delete_record_count", 0L).set("equality_delete_file_count", 0).set("spec_id", 0).set("last_updated_at", table.snapshot(secondCommitId).timestampMillis() * 1000).set("last_updated_snapshot_id", secondCommitId).build());
    Assert.assertEquals("Partitions table should have two rows", 2, expected.size());
    Assert.assertEquals("Actual results should have two rows", 2, actual.size());
    for (int i = 0; i < 2; i += 1) {
        TestHelpers.assertEqualsSafe(partitionsTable.schema().asStruct(), expected.get(i), actual.get(i));
    }
    // check predicate push down
    List<Row> filtered = spark.read().format("iceberg").load(loadLocation(tableIdentifier, "partitions")).filter("partition.id < 2").collectAsList();
    Assert.assertEquals("Actual results should have one row", 1, filtered.size());
    TestHelpers.assertEqualsSafe(partitionsTable.schema().asStruct(), expected.get(0), filtered.get(0));
    // check for snapshot expiration
    // if snapshot with firstCommitId is expired,
    // we expect the partition of id=1 will no longer have last updated timestamp and snapshotId
    SparkActions.get().expireSnapshots(table).expireSnapshotId(firstCommitId).execute();
    GenericData.Record newPartitionRecord = builder.set("partition", partitionBuilder.set("id", 1).build()).set("record_count", 1L).set("file_count", 1).set("total_data_file_size_in_bytes", dataFiles.get(0).fileSizeInBytes()).set("position_delete_record_count", 0L).set("position_delete_file_count", 0).set("equality_delete_record_count", 0L).set("equality_delete_file_count", 0).set("spec_id", 0).set("last_updated_at", null).set("last_updated_snapshot_id", null).build();
    expected.remove(0);
    expected.add(0, newPartitionRecord);
    List<Row> actualAfterSnapshotExpiration = spark.read().format("iceberg").load(loadLocation(tableIdentifier, "partitions")).collectAsList();
    Assert.assertEquals("Actual results should have two row", 2, actualAfterSnapshotExpiration.size());
    for (int i = 0; i < 2; i += 1) {
        TestHelpers.assertEqualsSafe(partitionsTable.schema().asStruct(), expected.get(i), actualAfterSnapshotExpiration.get(i));
    }
}

