    1).set("equality_delete_record_count", 0L).set("equality_delete_file_count", 0).set("spec_id", 0).set("last_updated_at", table.snapshot(posDeleteCommitId).timestampMillis() * 1000).set("last_updated_snapshot_id", posDeleteCommitId).build());
