    String query = String.format("SELECT f.* FROM %s f JOIN dim d ON f.date = d.date AND d.id = 1 ORDER BY id", tableName);
    assertQueryContainsRuntimeFilter(query);
    deleteNotMatchingFiles(Expressions.equal("date", 1), 3);
