    Dataset<Row> df1 = spark.range(1, 100).withColumn("date", date_add(expr("DATE '1970-01-01'"), expr("CAST(id % 2 AS INT)"))).withColumn("ts", expr("TO_TIMESTAMP(date)")).withColumn("data", expr("CAST(date AS STRING)")).select("id", "data", "date", "ts");
    df1.coalesce(1).writeTo(tableName).append();
    Table table = validationCatalog.loadTable(tableIdent);
    table.updateSpec().addField(Expressions.bucket("id", 8)).commit();
    sql("REFRESH TABLE %s", tableName);
    Dataset<Row> df2 = spark.range(1, 100).withColumn("date", date_add(expr("DATE '1970-01-01'"), expr("CAST(id % 4 AS INT)"))).withColumn("ts", expr("TO_TIMESTAMP(date)")).withColumn("data", expr("CAST(date AS STRING)")).select("id", "data", "date", "ts");
    df2.coalesce(1).writeTo(tableName).option(SparkWriteOptions.FANOUT_ENABLED, "true").append();
    sql("CREATE TABLE dim (id BIGINT, date DATE) USING parquet");
    Dataset<Row> dimDF = spark.range(1, 2).withColumn("date", expr("DATE '1970-01-02'")).select("id", "date");
    dimDF.coalesce(1).write().mode("append").insertInto("dim");
    String query = String.format("SELECT f.* FROM %s f JOIN dim d ON f.id = d.id AND d.date = DATE '1970-01-02' ORDER BY date", tableName);
    assertQueryContainsRuntimeFilter(query);
    deleteNotMatchingFiles(Expressions.equal("id", 1), 7);
    assertEquals("Should have expected rows", sql("SELECT * FROM %s WHERE id = 1 ORDER BY date", tableName), sql(query));
}

