    "4").commit();
    List<SimpleRecord> expected = Lists.newArrayListWithCapacity(4000);
    for (int i = 0; i < 4000; i++) {
        expected.add(new SimpleRecord(i, "a"));
    }
    Dataset<Row> df = spark.createDataFrame(expected, SimpleRecord.class);
