@Test
public void testWriteWithOutputSpec() throws NoSuchTableException {
    Table table = validationCatalog.loadTable(tableIdent);
    // Drop all records in table to have a fresh start.
    table.newDelete().deleteFromRowFilter(Expressions.alwaysTrue()).commit();
    final int originalSpecId = table.spec().specId();
    table.updateSpec().addField("data").commit();
    // Refresh this when using SparkCatalog since otherwise the new spec would not be caught.
    sql("REFRESH TABLE %s", tableName);
    // By default, we write to the current spec.
    List<SimpleRecord> data = ImmutableList.of(new SimpleRecord(10, "a"));
    spark.createDataFrame(data, SimpleRecord.class).toDF().writeTo(tableName).append();
    List<Object[]> expected = ImmutableList.of(row(10L, "a", table.spec().specId()));
    assertEquals("Rows must match", expected, sql("SELECT id, data, _spec_id FROM %s WHERE id >= 10 ORDER BY id", tableName));
    // Output spec ID should be respected when present.
    data = ImmutableList.of(new SimpleRecord(11, "b"), new SimpleRecord(12, "c"));
    spark.createDataFrame(data, SimpleRecord.class).toDF().writeTo(tableName).option("output-spec-id", Integer.toString(originalSpecId)).append();
    expected = ImmutableList.of(row(10L, "a", table.spec().specId()), row(11L, "b", originalSpecId), row(12L, "c", originalSpecId));
    assertEquals("Rows must match", expected, sql("SELECT id, data, _spec_id FROM %s WHERE id >= 10 ORDER BY id", tableName));
    // Verify that the actual partitions are written with the correct spec ID.
    // Two of the partitions should have the original spec ID and one should have the new one.
    Dataset<Row> actualPartitionRows = spark.read().format("iceberg").load(tableName + ".partitions").select("spec_id", "partition.id_trunc", "partition.data").orderBy("spec_id", "partition.id_trunc");
    expected = ImmutableList.of(row(originalSpecId, 9L, null), row(originalSpecId, 12L, null), row(table.spec().specId(), 9L, "a"));
    assertEquals("There are 3 partitions, one with the original spec ID and two with the new one", expected, rowsToJava(actualPartitionRows.collectAsList()));
    // Even the default spec ID should be followed when present.
    data = ImmutableList.of(new SimpleRecord(13, "d"));
    spark.createDataFrame(data, SimpleRecord.class).toDF().writeTo(tableName).option("output-spec-id", Integer.toString(table.spec().specId())).append();
    expected = ImmutableList.of(row(10L, "a", table.spec().specId()), row(11L, "b", originalSpecId), row(12L, "c", originalSpecId), row(13L, "d", table.spec().specId()));
    assertEquals("Rows must match", expected, sql("SELECT id, data, _spec_id FROM %s WHERE id >= 10 ORDER BY id", tableName));
}

