    sql("ALTER TABLE %s ADD PARTITION FIELD days(ts) AS day_col", tableName);
    table.refresh();
    PartitionSpec expected = PartitionSpec.builderFor(table.schema()).withSpecId(1).day("ts", "day_col").build();
    Assert.assertEquals("Should have new spec field", expected, table.spec());
    sql("ALTER TABLE %s REPLACE PARTITION FIELD day_col WITH hours(ts) AS hour_col", tableName);
    table.refresh();
    if (formatVersion == 1) {
        expected = PartitionSpec.builderFor(table.schema()).withSpecId(2).alwaysNull("ts", "day_col").hour("ts", "hour_col").build();
    } else {
        expected = PartitionSpecParser.fromJson(table.schema(), "{\n" + "  \"spec-id\" : 2,\n" + "  \"fields\" : [ {\n" + "    \"name\" : \"hour_col\",\n" + "    \"transform\" : \"hour\",\n" + "    \"source-id\" : 3,\n" + "    \"field-id\" : 1001\n" + "  } ]\n" + "}");
    }
    Assert.assertEquals("Should changed from daily to hourly partitioned field", expected, table.spec());
}

