@Test
public void testExpireSnapshotsWithStatisticFiles() throws Exception {
    sql("CREATE TABLE %s (id bigint NOT NULL, data string) USING iceberg", tableName);
    sql("INSERT INTO TABLE %s VALUES (10, 'abc')", tableName);
    Table table = validationCatalog.loadTable(tableIdent);
    String statsFileLocation1 = statsFileLocation(table.location());
    StatisticsFile statisticsFile1 = writeStatsFile(table.currentSnapshot().snapshotId(), table.currentSnapshot().sequenceNumber(), statsFileLocation1, table.io());
    table.updateStatistics().setStatistics(statisticsFile1.snapshotId(), statisticsFile1).commit();
    sql("INSERT INTO %s SELECT 20, 'def'", tableName);
    table.refresh();
    String statsFileLocation2 = statsFileLocation(table.location());
    StatisticsFile statisticsFile2 = writeStatsFile(table.currentSnapshot().snapshotId(), table.currentSnapshot().sequenceNumber(), statsFileLocation2, table.io());
    table.updateStatistics().setStatistics(statisticsFile2.snapshotId(), statisticsFile2).commit();
    waitUntilAfter(table.currentSnapshot().timestampMillis());
    Timestamp currentTimestamp = Timestamp.from(Instant.ofEpochMilli(System.currentTimeMillis()));
    List<Object[]> output = sql("CALL %s.system.expire_snapshots(older_than => TIMESTAMP '%s',table => '%s')", catalogName, currentTimestamp, tableIdent);
    Assertions.assertThat(output.get(0)[5]).as("should be 1 deleted statistics file").isEqualTo(1L);
    table.refresh();
    List<StatisticsFile> statsWithSnapshotId1 = table.statisticsFiles().stream().filter(statisticsFile -> statisticsFile.snapshotId() == statisticsFile1.snapshotId()).collect(Collectors.toList());
    Assertions.assertThat(statsWithSnapshotId1).as("Statistics file entry in TableMetadata should be deleted for the snapshot %s", statisticsFile1.snapshotId()).isEmpty();
    Assertions.assertThat(table.statisticsFiles()).as("Statistics file entry in TableMetadata should be present for the snapshot %s", statisticsFile2.snapshotId()).extracting(StatisticsFile::snapshotId).containsExactly(statisticsFile2.snapshotId());
    Assertions.assertThat(new File(statsFileLocation1)).as("Statistics file should not exist for snapshot %s", statisticsFile1.snapshotId()).doesNotExist();
    Assertions.assertThat(new File(statsFileLocation2)).as("Statistics file should exist for snapshot %s", statisticsFile2.snapshotId()).exists();
}

@Test
public void testTruncateExpressions() {
    sql("CREATE TABLE %s ( " + "  int_c INT, long_c LONG, dec_c DECIMAL(4, 2), str_c STRING, binary_c BINARY " + ") USING iceberg", tableName);
    sql("CREATE TEMPORARY VIEW emp " + "AS SELECT * FROM VALUES (101, 10001, 10.65, '101-Employee', CAST('1234' AS BINARY)) " + "AS EMP(int_c, long_c, dec_c, str_c, binary_c)");
    sql("INSERT INTO %s SELECT * FROM emp", tableName);
    Dataset<Row> df = spark.sql("SELECT * FROM " + tableName);
    df.select(new Column(new IcebergTruncateTransform(df.col("int_c").expr(), 2)).as("int_c"), new Column(new IcebergTruncateTransform(df.col("long_c").expr(), 2)).as("long_c"), new Column(new IcebergTruncateTransform(df.col("dec_c").expr(), 50)).as("dec_c"), new Column(new IcebergTruncateTransform(df.col("str_c").expr(), 2)).as("str_c"), new Column(new IcebergTruncateTransform(df.col("binary_c").expr(), 2)).as("binary_c")).createOrReplaceTempView("v");
    assertEquals("Should have expected rows", ImmutableList.of(row(100, 10000L, new BigDecimal("10.50"), "10", "12")), sql("SELECT int_c, long_c, dec_c, str_c, CAST(binary_c AS STRING) FROM v"));
}

