    ExecutorService executorService = MoreExecutors.getExitingExecutorService((ThreadPoolExecutor) Executors.newFixedThreadPool(2));
    AtomicInteger barrier = new AtomicInteger(0);
    AtomicBoolean shouldAppend = new AtomicBoolean(true);
    // merge thread
    Future<?> mergeFuture = executorService.submit(() -> {
        for (int numOperations = 0; numOperations < 20; numOperations++) {
            while (barrier.get() < numOperations * 2) {
                sleep(10);
            }
            sql("MERGE INTO %s t USING source s " + "ON t.id == s.value " + "WHEN MATCHED THEN " + "  UPDATE SET dep = 'x'", tableName);
            barrier.incrementAndGet();
        }
    });
    // append thread
    Future<?> appendFuture = executorService.submit(() -> {
        // load the table via the validation catalog to use another table instance for inserts
        Table table = validationCatalog.loadTable(tableIdent);
        GenericRecord record = GenericRecord.create(table.schema());
        // id
        record.set(0, 1);
        // dep
        record.set(1, "hr");
        for (int numOperations = 0; numOperations < 20; numOperations++) {
            while (shouldAppend.get() && barrier.get() < numOperations * 2) {
                sleep(10);
            }
            if (!shouldAppend.get()) {
                return;
            }
            for (int numAppends = 0; numAppends < 5; numAppends++) {
                DataFile dataFile = writeDataFile(table, ImmutableList.of(record));
                table.newFastAppend().appendFile(dataFile).commit();
                sleep(10);
            }
            barrier.incrementAndGet();
        }
    });
