@Test
public void testCommitUnknownException() {
    createAndInitTable("id INT, dep STRING, category STRING");
    // write unpartitioned files
    append(tableName, "{ \"id\": 1, \"dep\": \"hr\", \"category\": \"c1\"}");
    append(tableName, "{ \"id\": 2, \"dep\": \"hr\", \"category\": \"c1\" }\n" + "{ \"id\": 3, \"dep\": \"hr\", \"category\": \"c1\" }");
    Table table = validationCatalog.loadTable(tableIdent);
    RowDelta newRowDelta = table.newRowDelta();
    RowDelta spyNewRowDelta = spy(newRowDelta);
    doAnswer(invocation -> {
        newRowDelta.commit();
        throw new CommitStateUnknownException(new RuntimeException("Datacenter on Fire"));
    }).when(spyNewRowDelta).commit();
    Table spyTable = spy(table);
    when(spyTable.newRowDelta()).thenReturn(spyNewRowDelta);
    SparkTable sparkTable = new SparkTable(spyTable, false);
    ImmutableMap<String, String> config = ImmutableMap.of("type", "hive", "default-namespace", "default");
    spark.conf().set("spark.sql.catalog.dummy_catalog", "org.apache.iceberg.spark.source.TestSparkCatalog");
    config.forEach((key, value) -> spark.conf().set("spark.sql.catalog.dummy_catalog." + key, value));
    Identifier ident = Identifier.of(new String[] { "default" }, "table");
    TestSparkCatalog.setTable(ident, sparkTable);
    // Although an exception is thrown here, write and commit have succeeded
    AssertHelpers.assertThrowsWithCause("Should throw a Commit State Unknown Exception", SparkException.class, "Writing job aborted", CommitStateUnknownException.class, "Datacenter on Fire", () -> sql("DELETE FROM %s WHERE id = 2", "dummy_catalog.default.table"));
    // Since write and commit succeeded, the rows should be readable
    assertEquals("Should have expected rows", ImmutableList.of(row(1, "hr", "c1"), row(3, "hr", "c1")), sql("SELECT * FROM %s ORDER BY id", "dummy_catalog.default.table"));
}

@Test
public void testUnpartitionedTable() throws Exception {
    sql("CREATE TABLE %s (id bigint, data string) USING iceberg TBLPROPERTIES" + "('format-version'='2', 'write.delete.mode'='merge-on-read')", tableName);
    List<SimpleRecord> records = Lists.newArrayList(new SimpleRecord(1, "a"), new SimpleRecord(2, "b"), new SimpleRecord(3, "c"), new SimpleRecord(4, "d"));
    spark.createDataset(records, Encoders.bean(SimpleRecord.class)).coalesce(1).writeTo(tableName).append();
    sql("DELETE FROM %s WHERE id=1", tableName);
    Table table = Spark3Util.loadIcebergTable(spark, tableName);
    List<ManifestFile> expectedDataManifests = TestHelpers.dataManifests(table);
    List<ManifestFile> expectedDeleteManifests = TestHelpers.deleteManifests(table);
    Assert.assertEquals("Should have 1 data manifest", 1, expectedDataManifests.size());
    Assert.assertEquals("Should have 1 delete manifest", 1, expectedDeleteManifests.size());
    Schema entriesTableSchema = Spark3Util.loadIcebergTable(spark, tableName + ".entries").schema();
    Schema filesTableSchema = Spark3Util.loadIcebergTable(spark, tableName + ".files").schema();
    // check delete files table
    Dataset<Row> actualDeleteFilesDs = spark.sql("SELECT * FROM " + tableName + ".delete_files");
    List<Row> actualDeleteFiles = TestHelpers.selectNonDerived(actualDeleteFilesDs).collectAsList();
    Assert.assertEquals("Metadata table should return one delete file", 1, actualDeleteFiles.size());
    List<Record> expectedDeleteFiles = expectedEntries(table, FileContent.POSITION_DELETES, entriesTableSchema, expectedDeleteManifests, null);
    Assert.assertEquals("Should be one delete file manifest entry", 1, expectedDeleteFiles.size());
    TestHelpers.assertEqualsSafe(TestHelpers.nonDerivedSchema(actualDeleteFilesDs), expectedDeleteFiles.get(0), actualDeleteFiles.get(0));
    // check data files table
    Dataset<Row> actualDataFilesDs = spark.sql("SELECT * FROM " + tableName + ".data_files");
    List<Row> actualDataFiles = TestHelpers.selectNonDerived(actualDataFilesDs).collectAsList();
    Assert.assertEquals("Metadata table should return one data file", 1, actualDataFiles.size());
    List<Record> expectedDataFiles = expectedEntries(table, FileContent.DATA, entriesTableSchema, expectedDataManifests, null);
    Assert.assertEquals("Should be one data file manifest entry", 1, expectedDataFiles.size());
    TestHelpers.assertEqualsSafe(TestHelpers.nonDerivedSchema(actualDataFilesDs), expectedDataFiles.get(0), actualDataFiles.get(0));
    // check all files table
