@Test
public void testBatchAppend() throws Exception {
    String dataLocation = temp.newFolder().toString();
    sql("CREATE TABLE %s (id INT, data STRING) " + "USING iceberg " + "PARTITIONED BY (data)" + "TBLPROPERTIES ('%s' '%s')", tableName, TableProperties.WRITE_DATA_LOCATION, dataLocation);
    List<SimpleRecord> records = ImmutableList.of(new SimpleRecord(1, "a"), new SimpleRecord(2, "b"), new SimpleRecord(3, "a"), new SimpleRecord(4, "b"));
    Dataset<Row> inputDF = spark.createDataFrame(records, SimpleRecord.class);
    AssertHelpers.assertThrows("Write must fail", SparkException.class, "Writing job aborted", () -> {
        try {
            // incoming records are not ordered by partitions so the job must fail
            inputDF.coalesce(1).sortWithinPartitions("id").writeTo(tableName).option(SparkWriteOptions.USE_TABLE_DISTRIBUTION_AND_ORDERING, "false").append();
        } catch (NoSuchTableException e) {
            throw new RuntimeException(e);
        }
    });
    assertEquals("Should be no records", sql("SELECT * FROM %s", tableName), ImmutableList.of());
    assertEquals("Should be no orphan data files", ImmutableList.of(), sql("CALL %s.system.remove_orphan_files(table => '%s', older_than => %dL, location => '%s')", catalogName, tableName, System.currentTimeMillis() + 5000, dataLocation));
}

