    long t4 = rightAfterSnapshot();
    Set<String> deletedFiles = Sets.newHashSet();
    Set<String> deleteThreads = ConcurrentHashMap.newKeySet();
    AtomicInteger deleteThreadsIndex = new AtomicInteger(0);
    ExpireSnapshots.Result result = SparkActions.get().expireSnapshots(table).executeDeleteWith(Executors.newFixedThreadPool(4, runnable -> {
        Thread thread = new Thread(runnable);
        thread.setName("remove-snapshot-" + deleteThreadsIndex.getAndIncrement());
        thread.setDaemon(// daemon threads will be terminated abruptly when the JVM exits
        true);
        return thread;
    })).expireOlderThan(t4).deleteWith(s -> {
        deleteThreads.add(Thread.currentThread().getName());
        deletedFiles.add(s);
    }).execute();
    // Verifies that the delete methods ran in the threads created by the provided ExecutorService
    // ThreadFactory
    Assert.assertEquals(deleteThreads, Sets.newHashSet("remove-snapshot-0", "remove-snapshot-1", "remove-snapshot-2", "remove-snapshot-3"));
    Assert.assertTrue("FILE_A should be deleted", deletedFiles.contains(FILE_A.path().toString()));
    Assert.assertTrue("FILE_B should be deleted", deletedFiles.contains(FILE_B.path().toString()));
    checkExpirationResults(2L, 0L, 0L, 3L, 3L, result);
}

