@Test
public void testRemoveOrphanFilesWithStatisticFiles() throws Exception {
    Table table = TABLES.create(SCHEMA, PartitionSpec.unpartitioned(), ImmutableMap.of(TableProperties.FORMAT_VERSION, "2"), tableLocation);
    List<ThreeColumnRecord> records = Lists.newArrayList(new ThreeColumnRecord(1, "AAAAAAAAAA", "AAAA"));
    Dataset<Row> df = spark.createDataFrame(records, ThreeColumnRecord.class).coalesce(1);
    df.select("c1", "c2", "c3").write().format("iceberg").mode("append").save(tableLocation);
    table.refresh();
    long snapshotId = table.currentSnapshot().snapshotId();
    long snapshotSequenceNumber = table.currentSnapshot().sequenceNumber();
    File statsLocation = new File(new URI(tableLocation)).toPath().resolve("data").resolve("some-stats-file").toFile();
    StatisticsFile statisticsFile;
    try (PuffinWriter puffinWriter = Puffin.write(Files.localOutput(statsLocation)).build()) {
        puffinWriter.add(new Blob("some-blob-type", ImmutableList.of(1), snapshotId, snapshotSequenceNumber, ByteBuffer.wrap("blob content".getBytes(StandardCharsets.UTF_8))));
        puffinWriter.finish();
        statisticsFile = new GenericStatisticsFile(snapshotId, statsLocation.toString(), puffinWriter.fileSize(), puffinWriter.footerSize(), puffinWriter.writtenBlobsMetadata().stream().map(GenericBlobMetadata::from).collect(ImmutableList.toImmutableList()));
    }
    Transaction transaction = table.newTransaction();
    transaction.updateStatistics().setStatistics(snapshotId, statisticsFile).commit();
    transaction.commitTransaction();
    SparkActions.get().deleteOrphanFiles(table).olderThan(System.currentTimeMillis() + 1000).execute();
    Assertions.assertThat(statsLocation.exists()).as("stats file should exist").isTrue();
    Assertions.assertThat(statsLocation.length()).as("stats file length").isEqualTo(statisticsFile.fileSizeInBytes());
    transaction = table.newTransaction();
    transaction.updateStatistics().removeStatistics(statisticsFile.snapshotId()).commit();
    transaction.commitTransaction();
    DeleteOrphanFiles.Result result = SparkActions.get().deleteOrphanFiles(table).olderThan(System.currentTimeMillis() + 1000).execute();
    Iterable<String> orphanFileLocations = result.orphanFileLocations();
    Assertions.assertThat(orphanFileLocations).as("Should be orphan files").hasSize(1);
    Assertions.assertThat(Iterables.getOnlyElement(orphanFileLocations)).as("Deleted file").isEqualTo(statsLocation.toURI().toString());
    Assertions.assertThat(statsLocation.exists()).as("stats file should be deleted").isFalse();
}

