    Assert.assertEquals(4000, expectedDeletes.size());
    // 4 * 4000 - 4000
    Assert.assertEquals(12000, expectedRecords.size());
    Result result = SparkActions.get(spark).rewritePositionDeletes(table).option(SizeBasedFileRewriter.REWRITE_ALL, "true").execute();
