public void testMergeSchemaFailsWithoutWriterOption() throws Exception {
    sql("ALTER TABLE %s SET TBLPROPERTIES ('%s'='true')", tableName, TableProperties.SPARK_WRITE_ACCEPT_ANY_SCHEMA);
