        appender.addAll(expected);
    }
    // add the Avro data file to the source table
    source.newAppend().appendFile(DataFiles.builder(PartitionSpec.unpartitioned()).withRecordCount(10).withInputFile(Files.localInput(avroData)).build()).commit();
    Dataset<Row> sourceDF = spark.read().format("iceberg").option(SparkReadOptions.VECTORIZATION_ENABLED, String.valueOf(vectorized)).load(sourceLocation);
    for (String column : columnNames) {
