    List<Object[]> actual = sql(select, tableName);
    List<Object[]> expected = Lists.newArrayList();
    expected.add(new Object[] { 6L, Float.NaN, 1.0F, 6L });
    assertEquals("expected and actual should equal", expected, actual);
