@Test
public void testInfinity() {
    sql("CREATE TABLE %s (id int, data1 float, data2 double, data3 double) USING iceberg PARTITIONED BY (id)", tableName);
    sql("INSERT INTO %s VALUES (1, float('-infinity'), double('infinity'), 1.23), " + "(1, float('-infinity'), double('infinity'), -1.23), " + "(1, float('-infinity'), double('infinity'), double('infinity')), " + "(1, float('-infinity'), double('infinity'), 2.23), " + "(1, float('-infinity'), double('infinity'), double('-infinity')), " + "(1, float('-infinity'), double('infinity'), -2.23)", tableName);
    String select = "SELECT count(*), max(data1), min(data1), count(data1), max(data2), min(data2), count(data2), max(data3), min(data3), count(data3) FROM %s";
    List<Object[]> explain = sql("EXPLAIN " + select, tableName);
    String explainString = explain.get(0)[0].toString().toLowerCase(Locale.ROOT);
    boolean explainContainsPushDownAggregates = false;
    if (explainString.contains("max(data1)") && explainString.contains("min(data1)") && explainString.contains("count(data1)") && explainString.contains("max(data2)") && explainString.contains("min(data2)") && explainString.contains("count(data2)") && explainString.contains("max(data3)") && explainString.contains("min(data3)") && explainString.contains("count(data3)")) {
        explainContainsPushDownAggregates = true;
    }
    Assert.assertTrue("explain should contain the pushed down aggregates", explainContainsPushDownAggregates);
    List<Object[]> actual = sql(select, tableName);
    List<Object[]> expected = Lists.newArrayList();
    expected.add(new Object[] { 6L, Float.NEGATIVE_INFINITY, Float.NEGATIVE_INFINITY, 6L, Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY, 6L, Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY, 6L });
    assertEquals("min/max/count push down", expected, actual);
}

