@Test
public void addAvroFile() throws Exception {
    // Spark Session Catalog cannot load metadata tables
    // with "The namespace in session catalog must have exactly one name part"
    Assume.assumeFalse(catalogName.equals("spark_catalog"));
    // Create an Avro file
    Schema schema = SchemaBuilder.record("record").fields().requiredInt("id").requiredString("data").endRecord();
    GenericRecord record1 = new GenericData.Record(schema);
    record1.put("id", 1L);
    record1.put("data", "a");
    GenericRecord record2 = new GenericData.Record(schema);
    record2.put("id", 2L);
    record2.put("data", "b");
    File outputFile = temp.newFile("test.avro");
    DatumWriter<GenericRecord> datumWriter = new GenericDatumWriter(schema);
    DataFileWriter<GenericRecord> dataFileWriter = new DataFileWriter(datumWriter);
    dataFileWriter.create(schema, outputFile);
    dataFileWriter.append(record1);
    dataFileWriter.append(record2);
    dataFileWriter.close();
    String createIceberg = "CREATE TABLE %s (id Long, data String) USING iceberg";
    sql(createIceberg, tableName);
    List<Object[]> result = sql("CALL %s.system.add_files('%s', '`avro`.`%s`')", catalogName, tableName, outputFile.getPath());
    assertEquals("Procedure output must match", ImmutableList.of(row(1L, 1L)), result);
    List<Object[]> expected = Lists.newArrayList(new Object[] { 1L, "a" }, new Object[] { 2L, "b" });
    assertEquals("Iceberg table contains correct data", expected, sql("SELECT * FROM %s ORDER BY id", tableName));
    List<Object[]> actualRecordCount = sql("select %s from %s.files", DataFile.RECORD_COUNT.name(), tableName);
    List<Object[]> expectedRecordCount = Lists.newArrayList();
    expectedRecordCount.add(new Object[] { 2L });
    assertEquals("Iceberg file metadata should have correct metadata count", expectedRecordCount, actualRecordCount);
}

