@Test
public void testQueryWithTimeRange() {
    createTable();
    sql("INSERT INTO %s VALUES (1, 'a')", tableName);
    Table table = validationCatalog.loadTable(tableIdent);
    Snapshot snap1 = table.currentSnapshot();
    long rightAfterSnap1 = waitUntilAfter(snap1.timestampMillis());
    sql("INSERT INTO %s VALUES (2, 'b')", tableName);
    table.refresh();
    Snapshot snap2 = table.currentSnapshot();
    long rightAfterSnap2 = waitUntilAfter(snap2.timestampMillis());
    sql("INSERT OVERWRITE %s VALUES (-2, 'b')", tableName);
    table.refresh();
    Snapshot snap3 = table.currentSnapshot();
    long rightAfterSnap3 = waitUntilAfter(snap3.timestampMillis());
    assertEquals("Should have expected changed rows only from snapshot 3", ImmutableList.of(row(2, "b", "DELETE", 0, snap3.snapshotId()), row(-2, "b", "INSERT", 0, snap3.snapshotId())), changelogRecords(rightAfterSnap2, snap3.timestampMillis()));
    assertEquals("Should have expected changed rows only from snapshot 3", ImmutableList.of(row(2, "b", "DELETE", 0, snap3.snapshotId()), row(-2, "b", "INSERT", 0, snap3.snapshotId())), changelogRecords(snap2.timestampMillis(), snap3.timestampMillis()));
    assertEquals("Should have expected changed rows from snapshot 2 and 3", ImmutableList.of(row(2, "b", "INSERT", 0, snap2.snapshotId()), row(2, "b", "DELETE", 1, snap3.snapshotId()), row(-2, "b", "INSERT", 1, snap3.snapshotId())), changelogRecords(rightAfterSnap1, snap3.timestampMillis()));
    assertEquals("Should have expected changed rows up to the current snapshot", ImmutableList.of(row(2, "b", "INSERT", 0, snap2.snapshotId()), row(2, "b", "DELETE", 1, snap3.snapshotId()), row(-2, "b", "INSERT", 1, snap3.snapshotId())), changelogRecords(rightAfterSnap1, null));
    assertEquals("Should have empty changed rows if end time is before the first snapshot", ImmutableList.of(), changelogRecords(null, snap1.timestampMillis() - 1));
    assertEquals("Should have empty changed rows if start time is after the current snapshot", ImmutableList.of(), changelogRecords(rightAfterSnap3, null));
    assertEquals("Should have empty changed rows if end time is before the first snapshot", ImmutableList.of(), changelogRecords(null, snap1.timestampMillis() - 1));
    assertEquals("Should have empty changed rows if there are no snapshots between start time and end time", ImmutableList.of(), changelogRecords(rightAfterSnap2, snap3.timestampMillis() - 1));
}

