@Test
public void testCherrypickSnapshotUsingPositionalArgs() {
    sql("CREATE TABLE %s (id bigint NOT NULL, data string) USING iceberg", tableName);
    sql("ALTER TABLE %s SET TBLPROPERTIES ('%s' 'true')", tableName, WRITE_AUDIT_PUBLISH_ENABLED);
    spark.conf().set("spark.wap.id", "1");
    sql("INSERT INTO TABLE %s VALUES (1, 'a')", tableName);
    assertEquals("Should not see rows from staged snapshot", ImmutableList.of(), sql("SELECT * FROM %s", tableName));
    Table table = validationCatalog.loadTable(tableIdent);
    Snapshot wapSnapshot = Iterables.getOnlyElement(table.snapshots());
    List<Object[]> output = sql("CALL %s.system.cherrypick_snapshot('%s', %dL)", catalogName, tableIdent, wapSnapshot.snapshotId());
    table.refresh();
    Snapshot currentSnapshot = table.currentSnapshot();
    assertEquals("Procedure output must match", ImmutableList.of(row(wapSnapshot.snapshotId(), currentSnapshot.snapshotId())), output);
    assertEquals("Cherrypick must be successful", ImmutableList.of(row(1L, "a")), sql("SELECT * FROM %s", tableName));
}

