@Test
public void testOverwriteFilterSerializableIsolation() throws Exception {
    Table table = validationCatalog.loadTable(tableIdent);
    long snapshotId = table.currentSnapshot().snapshotId();
    List<SimpleRecord> records = Lists.newArrayList(new SimpleRecord(1, "a"));
    spark.createDataFrame(records, SimpleRecord.class).writeTo(tableName).append();
    // Validating from previous snapshot finds conflicts
    Dataset<Row> conflictingDf = spark.createDataFrame(records, SimpleRecord.class);
    AssertHelpers.assertThrowsCause("Conflicting new data files should throw exception", ValidationException.class, "Found conflicting files that can contain records matching ref(name=\"id\") == 1:", () -> {
        try {
            conflictingDf.writeTo(tableName).option(SparkWriteOptions.VALIDATE_FROM_SNAPSHOT_ID, String.valueOf(snapshotId)).option(SparkWriteOptions.ISOLATION_LEVEL, IsolationLevel.SERIALIZABLE.toString()).overwrite(functions.col("id").equalTo(1));
        } catch (NoSuchTableException e) {
            throw new RuntimeException(e);
        }
    });
    // Validating from latest snapshot should succeed
    table.refresh();
    long newSnapshotId = table.currentSnapshot().snapshotId();
    conflictingDf.writeTo(tableName).option(SparkWriteOptions.VALIDATE_FROM_SNAPSHOT_ID, String.valueOf(newSnapshotId)).option(SparkWriteOptions.ISOLATION_LEVEL, IsolationLevel.SERIALIZABLE.toString()).overwrite(functions.col("id").equalTo(1));
}

