    sql("CALL %s.system.create_changelog_view(table => '%s', " + "options => map('start-snapshot-id','%s'), " + "net_changes => true)", catalogName, tableName, snap1.snapshotId());
    assertEquals("Rows should match", ImmutableList.of(row(2, "b", 11, DELETE, 0, snap2.snapshotId()), row(3, "c", 15, INSERT, 1, snap3.snapshotId())), sql("select * from %s order by _change_ordinal, data", viewName));
}

