    Snapshot currentSnapshot = SnapshotUtil.latestSnapshot(table, branch);
    if (mode(table) == COPY_ON_WRITE) {
        validateCopyOnWrite(currentSnapshot, "3", "4", "1");
    } else {
        validateMergeOnRead(currentSnapshot, "3", "3", null);
    }
