    StatisticsFile statisticsFile1 = writeStatsFile(table.currentSnapshot().snapshotId(), table.currentSnapshot().sequenceNumber(), statsFileLocation1, table.io());
    table.updateStatistics().setStatistics(statisticsFile1.snapshotId(), statisticsFile1).commit();
    sql("INSERT INTO %s SELECT 20, 'def'", tableName);
    table.refresh();
    String statsFileLocation2 = statsFileLocation(table.location());
    StatisticsFile statisticsFile2 = writeStatsFile(table.currentSnapshot().snapshotId(), table.currentSnapshot().sequenceNumber(), statsFileLocation2, table.io());
    table.updateStatistics().setStatistics(statisticsFile2.snapshotId(), statisticsFile2).commit();
    waitUntilAfter(table.currentSnapshot().timestampMillis());
