@Test
public synchronized void testMergeWithSerializableIsolation() throws InterruptedException {
    // cannot run tests with concurrency for Hadoop tables without atomic renames
    Assume.assumeFalse(catalogName.equalsIgnoreCase("testhadoop"));
    createAndInitTable("id INT, dep STRING");
    createOrReplaceView("source", Collections.singletonList(1), Encoders.INT());
    sql("ALTER TABLE %s SET TBLPROPERTIES('%s' '%s')", tableName, MERGE_ISOLATION_LEVEL, "serializable");
    sql("INSERT INTO TABLE %s VALUES (1, 'hr')", tableName);
    createBranchIfNeeded();
    ExecutorService executorService = MoreExecutors.getExitingExecutorService((ThreadPoolExecutor) Executors.newFixedThreadPool(2));
    AtomicInteger barrier = new AtomicInteger(0);
    AtomicBoolean shouldAppend = new AtomicBoolean(true);
    // merge thread
    Future<?> mergeFuture = executorService.submit(() -> {
        for (int numOperations = 0; numOperations < Integer.MAX_VALUE; numOperations++) {
            while (barrier.get() < numOperations * 2) {
                sleep(10);
            }
            sql("MERGE INTO %s t USING source s " + "ON t.id == s.value " + "WHEN MATCHED THEN " + "  UPDATE SET dep = 'x'", commitTarget());
            barrier.incrementAndGet();
        }
    });
    // append thread
    Future<?> appendFuture = executorService.submit(() -> {
        // load the table via the validation catalog to use another table instance
        Table table = validationCatalog.loadTable(tableIdent);
        GenericRecord record = GenericRecord.create(table.schema());
        // id
        record.set(0, 1);
        // dep
        record.set(1, "hr");
        for (int numOperations = 0; numOperations < Integer.MAX_VALUE; numOperations++) {
            while (shouldAppend.get() && barrier.get() < numOperations * 2) {
                sleep(10);
            }
            if (!shouldAppend.get()) {
                return;
            }
            for (int numAppends = 0; numAppends < 5; numAppends++) {
                DataFile dataFile = writeDataFile(table, ImmutableList.of(record));
                AppendFiles appendFiles = table.newFastAppend().appendFile(dataFile);
                if (branch != null) {
                    appendFiles.toBranch(branch);
                }
                appendFiles.commit();
                sleep(10);
            }
            barrier.incrementAndGet();
        }
    });
    try {
        Assertions.assertThatThrownBy(mergeFuture::get).isInstanceOf(ExecutionException.class).cause().isInstanceOf(SparkException.class).cause().isInstanceOf(ValidationException.class).hasMessageContaining("Found conflicting files that can contain");
    } finally {
        shouldAppend.set(false);
        appendFuture.cancel(true);
    }
    executorService.shutdown();
    Assert.assertTrue("Timeout", executorService.awaitTermination(2, TimeUnit.MINUTES));
}

