@Test
public void testMetadataLogEntries() throws Exception {
    // Create table and insert data
    sql("CREATE TABLE %s (id bigint, data string) " + "USING iceberg " + "PARTITIONED BY (data) " + "TBLPROPERTIES " + "('format-version'='2')", tableName);
    List<SimpleRecord> recordsA = Lists.newArrayList(new SimpleRecord(1, "a"), new SimpleRecord(2, "a"));
    spark.createDataset(recordsA, Encoders.bean(SimpleRecord.class)).writeTo(tableName).append();
    List<SimpleRecord> recordsB = Lists.newArrayList(new SimpleRecord(1, "b"), new SimpleRecord(2, "b"));
    spark.createDataset(recordsB, Encoders.bean(SimpleRecord.class)).writeTo(tableName).append();
    Table table = Spark3Util.loadIcebergTable(spark, tableName);
    Long currentSnapshotId = table.currentSnapshot().snapshotId();
    TableMetadata tableMetadata = ((HasTableOperations) table).operations().current();
    Snapshot currentSnapshot = tableMetadata.currentSnapshot();
    Snapshot parentSnapshot = table.snapshot(currentSnapshot.parentId());
    List<TableMetadata.MetadataLogEntry> metadataLogEntries = Lists.newArrayList(tableMetadata.previousFiles());
    // Check metadataLog table
    List<Object[]> metadataLogs = sql("SELECT * FROM %s.metadata_log_entries", tableName);
    assertEquals("MetadataLogEntriesTable result should match the metadataLog entries", ImmutableList.of(row(DateTimeUtils.toJavaTimestamp(metadataLogEntries.get(0).timestampMillis() * 1000), metadataLogEntries.get(0).file(), null, null, null), row(DateTimeUtils.toJavaTimestamp(metadataLogEntries.get(1).timestampMillis() * 1000), metadataLogEntries.get(1).file(), parentSnapshot.snapshotId(), parentSnapshot.schemaId(), parentSnapshot.sequenceNumber()), row(DateTimeUtils.toJavaTimestamp(currentSnapshot.timestampMillis() * 1000), tableMetadata.metadataFileLocation(), currentSnapshot.snapshotId(), currentSnapshot.schemaId(), currentSnapshot.sequenceNumber())), metadataLogs);
    // test filtering
    List<Object[]> metadataLogWithFilters = sql("SELECT * FROM %s.metadata_log_entries WHERE latest_snapshot_id = %s", tableName, currentSnapshotId);
    Assert.assertEquals("metadataLogEntries table should return 1 row", 1, metadataLogWithFilters.size());
    assertEquals("Result should match the latest snapshot entry", ImmutableList.of(row(DateTimeUtils.toJavaTimestamp(tableMetadata.currentSnapshot().timestampMillis() * 1000), tableMetadata.metadataFileLocation(), tableMetadata.currentSnapshot().snapshotId(), tableMetadata.currentSnapshot().schemaId(), tableMetadata.currentSnapshot().sequenceNumber())), metadataLogWithFilters);
    // test projection
    List<String> metadataFiles = metadataLogEntries.stream().map(TableMetadata.MetadataLogEntry::file).collect(Collectors.toList());
    metadataFiles.add(tableMetadata.metadataFileLocation());
    List<Object[]> metadataLogWithProjection = sql("SELECT file FROM %s.metadata_log_entries", tableName);
    Assert.assertEquals("metadataLogEntries table should return 3 rows", 3, metadataLogWithProjection.size());
    assertEquals("metadataLog entry should be of same file", metadataFiles.stream().map(this::row).collect(Collectors.toList()), metadataLogWithProjection);
}

