    df.writeTo(tableName).append();
    long second = table.currentSnapshot().snapshotId();
    Integer minSnapshotsToKeep = 2;
    long maxSnapshotAge = 2;
    long maxRefAge = 10;
    for (String timeUnit : TIME_UNITS) {
        sql("ALTER TABLE %s REPLACE BRANCH %s AS OF VERSION %d RETAIN %d %s WITH SNAPSHOT RETENTION %d SNAPSHOTS %d %s", tableName, branchName, second, maxRefAge, timeUnit, minSnapshotsToKeep, maxSnapshotAge, timeUnit);
        table.refresh();
        SnapshotRef ref = table.refs().get(branchName);
        Assert.assertNotNull(ref);
        Assert.assertEquals(second, ref.snapshotId());
        Assert.assertEquals(minSnapshotsToKeep, ref.minSnapshotsToKeep());
        Assert.assertEquals(TimeUnit.valueOf(timeUnit).toMillis(maxSnapshotAge), ref.maxSnapshotAgeMs().longValue());
        Assert.assertEquals(TimeUnit.valueOf(timeUnit).toMillis(maxRefAge), ref.maxRefAgeMs().longValue());
    }
}

