@Test
public void testRewriteJobOrderBytesAsc() {
    Table table = createTablePartitioned(4, 2);
    writeRecords(1, SCALE, 1);
    writeRecords(2, SCALE, 2);
    writeRecords(3, SCALE, 3);
    writeRecords(4, SCALE, 4);
    table.updateProperties().set(TableProperties.FORMAT_VERSION, "2").commit();
    RewriteDataFilesSparkAction basicRewrite = basicRewrite(table).binPack();
    List<Long> expected = toGroupStream(table, basicRewrite).mapToLong(RewriteFileGroup::sizeInBytes).boxed().collect(Collectors.toList());
    RewriteDataFilesSparkAction jobOrderRewrite = basicRewrite(table).option(RewriteDataFiles.REWRITE_JOB_ORDER, RewriteJobOrder.BYTES_ASC.orderName()).binPack();
    List<Long> actual = toGroupStream(table, jobOrderRewrite).mapToLong(RewriteFileGroup::sizeInBytes).boxed().collect(Collectors.toList());
    expected.sort(Comparator.naturalOrder());
    Assert.assertEquals("Size in bytes order should be ascending", actual, expected);
    Collections.reverse(expected);
    Assert.assertNotEquals("Size in bytes order should not be descending", actual, expected);
}

