@Test
public void testMixDeleteAndInsert() throws IOException {
    table.newAppend().appendFile(dataFile1).commit();
    long snapshotId1 = table.currentSnapshot().snapshotId();
    table.newDelete().deleteFile(dataFile1).commit();
    long snapshotId2 = table.currentSnapshot().snapshotId();
    table.newAppend().appendFile(dataFile2).commit();
    long snapshotId3 = table.currentSnapshot().snapshotId();
    CloseableIterable<ScanTaskGroup<ChangelogScanTask>> taskGroups = newScan().planTasks();
    List<InternalRow> rows = Lists.newArrayList();
    for (ScanTaskGroup<ChangelogScanTask> taskGroup : taskGroups) {
        ChangelogRowReader reader = new ChangelogRowReader(table, taskGroup, table.schema(), table.schema(), false);
        while (reader.next()) {
            rows.add(reader.get().copy());
        }
        reader.close();
    }
    // order by the change ordinal
    rows.sort((r1, r2) -> {
        if (r1.getInt(3) != r2.getInt(3)) {
            return r1.getInt(3) - r2.getInt(3);
        } else {
            return r1.getInt(0) - r2.getInt(0);
        }
    });
    List<Object[]> expectedRows = Lists.newArrayList();
    addExpectedRows(expectedRows, ChangelogOperation.INSERT, snapshotId1, 0, records1);
    addExpectedRows(expectedRows, ChangelogOperation.DELETE, snapshotId2, 1, records1);
    addExpectedRows(expectedRows, ChangelogOperation.INSERT, snapshotId3, 2, records2);
    assertEquals("Should have expected rows", expectedRows, internalRowsToJava(rows));
}

@Test
public void testWriteDataWithDifferentSetting() throws Exception {
    sql("CREATE TABLE %s (id int, data string) USING iceberg", tableName);
    Map<String, String> tableProperties = Maps.newHashMap();
    tableProperties.put(PARQUET_COMPRESSION, "gzip");
    tableProperties.put(AVRO_COMPRESSION, "gzip");
    tableProperties.put(ORC_COMPRESSION, "zlib");
    tableProperties.put(DELETE_PARQUET_COMPRESSION, "gzip");
    tableProperties.put(DELETE_AVRO_COMPRESSION, "gzip");
    tableProperties.put(DELETE_ORC_COMPRESSION, "zlib");
    tableProperties.put(DELETE_MODE, MERGE_ON_READ.modeName());
    tableProperties.put(FORMAT_VERSION, "2");
    sql("ALTER TABLE %s SET TBLPROPERTIES ('%s' '%s')", tableName, DEFAULT_FILE_FORMAT, format);
    sql("ALTER TABLE %s SET TBLPROPERTIES ('%s' '%s')", tableName, DELETE_DEFAULT_FILE_FORMAT, format);
    for (Map.Entry<String, String> entry : tableProperties.entrySet()) {
        sql("ALTER TABLE %s SET TBLPROPERTIES ('%s' '%s')", tableName, entry.getKey(), entry.getValue());
    }
    List<SimpleRecord> expectedOrigin = Lists.newArrayList();
    for (int i = 0; i < 1000; i++) {
        expectedOrigin.add(new SimpleRecord(i, "hello world" + i));
    }
    Dataset<Row> df = spark.createDataFrame(expectedOrigin, SimpleRecord.class);
    for (Map.Entry<String, String> entry : properties.entrySet()) {
        spark.conf().set(entry.getKey(), entry.getValue());
    }
    df.select("id", "data").writeTo(tableName).option(SparkWriteOptions.WRITE_FORMAT, format.toString()).append();
    Table table = catalog.loadTable(TableIdentifier.of("default", tableName));
    List<ManifestFile> manifestFiles = table.currentSnapshot().dataManifests(table.io());
    try (ManifestReader<DataFile> reader = ManifestFiles.read(manifestFiles.get(0), table.io())) {
        DataFile file = reader.iterator().next();
        InputFile inputFile = table.io().newInputFile(file.path().toString());
        Assertions.assertThat(getCompressionType(inputFile)).isEqualToIgnoringCase(properties.get(COMPRESSION_CODEC));
    }
    sql("DELETE from %s where id < 100", tableName);
    table.refresh();
    List<ManifestFile> deleteManifestFiles = table.currentSnapshot().deleteManifests(table.io());
    Map<Integer, PartitionSpec> specMap = Maps.newHashMap();
    specMap.put(0, PartitionSpec.unpartitioned());
    try (ManifestReader<DeleteFile> reader = ManifestFiles.readDeleteManifest(deleteManifestFiles.get(0), table.io(), specMap)) {
        DeleteFile file = reader.iterator().next();
        InputFile inputFile = table.io().newInputFile(file.path().toString());
        Assertions.assertThat(getCompressionType(inputFile)).isEqualToIgnoringCase(properties.get(COMPRESSION_CODEC));
    }
    SparkActions.get(spark).rewritePositionDeletes(table).option(SizeBasedFileRewriter.REWRITE_ALL, "true").execute();
    table.refresh();
    deleteManifestFiles = table.currentSnapshot().deleteManifests(table.io());
    try (ManifestReader<DeleteFile> reader = ManifestFiles.readDeleteManifest(deleteManifestFiles.get(0), table.io(), specMap)) {
        DeleteFile file = reader.iterator().next();
        InputFile inputFile = table.io().newInputFile(file.path().toString());
        Assertions.assertThat(getCompressionType(inputFile)).isEqualToIgnoringCase(properties.get(COMPRESSION_CODEC));
    }
}

