public void testPrimitiveColumns() throws Exception {
    Table table = createPrimitiveTable();
    DataFile dataFile = table.currentSnapshot().addedDataFiles(table.io()).iterator().next();
    Map<Integer, Long> columnSizeStats = dataFile.columnSizes();
    Object[] binaryCol = row(columnSizeStats.get(PRIMITIVE_SCHEMA.findField("binaryCol").fieldId()), 4L, 2L, null, Base64.getDecoder().decode("1111"), Base64.getDecoder().decode("2222"));
    Object[] booleanCol = row(columnSizeStats.get(PRIMITIVE_SCHEMA.findField("booleanCol").fieldId()), 4L, 0L, null, false, true);
    Object[] decimalCol = row(columnSizeStats.get(PRIMITIVE_SCHEMA.findField("decimalCol").fieldId()), 4L, 1L, null, new BigDecimal("1.00"), new BigDecimal("2.00"));
    Object[] doubleCol = row(columnSizeStats.get(PRIMITIVE_SCHEMA.findField("doubleCol").fieldId()), 4L, 0L, 1L, 1.0D, 2.0D);
    Object[] fixedCol = row(columnSizeStats.get(PRIMITIVE_SCHEMA.findField("fixedCol").fieldId()), 4L, 2L, null, Base64.getDecoder().decode("1111"), Base64.getDecoder().decode("2222"));
    Object[] floatCol = row(columnSizeStats.get(PRIMITIVE_SCHEMA.findField("floatCol").fieldId()), 4L, 0L, 2L, 0f, 0f);
