    sql("INSERT INTO TABLE %s VALUES (2, 'c2', 'd2')", tableName);
    assertPartitions(ImmutableList.of(row("d2")), "STRUCT<data:STRING>", PARTITIONS, "partition.data = 'd2'");
    // Partition Table with two partition column
