@Test
public void testPartitionValueTypes() throws Exception {
    String[] columnNames = new String[] { "b", "i", "l", "f", "d", "date", "ts", "s", "bytes", "dec_9_0", "dec_11_2", "dec_38_10" };
    HadoopTables tables = new HadoopTables(spark.sessionState().newHadoopConf());
    // create a table around the source data
    String sourceLocation = temp.newFolder("source_table").toString();
    Table source = tables.create(SUPPORTED_PRIMITIVES, sourceLocation);
    // write out an Avro data file with all of the data types for source data
    List<GenericData.Record> expected = RandomData.generateList(source.schema(), 2, 128735L);
    File avroData = temp.newFile("data.avro");
    Assert.assertTrue(avroData.delete());
    try (FileAppender<GenericData.Record> appender = Avro.write(Files.localOutput(avroData)).schema(source.schema()).build()) {
        appender.addAll(expected);
    }
    // add the Avro data file to the source table
    source.newAppend().appendFile(DataFiles.builder(PartitionSpec.unpartitioned()).withRecordCount(10).withInputFile(Files.localInput(avroData)).build()).commit();
    Dataset<Row> sourceDF = spark.read().format("iceberg").option(SparkReadOptions.VECTORIZATION_ENABLED, String.valueOf(vectorized)).load(sourceLocation);
    for (String column : columnNames) {
        String desc = "partition_by_" + SUPPORTED_PRIMITIVES.findType(column).toString();
        File parent = temp.newFolder(desc);
        File location = new File(parent, "test");
        File dataFolder = new File(location, "data");
        Assert.assertTrue("mkdirs should succeed", dataFolder.mkdirs());
        PartitionSpec spec = PartitionSpec.builderFor(SUPPORTED_PRIMITIVES).identity(column).build();
        Table table = tables.create(SUPPORTED_PRIMITIVES, spec, location.toString());
        table.updateProperties().set(TableProperties.DEFAULT_FILE_FORMAT, format).commit();
        sourceDF.write().format("iceberg").mode(SaveMode.Append).option(SparkWriteOptions.USE_TABLE_DISTRIBUTION_AND_ORDERING, "false").save(location.toString());
        List<Row> actual = spark.read().format("iceberg").option(SparkReadOptions.VECTORIZATION_ENABLED, String.valueOf(vectorized)).load(location.toString()).collectAsList();
        Assert.assertEquals("Number of rows should match", expected.size(), actual.size());
        for (int i = 0; i < expected.size(); i += 1) {
            TestHelpers.assertEqualsSafe(SUPPORTED_PRIMITIVES.asStruct(), expected.get(i), actual.get(i));
        }
    }
}

