    List<Object[]> expected = ImmutableList.of(row(1L, "a"), row(2L, "b"), row(4L, "d"), row(5L, "e"));
    assertEquals("Row data should match expected", expected, sql("SELECT * FROM %s ORDER BY id", selectTarget()));
}

