    Table table = validationCatalog.loadTable(tableIdent);
    sql("INSERT INTO TABLE %s VALUES (1, 'hr')", tableName);
    table.refresh();
    Snapshot firstSnapshot = table.currentSnapshot();
    waitUntilAfter(firstSnapshot.timestampMillis());
    sql("INSERT INTO TABLE %s VALUES (2, 'hr')", tableName);
    table.refresh();
    Snapshot secondSnapshot = table.currentSnapshot();
    waitUntilAfter(secondSnapshot.timestampMillis());
    sql("INSERT INTO TABLE %s VALUES (3, 'hr')", tableName);
    table.refresh();
    try {
        TABLE_CACHE.add("key", table);
        assertEquals("Should have expected rows in 3rd snapshot", ImmutableList.of(row(1, "hr"), row(2, "hr"), row(3, "hr")), sql("SELECT * FROM testcache.key ORDER BY id"));
        assertEquals("Should have expected rows in 2nd snapshot", ImmutableList.of(row(1, "hr"), row(2, "hr")), sql("SELECT * FROM testcache.`key#at_timestamp_%s` ORDER BY id", secondSnapshot.timestampMillis()));
        assertEquals("Should have expected rows in 1st snapshot", ImmutableList.of(row(1, "hr")), sql("SELECT * FROM testcache.`key#snapshot_id_%d` ORDER BY id", firstSnapshot.snapshotId()));
    } finally {
        TABLE_CACHE.remove("key");
    }
}

