    Predicate eqNullSafe2 = new Predicate("<=>", valueAndAttr);
    Expression actualEqNullSafe2 = SparkV2Filters.convert(eqNullSafe2);
    Assertions.assertThat(actualEqNullSafe2.toString()).isEqualTo(expectedEqNullSafe.toString());
}

