@Test
public void addWeirdCaseHiveTable() {
    createWeirdCaseTable();
    String createIceberg = "CREATE TABLE %s (id Integer, `naMe` String, dept String, subdept String) USING iceberg " + "PARTITIONED BY (`naMe`)";
    sql(createIceberg, tableName);
    List<Object[]> result = sql("CALL %s.system.add_files('%s', '%s', map('naMe', 'John Doe'))", catalogName, tableName, sourceTableName);
    assertEquals("Procedure output must match", ImmutableList.of(row(2L, 1L)), result);
    /*
    While we would like to use
    SELECT id, `naMe`, dept, subdept FROM %s WHERE `naMe` = 'John Doe' ORDER BY id
    Spark does not actually handle this pushdown correctly for hive based tables and it returns 0 records
     */
    List<Object[]> expected = sql("SELECT id, `naMe`, dept, subdept from %s ORDER BY id", sourceTableName).stream().filter(r -> r[1].equals("John Doe")).collect(Collectors.toList());
    // TODO when this assert breaks Spark fixed the pushdown issue
    Assert.assertEquals("If this assert breaks it means that Spark has fixed the pushdown issue", 0, sql("SELECT id, `naMe`, dept, subdept from %s WHERE `naMe` = 'John Doe' ORDER BY id", sourceTableName).size());
    // Pushdown works for iceberg
    Assert.assertEquals("We should be able to pushdown mixed case partition keys", 2, sql("SELECT id, `naMe`, dept, subdept FROM %s WHERE `naMe` = 'John Doe' ORDER BY id", tableName).size());
    assertEquals("Iceberg table contains correct data", expected, sql("SELECT id, `naMe`, dept, subdept FROM %s ORDER BY id", tableName));
}

