@Test
public void testSetIdentifierFields() {
    sql("CREATE TABLE %s (id bigint NOT NULL, " + "location struct<lon:bigint NOT NULL,lat:bigint NOT NULL> NOT NULL) USING iceberg", tableName);
    Table table = validationCatalog.loadTable(tableIdent);
    Assert.assertTrue("Table should start without identifier", table.schema().identifierFieldIds().isEmpty());
    sql("ALTER TABLE %s SET IDENTIFIER FIELDS id", tableName);
    table.refresh();
    Assert.assertEquals("Should have new identifier field", Sets.newHashSet(table.schema().findField("id").fieldId()), table.schema().identifierFieldIds());
    sql("ALTER TABLE %s SET IDENTIFIER FIELDS id, location.lon", tableName);
