    Assert.assertEquals("Should have new identifier field", Sets.newHashSet(table.schema().findField("id").fieldId(), table.schema().findField("location.lon").fieldId()), table.schema().identifierFieldIds());
    sql("ALTER TABLE %s SET IDENTIFIER FIELDS location.lon", tableName);
    table.refresh();
    Assert.assertEquals("Should have new identifier field", Sets.newHashSet(table.schema().findField("location.lon").fieldId()), table.schema().identifierFieldIds());
}

