    // query the timestamps starting from the second insert
    returns = sql("CALL %s.system.create_changelog_view(table => '%s', " + "options => map('%s', '%s', '%s', '%s'))", catalogName, tableName, SparkReadOptions.START_TIMESTAMP, afterFirstInsert, SparkReadOptions.END_TIMESTAMP, afterInsertOverwrite);
    assertEquals("Rows should match", ImmutableList.of(row(2, "b", INSERT, 0, snap1.snapshotId()), row(-2, "b", INSERT, 1, snap2.snapshotId()), row(2, "b", DELETE, 1, snap2.snapshotId())), sql("select * from %s order by _change_ordinal, id", returns.get(0)[0]));
}

