    createAndInitTable("id INT, dep STRING", "{ \"id\": 1, \"dep\": \"emp-id-one\" }\n" + "{ \"id\": 6, \"dep\": \"emp-id-6\" }");
    createOrReplaceView("source", "id INT, dep STRING", "{ \"id\": 1, \"dep\": \"emp-id-1\" }\n" + "{ \"id\": 1, \"dep\": \"emp-id-1\" }\n" + "{ \"id\": 2, \"dep\": \"emp-id-2\" }\n" + "{ \"id\": 6, \"dep\": \"emp-id-6\" }");
    String errorMsg = "a single row from the target table with multiple rows of the source table";
    AssertHelpers.assertThrowsCause("Should complain about multiple matches", SparkException.class, errorMsg, () -> {
        sql("MERGE INTO %s AS t USING source AS s " + "ON t.id == s.id " + "WHEN MATCHED AND t.id = 1 THEN " + "  DELETE " + "WHEN NOT MATCHED AND s.id = 2 THEN " + "  INSERT *", commitTarget());
    });
    assertEquals("Target should be unchanged", ImmutableList.of(row(1, "emp-id-one"), row(6, "emp-id-6")), sql("SELECT * FROM %s ORDER BY id ASC NULLS LAST", selectTarget()));
}

