    sql("UPDATE %s t SET dep = 'x', id = -1 WHERE " + "EXISTS (SELECT 1 FROM updated_id u WHERE t.id = u.value + 2)", commitTarget());
    assertEquals("Should have expected rows", ImmutableList.of(row(-1, "x"), row(2, "hardware"), row(null, "hr")), sql("SELECT * FROM %s ORDER BY id ASC NULLS LAST", selectTarget()));
    sql("UPDATE %s t SET id = -2 WHERE " + "EXISTS (SELECT 1 FROM updated_id u WHERE t.id = u.value) OR " + "t.id IS NULL", commitTarget());
    assertEquals("Should have expected rows", ImmutableList.of(row(-2, "hr"), row(-2, "x"), row(2, "hardware")), sql("SELECT * FROM %s ORDER BY id, dep", selectTarget()));
    sql("UPDATE %s t SET id = 1 WHERE " + "EXISTS (SELECT 1 FROM updated_id ui WHERE t.id = ui.value) AND " + "EXISTS (SELECT 1 FROM updated_dep ud WHERE t.dep = ud.value)", commitTarget());
    assertEquals("Should have expected rows", ImmutableList.of(row(-2, "x"), row(1, "hr"), row(2, "hardware")), sql("SELECT * FROM %s ORDER BY id, dep", selectTarget()));
}

