    for (SimpleRecord record : expectedRecords) {
        Dataset<Row> originalDf = spark.createDataFrame(Lists.newArrayList(record), SimpleRecord.class);
        originalDf.select("id", "data").write().format("iceberg").mode("append").save(tableLocation);
    }
    List<Long> snapshotIds = SnapshotUtil.currentAncestorIds(table);
    // start-snapshot-id and snapshot-id are both configured.
    Assertions.assertThatThrownBy(() -> spark.read().format("iceberg").option("snapshot-id", snapshotIds.get(3).toString()).option("start-snapshot-id", snapshotIds.get(3).toString()).load(tableLocation).explain()).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot set start-snapshot-id and end-snapshot-id for incremental scans when either snapshot-id or as-of-timestamp is set");
    // end-snapshot-id and as-of-timestamp are both configured.
    Assertions.assertThatThrownBy(() -> spark.read().format("iceberg").option(SparkReadOptions.AS_OF_TIMESTAMP, Long.toString(table.snapshot(snapshotIds.get(3)).timestampMillis())).option("end-snapshot-id", snapshotIds.get(2).toString()).load(tableLocation).explain()).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot set start-snapshot-id and end-snapshot-id for incremental scans when either snapshot-id or as-of-timestamp is set");
    // only end-snapshot-id is configured.
    Assertions.assertThatThrownBy(() -> spark.read().format("iceberg").option("end-snapshot-id", snapshotIds.get(2).toString()).load(tableLocation).explain()).isInstanceOf(IllegalArgumentException.class).hasMessage("Cannot set only end-snapshot-id for incremental scans. Please, set start-snapshot-id too.");
    // test (1st snapshot, current snapshot] incremental scan.
    List<SimpleRecord> result = spark.read().format("iceberg").option("start-snapshot-id", snapshotIds.get(3).toString()).load(tableLocation).orderBy("id").as(Encoders.bean(SimpleRecord.class)).collectAsList();
    Assert.assertEquals("Records should match", expectedRecords.subList(1, 4), result);
    // test (2nd snapshot, 3rd snapshot] incremental scan.
    Dataset<Row> resultDf = spark.read().format("iceberg").option("start-snapshot-id", snapshotIds.get(2).toString()).option("end-snapshot-id", snapshotIds.get(1).toString()).load(tableLocation);
    List<SimpleRecord> result1 = resultDf.orderBy("id").as(Encoders.bean(SimpleRecord.class)).collectAsList();
    Assert.assertEquals("Records should match", expectedRecords.subList(2, 3), result1);
    Assert.assertEquals("Unprocessed count should match record count", 1, resultDf.count());
}

