    String baseLocation = temp.newFolder("partition_by_nested_string").toString();
    tables.create(nestedSchema, spec, baseLocation);
    // input data frame
    StructField[] structFields = { new StructField("struct", DataTypes.createStructType(new StructField[] { new StructField("string", DataTypes.StringType, false, Metadata.empty()) }), false, Metadata.empty()) };
