    sql("CREATE TABLE %s (id BIGINT) USING iceberg TBLPROPERTIES ('format-version'='2')", tableName);
    spark.range(10000).coalesce(1).writeTo(tableName).append();
    spark.range(10001, 20000).coalesce(1).writeTo(tableName).append();
    Dataset<Row> df = spark.sql(String.format("select * from %s where id < 10000", tableName));
    df.collect();
    List<SparkPlan> sparkPlans = seqAsJavaListConverter(df.queryExecution().executedPlan().collectLeaves()).asJava();
    Map<String, SQLMetric> metricsMap = JavaConverters.mapAsJavaMapConverter(sparkPlans.get(0).metrics()).asJava();
    Assertions.assertThat(metricsMap.get("skippedDataFiles").value()).isEqualTo(1);
    Assertions.assertThat(metricsMap.get("scannedDataManifests").value()).isEqualTo(2);
    Assertions.assertThat(metricsMap.get("scannedDataFiles").value()).isEqualTo(1);
    Assertions.assertThat(metricsMap.get("skippedDataManifests").value()).isEqualTo(0);
    Assertions.assertThat(metricsMap.get("totalFileSize").value()).isNotEqualTo(0);
    Assertions.assertThat(metricsMap.get("totalPlanningDuration").value()).isNotEqualTo(0);
}

@Test
public void testReadMetricsForV2Table() throws NoSuchTableException {
    sql("CREATE TABLE %s (id BIGINT) USING iceberg TBLPROPERTIES ('format-version'='2')", tableName);
    spark.range(10000).coalesce(1).writeTo(tableName).append();
    spark.range(10001, 20000).coalesce(1).writeTo(tableName).append();
    Dataset<Row> df = spark.sql(String.format("select * from %s where id < 10000", tableName));
    df.collect();
    List<SparkPlan> sparkPlans = seqAsJavaListConverter(df.queryExecution().executedPlan().collectLeaves()).asJava();
    Map<String, SQLMetric> metricsMap = JavaConverters.mapAsJavaMapConverter(sparkPlans.get(0).metrics()).asJava();
    Assertions.assertThat(metricsMap.get("skippedDataFiles").value()).isEqualTo(1);
    Assertions.assertThat(metricsMap.get("scannedDataManifests").value()).isEqualTo(2);
    Assertions.assertThat(metricsMap.get("scannedDataFiles").value()).isEqualTo(1);
    Assertions.assertThat(metricsMap.get("skippedDataManifests").value()).isEqualTo(0);
    Assertions.assertThat(metricsMap.get("totalFileSize").value()).isNotEqualTo(0);
    Assertions.assertThat(metricsMap.get("totalPlanningDuration").value()).isNotEqualTo(0);
}

@Test
public void testEstimatedRowCount() throws NoSuchTableException {
    sql("CREATE TABLE %s (id BIGINT, date DATE) USING iceberg TBLPROPERTIES('%s' = '%s')", tableName, TableProperties.DEFAULT_FILE_FORMAT, format);
    Dataset<Row> df = spark.range(10000).withColumn("date", date_add(expr("DATE '1970-01-01'"), expr("CAST(id AS INT)"))).select("id", "date");
    df.coalesce(1).writeTo(tableName).append();
    Table table = validationCatalog.loadTable(tableIdent);
    SparkScanBuilder scanBuilder = new SparkScanBuilder(spark, table, CaseInsensitiveStringMap.empty());
    SparkScan scan = (SparkScan) scanBuilder.build();
    Statistics stats = scan.estimateStatistics();
    Assert.assertEquals(10000L, stats.numRows().getAsLong());
}

