@Test
public void testTaskSetLoading() throws NoSuchTableException, IOException {
    sql("CREATE TABLE %s (id INT, data STRING) USING iceberg", tableName);
    List<SimpleRecord> records = ImmutableList.of(new SimpleRecord(1, "a"), new SimpleRecord(2, "b"));
    Dataset<Row> df = spark.createDataFrame(records, SimpleRecord.class);
    df.writeTo(tableName).append();
    Table table = validationCatalog.loadTable(tableIdent);
    Assert.assertEquals("Should produce 1 snapshot", 1, Iterables.size(table.snapshots()));
    try (CloseableIterable<FileScanTask> fileScanTasks = table.newScan().planFiles()) {
        ScanTaskSetManager taskSetManager = ScanTaskSetManager.get();
        String setID = UUID.randomUUID().toString();
        taskSetManager.stageTasks(table, setID, ImmutableList.copyOf(fileScanTasks));
        // load the staged file set
        Dataset<Row> scanDF = spark.read().format("iceberg").option(SparkReadOptions.SCAN_TASK_SET_ID, setID).load(tableName);
        // write the records back essentially duplicating data
        scanDF.writeTo(tableName).append();
    }
    assertEquals("Should have expected rows", ImmutableList.of(row(1, "a"), row(1, "a"), row(2, "b"), row(2, "b")), sql("SELECT * FROM %s ORDER BY id", tableName));
}

@Test
public void testTaskSetPlanning() throws NoSuchTableException, IOException {
    sql("CREATE TABLE %s (id INT, data STRING) USING iceberg", tableName);
    List<SimpleRecord> records = ImmutableList.of(new SimpleRecord(1, "a"), new SimpleRecord(2, "b"));
    Dataset<Row> df = spark.createDataFrame(records, SimpleRecord.class);
    df.coalesce(1).writeTo(tableName).append();
    df.coalesce(1).writeTo(tableName).append();
    Table table = validationCatalog.loadTable(tableIdent);
    Assert.assertEquals("Should produce 2 snapshots", 2, Iterables.size(table.snapshots()));
    try (CloseableIterable<FileScanTask> fileScanTasks = table.newScan().planFiles()) {
        ScanTaskSetManager taskSetManager = ScanTaskSetManager.get();
        String setID = UUID.randomUUID().toString();
        List<FileScanTask> tasks = ImmutableList.copyOf(fileScanTasks);
        taskSetManager.stageTasks(table, setID, tasks);
        // load the staged file set and make sure each file is in a separate split
        Dataset<Row> scanDF = spark.read().format("iceberg").option(SparkReadOptions.SCAN_TASK_SET_ID, setID).option(SparkReadOptions.SPLIT_SIZE, tasks.get(0).file().fileSizeInBytes()).load(tableName);
        Assert.assertEquals("Num partitions should match", 2, scanDF.javaRDD().getNumPartitions());
        // load the staged file set and make sure we combine both files into a single split
        scanDF = spark.read().format("iceberg").option(SparkReadOptions.SCAN_TASK_SET_ID, setID).option(SparkReadOptions.SPLIT_SIZE, Long.MAX_VALUE).load(tableName);
        Assert.assertEquals("Num partitions should match", 1, scanDF.javaRDD().getNumPartitions());
    }
}

@Test
public void testTableEquality() throws NoSuchTableException {
    CatalogManager catalogManager = spark.sessionState().catalogManager();
    TableCatalog catalog = (TableCatalog) catalogManager.catalog(catalogName);
    Identifier identifier = Identifier.of(tableIdent.namespace().levels(), tableIdent.name());
    SparkTable table1 = (SparkTable) catalog.loadTable(identifier);
    SparkTable table2 = (SparkTable) catalog.loadTable(identifier);
    // different instances pointing to the same table must be equivalent
    Assert.assertNotSame("References must be different", table1, table2);
    Assert.assertEquals("Tables must be equivalent", table1, table2);
}

