@Test
public void testCreateRTASWithPartitionSpecChanging() {
    sql("CREATE OR REPLACE TABLE %s USING iceberg PARTITIONED BY (part) AS " + "SELECT id, data, CASE WHEN (id %% 2) = 0 THEN 'even' ELSE 'odd' END AS part " + "FROM %s ORDER BY 3, 1", tableName, sourceName);
    Table rtasTable = validationCatalog.loadTable(tableIdent);
    assertEquals("Should have rows matching the source table", sql("SELECT id, data, CASE WHEN (id %% 2) = 0 THEN 'even' ELSE 'odd' END AS part " + "FROM %s ORDER BY id", sourceName), sql("SELECT * FROM %s ORDER BY id", tableName));
    // Change the partitioning of the table
    // Spec 1
    rtasTable.updateSpec().removeField("part").commit();
    sql("CREATE OR REPLACE TABLE %s USING iceberg PARTITIONED BY (part, id) AS " + "SELECT 2 * id as id, data, CASE WHEN ((2 * id) %% 2) = 0 THEN 'even' ELSE 'odd' END AS part " + "FROM %s ORDER BY 3, 1", tableName, sourceName);
    Schema expectedSchema = new Schema(Types.NestedField.optional(1, "id", Types.LongType.get()), Types.NestedField.optional(2, "data", Types.StringType.get()), Types.NestedField.optional(3, "part", Types.StringType.get()));
    PartitionSpec expectedSpec = PartitionSpec.builderFor(expectedSchema).identity("part").identity("id").withSpecId(// The Spec is new
    2).build();
    Assert.assertEquals("Should be partitioned by part and id", expectedSpec, rtasTable.spec());
    // the replacement table has a different schema and partition spec than the original
    Assert.assertEquals("Should have expected nullable schema", expectedSchema.asStruct(), rtasTable.schema().asStruct());
    assertEquals("Should have rows matching the source table", sql("SELECT 2 * id, data, CASE WHEN ((2 * id) %% 2) = 0 THEN 'even' ELSE 'odd' END AS part " + "FROM %s ORDER BY id", sourceName), sql("SELECT * FROM %s ORDER BY id", tableName));
    Assert.assertEquals("Table should have expected snapshots", 2, Iterables.size(rtasTable.snapshots()));
}

@Test
public void testDeleteFromUnpartitionedTable() throws NoSuchTableException {
    sql("CREATE TABLE %s (id bigint, data string) USING iceberg", tableName);
    List<SimpleRecord> records = Lists.newArrayList(new SimpleRecord(1, "a"), new SimpleRecord(2, "b"), new SimpleRecord(3, "c"));
    Dataset<Row> df = spark.createDataFrame(records, SimpleRecord.class);
    df.coalesce(1).writeTo(tableName).append();
    assertEquals("Should have expected rows", ImmutableList.of(row(1L, "a"), row(2L, "b"), row(3L, "c")), sql("SELECT * FROM %s ORDER BY id", tableName));
    sql("DELETE FROM %s WHERE id < 2", tableName);
    assertEquals("Should have no rows after successful delete", ImmutableList.of(row(2L, "b"), row(3L, "c")), sql("SELECT * FROM %s ORDER BY id", tableName));
    sql("DELETE FROM %s WHERE id < 4", tableName);
    assertEquals("Should have no rows after successful delete", ImmutableList.of(), sql("SELECT * FROM %s ORDER BY id", tableName));
}

@Test
public void testDeleteFromTableAtSnapshot() throws NoSuchTableException {
    sql("CREATE TABLE %s (id bigint, data string) USING iceberg", tableName);
    List<SimpleRecord> records = Lists.newArrayList(new SimpleRecord(1, "a"), new SimpleRecord(2, "b"), new SimpleRecord(3, "c"));
    Dataset<Row> df = spark.createDataFrame(records, SimpleRecord.class);
    df.coalesce(1).writeTo(tableName).append();
    long snapshotId = validationCatalog.loadTable(tableIdent).currentSnapshot().snapshotId();
    String prefix = "snapshot_id_";
    Assertions.assertThatThrownBy(() -> sql("DELETE FROM %s.%s WHERE id < 4", tableName, prefix + snapshotId)).isInstanceOf(IllegalArgumentException.class).hasMessageStartingWith("Cannot delete from table at a specific snapshot");
}

@Test
public void testDeleteFromPartitionedTable() throws NoSuchTableException {
    sql("CREATE TABLE %s (id bigint, data string) " + "USING iceberg " + "PARTITIONED BY (truncate(id, 2))", tableName);
    List<SimpleRecord> records = Lists.newArrayList(new SimpleRecord(1, "a"), new SimpleRecord(2, "b"), new SimpleRecord(3, "c"));
    Dataset<Row> df = spark.createDataFrame(records, SimpleRecord.class);
    df.coalesce(1).writeTo(tableName).append();
    assertEquals("Should have 3 rows in 2 partitions", ImmutableList.of(row(1L, "a"), row(2L, "b"), row(3L, "c")), sql("SELECT * FROM %s ORDER BY id", tableName));
    sql("DELETE FROM %s WHERE id > 2", tableName);
    assertEquals("Should have two rows in the second partition", ImmutableList.of(row(1L, "a"), row(2L, "b")), sql("SELECT * FROM %s ORDER BY id", tableName));
    sql("DELETE FROM %s WHERE id < 2", tableName);
    assertEquals("Should have two rows in the second partition", ImmutableList.of(row(2L, "b")), sql("SELECT * FROM %s ORDER BY id", tableName));
}

