    // This situation is atypical but allowed. Typically, width is static as data is partitioned on
    // one width.
    long rumRows = 10L;
    long numNonZero = spark.range(rumRows).toDF("value").selectExpr("CAST(value + 1 AS INT) AS width", "value").selectExpr("system.truncate(width, value) as truncated_value").filter("truncated_value == 0").count();
    Assert.assertEquals("A truncate function with variable widths should be usable on dataframe columns", rumRows, numNonZero);
}

