@Test
public void testMagicFunctionsResolveForTinyIntAndSmallIntWidths() {
    // Magic functions have staticinvoke in the explain output. Nonmagic calls use
    // applyfunctionexpression instead.
    String tinyIntWidthExplain = (String) scalarSql("EXPLAIN EXTENDED SELECT system.truncate(1Y, 6)");
    Assertions.assertThat(tinyIntWidthExplain).contains("cast(1 as int)").contains("staticinvoke(class org.apache.iceberg.spark.functions.TruncateFunction$TruncateInt");
    String smallIntWidth = (String) scalarSql("EXPLAIN EXTENDED SELECT system.truncate(5S, 6L)");
    Assertions.assertThat(smallIntWidth).contains("cast(5 as int)").contains("staticinvoke(class org.apache.iceberg.spark.functions.TruncateFunction$TruncateBigInt");
}

