    withSQLConf(ImmutableMap.of(SQLConf.SHUFFLE_PARTITIONS().key(), "200", SQLConf.AUTO_BROADCASTJOIN_THRESHOLD().key(), "-1", SQLConf.ADAPTIVE_EXECUTION_ENABLED().key(), "true", SQLConf.COALESCE_PARTITIONS_ENABLED().key(), "true", SQLConf.ADVISORY_PARTITION_SIZE_IN_BYTES().key(), "100", SparkSQLProperties.ADVISORY_PARTITION_SIZE, String.valueOf(256 * 1024 * 1024)), () -> {
