    String query = String.format("MERGE INTO %s AS t USING source AS s " + "ON t.id == s.id AND ((t.dep = 'd1' AND t.sub_dep IN ('sd1', 'sd3')) OR (t.dep = 'd6' AND t.sub_dep IN ('sd2', 'sd6'))) " + "WHEN MATCHED THEN " + "  UPDATE SET salary = s.salary " + "WHEN NOT MATCHED THEN " + "  INSERT *", commitTarget());
    Table table = validationCatalog.loadTable(tableIdent);
    if (mode(table) == COPY_ON_WRITE) {
        checkJoinAndFilterConditions(query, "Join [id], [id], FullOuter", "((dep = 'd1' AND sub_dep IN ('sd1', 'sd3')) OR (dep = 'd6' AND sub_dep IN ('sd2', 'sd6')))");
    } else {
        checkJoinAndFilterConditions(query, "Join [id], [id], RightOuter", "((dep = 'd1' AND sub_dep IN ('sd1', 'sd3')) OR (dep = 'd6' AND sub_dep IN ('sd2', 'sd6')))");
    }
    assertEquals("Should have expected rows", ImmutableList.of(// updated
    row(1, 101, "d1", "sd1"), // new
    row(2, 200, "d2", "sd2"), // new
    row(3, 300, "d3", "sd3"), // existing
    row(6, 600, "d6", "sd6")), sql("SELECT * FROM %s ORDER BY id", selectTarget()));
}

@Test
public void testMergeWithStaticPredicatePushDown() {
    createAndInitTable("id BIGINT, dep STRING");
    sql("ALTER TABLE %s ADD PARTITION FIELD dep", tableName);
    // add a data file to the 'software' partition
    append(tableName, "{ \"id\": 1, \"dep\": \"software\" }");
    createBranchIfNeeded();
    // add a data file to the 'hr' partition
    append(commitTarget(), "{ \"id\": 1, \"dep\": \"hr\" }");
    Table table = validationCatalog.loadTable(tableIdent);
    Snapshot snapshot = SnapshotUtil.latestSnapshot(table, branch);
    String dataFilesCount = snapshot.summary().get(SnapshotSummary.TOTAL_DATA_FILES_PROP);
    Assert.assertEquals("Must have 2 files before MERGE", "2", dataFilesCount);
    createOrReplaceView("source", "{ \"id\": 1, \"dep\": \"finance\" }\n" + "{ \"id\": 2, \"dep\": \"hardware\" }");
    // remove the data file from the 'hr' partition to ensure it is not scanned
    withUnavailableFiles(snapshot.addedDataFiles(table.io()), () -> {
        // disable dynamic pruning and rely only on static predicate pushdown
        withSQLConf(ImmutableMap.of(SQLConf.DYNAMIC_PARTITION_PRUNING_ENABLED().key(), "false", SQLConf.RUNTIME_ROW_LEVEL_OPERATION_GROUP_FILTER_ENABLED().key(), "false"), () -> {
            sql("MERGE INTO %s t USING source " + "ON t.id == source.id AND t.dep IN ('software') AND source.id < 10 " + "WHEN MATCHED AND source.id = 1 THEN " + "  UPDATE SET dep = source.dep " + "WHEN NOT MATCHED THEN " + "  INSERT (dep, id) VALUES (source.dep, source.id)", commitTarget());
        });
    });
    ImmutableList<Object[]> expectedRows = ImmutableList.of(// updated
    row(1L, "finance"), // kept
    row(1L, "hr"), // new
    row(2L, "hardware"));
    assertEquals("Output should match", expectedRows, sql("SELECT * FROM %s ORDER BY id, dep", selectTarget()));
}

