public void testMergeWithSubqueriesInConditions() {
    createAndInitTable("id INT, c STRUCT<n1:INT,n2:STRUCT<dn1:INT,dn2:INT>>", "{ \"id\": 1, \"c\": { \"n1\": 2, \"n2\": { \"dn1\": 3, \"dn2\": 4 } } }");
    createOrReplaceView("source", "{ \"c1\": -100, \"c2\": -200 }");
    AssertHelpers.assertThrows("Should complain about subquery expressions", AnalysisException.class, "MERGE operation contains unsupported SEARCH condition. Subqueries are not allowed", () -> {
        sql("MERGE INTO %s t USING source s " + "ON t.id == s.c1 AND t.id < (SELECT max(c2) FROM source) " + "WHEN MATCHED THEN " + "  UPDATE SET t.c.n1 = s.c2", commitTarget());
    });
    AssertHelpers.assertThrows("Should complain about subquery expressions", AnalysisException.class, "MERGE operation contains unsupported UPDATE condition. Subqueries are not allowed", () -> {
        sql("MERGE INTO %s t USING source s " + "ON t.id == s.c1 " + "WHEN MATCHED AND t.id < (SELECT max(c2) FROM source) THEN " + "  UPDATE SET t.c.n1 = s.c2", commitTarget());
    });
    AssertHelpers.assertThrows("Should complain about subquery expressions", AnalysisException.class, "MERGE operation contains unsupported DELETE condition. Subqueries are not allowed", () -> {
        sql("MERGE INTO %s t USING source s " + "ON t.id == s.c1 " + "WHEN MATCHED AND t.id NOT IN (SELECT c2 FROM source) THEN " + "  DELETE", commitTarget());
    });
    AssertHelpers.assertThrows("Should complain about subquery expressions", AnalysisException.class, "MERGE operation contains unsupported INSERT condition. Subqueries are not allowed", () -> {
        sql("MERGE INTO %s t USING source s " + "ON t.id == s.c1 " + "WHEN NOT MATCHED AND s.c1 IN (SELECT c2 FROM source) THEN " + "  INSERT (id, c) VALUES (1, null)", commitTarget());
    });
}

