@Test
public void testUpdateToWAPBranch() {
    Assume.assumeTrue("WAP branch only works for table identifier without branch", branch == null);
    createAndInitTable("id INT, dep STRING", "{ \"id\": 1, \"dep\": \"hr\" }\n" + "{ \"id\": 2, \"dep\": \"a\" }");
    sql("ALTER TABLE %s SET TBLPROPERTIES ('%s' = 'true')", tableName, TableProperties.WRITE_AUDIT_PUBLISH_ENABLED);
    withSQLConf(ImmutableMap.of(SparkSQLProperties.WAP_BRANCH, "wap"), () -> {
        sql("UPDATE %s SET dep='hr' WHERE dep='a'", tableName);
        Assert.assertEquals("Should have expected num of rows when reading table", 2L, sql("SELECT * FROM %s WHERE dep='hr'", tableName).size());
        Assert.assertEquals("Should have expected num of rows when reading WAP branch", 2L, sql("SELECT * FROM %s.branch_wap WHERE dep='hr'", tableName).size());
        Assert.assertEquals("Should not modify main branch", 1L, sql("SELECT * FROM %s.branch_main WHERE dep='hr'", tableName).size());
    });
    withSQLConf(ImmutableMap.of(SparkSQLProperties.WAP_BRANCH, "wap"), () -> {
        sql("UPDATE %s SET dep='b' WHERE dep='hr'", tableName);
        Assert.assertEquals("Should have expected num of rows when reading table with multiple writes", 2L, sql("SELECT * FROM %s WHERE dep='b'", tableName).size());
        Assert.assertEquals("Should have expected num of rows when reading WAP branch with multiple writes", 2L, sql("SELECT * FROM %s.branch_wap WHERE dep='b'", tableName).size());
        Assert.assertEquals("Should not modify main branch with multiple writes", 0L, sql("SELECT * FROM %s.branch_main WHERE dep='b'", tableName).size());
    });
}

