@Test
public void testGettingStarted() throws IOException {
    // Creating a table
    sql("CREATE TABLE %s (id bigint, data string) USING iceberg", tableName);
    // Writing
    sql("INSERT INTO %s VALUES (1, 'a'), (2, 'b'), (3, 'c')", tableName);
    Assert.assertEquals("Should have inserted 3 rows", 3L, scalarSql("SELECT COUNT(*) FROM %s", tableName));
    sql("DROP TABLE IF EXISTS source PURGE");
    sql("CREATE TABLE source (id bigint, data string) USING parquet LOCATION '%s'", temp.newFolder());
    sql("INSERT INTO source VALUES (10, 'd'), (11, 'ee')");
    sql("INSERT INTO %s SELECT id, data FROM source WHERE length(data) = 1", tableName);
    Assert.assertEquals("Table should now have 4 rows", 4L, scalarSql("SELECT COUNT(*) FROM %s", tableName));
    sql("DROP TABLE IF EXISTS updates PURGE");
    sql("CREATE TABLE updates (id bigint, data string) USING parquet LOCATION '%s'", temp.newFolder());
    sql("INSERT INTO updates VALUES (1, 'x'), (2, 'x'), (4, 'z')");
    sql("MERGE INTO %s t USING (SELECT * FROM updates) u ON t.id = u.id\n" + "WHEN MATCHED THEN UPDATE SET t.data = u.data\n" + "WHEN NOT MATCHED THEN INSERT *", tableName);
    Assert.assertEquals("Table should now have 5 rows", 5L, scalarSql("SELECT COUNT(*) FROM %s", tableName));
    Assert.assertEquals("Record 1 should now have data x", "x", scalarSql("SELECT data FROM %s WHERE id = 1", tableName));
    // Reading
    Assert.assertEquals("There should be 2 records with data x", 2L, scalarSql("SELECT count(1) as count FROM %s WHERE data = 'x' GROUP BY data ", tableName));
    // Not supported because of Spark limitation
    if (!catalogName.equals("spark_catalog")) {
        Assert.assertEquals("There should be 3 snapshots", 3L, scalarSql("SELECT COUNT(*) FROM %s.snapshots", tableName));
    }
}

